            },
            {
              "type": "DRUG",
              "name": "Docetaxel injection",
              "description": "Docetaxel, is an anti-tumor drug, significantly reduces the number of free tubules by promoting tubule polymerization into stable microtubules and inhibiting their depolymerization.",
              "armGroupLabels": [
