        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Progression-free survival (PFS)",
              "description": "Time from subject randomization (first treatment) to first disease progression or death from any cause, whichever occurred first, was assessed by an independent Review Committee (IRC) per Response evaluation criteria in solid tumors (RECIST) 1.1.",
              "timeFrame": "Baseline up to 3 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Overall survival (OS)",
              "description": "From randomization to the time of death from any cause.",
              "timeFrame": "Baseline up to 3 years"
            },
            {
              "measure": "Objective mitigation rate (ORR)",
              "description": "According to RECIST 1.1 criteria, proportion of patients with confirmed tumor volume reduction to pre-specified values and maintained minimum requirements\n\n, namely the proportion of patients with complete response (CR) and partial response (PR).",
              "timeFrame": "Baseline up to 3 years"
            },
            {
              "measure": "Duration of Response (DOR)",
              "description": "From the time of tumor first evaluated as complete or partial response to the time of first disease progression or death from various causes.",
              "timeFrame": "Baseline up to 3 years"
            },
            {
              "measure": "Disease control rate (DCR)",
              "description": "According to RECIST 1.1 criteria, proportion of patients with confirmed tumor volume reduction to pre-specified values and maintained minimum requirements\n\n, namely the proportion of patients with CR, PR and stable disease (SD).",
              "timeFrame": "Baseline up to 3 years"
            },
            {
              "measure": "Time to response (TTR)",
              "description": "Time from patient randomization (first treatment) to first response per RECIST 1.1 criteria",
              "timeFrame": "Baseline up to 3 years"
            },
            {
              "measure": "Patient-reported outcome (PRO)",
              "description": "Reports of their health status directly from patients",
              "timeFrame": "Baseline up to 3 years"
            },
            {
              "measure": "Abnormal laboratory test indicators",
              "description": "The occurrence of laboratory test indicators exceed the normal range",
              "timeFrame": "From the subject signed the informed consent form to 30 days after the last dose"
            },
            {
              "measure": "Adverse event rate",
              "description": "The occurrence of all adverse events (AEs), serious adverse events (SAEs) and treatment-related adverse events (TEAEs)",
              "timeFrame": "From the subject signed the informed consent form to 30 days after the last dose"
            },
            {
              "measure": "Time to Maximum Plasma Concentration (Tmax)",
              "description": "Time to maximum plasma concentration after dosing",
              "timeFrame": "Pre-dose and 2 hours after D1553 administration on Day 1 of cycle 1 and cycle 3. Each cycle is 21 days."
            },
            {
              "measure": "Half life (t1/2)",
              "description": "Time required for plasma concentrations to drop by half",
              "timeFrame": "Pre-dose and 2 hours after D1553 administration on Day 1 of cycle 1 and cycle 3. Each cycle is 21 days."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Voluntary participation in the study and sign of written informed consent after full informed consent, willing and able to comply with the study procedures and requirements specified in the protocol;\n* Age greater than or equal to 18 years old; male and female; eastern cooperative oncology group performance status (ECOG) score 0-1; expected survival period greater than or equal to 3 months;\n* Pathologically confirmed locally advanced, unresectable and / or metastatic non-small cell lung cancer (stage III b / III c / IV of american joint committee on cancer (AJCC) 8th);\n* Subjects must provide adequate and qualified tumor tissue specimens (surgical resection samples or puncture / biopsy tissue samples within 2 years prior to screening) for confirmation of the KRAS G12C mutation in the central laboratory;\n* Disease progression or toxicity after previous treatment with first-line anti-PD-1 / PD-L1 and platinum-containing chemotherapy is not tolerated.Subjects who have clear medical reasons and can not tolerate anti-PD-1 / PD-L1 therapy or platinum-containing chemotherapy;\n* Having at least one target lesion according to RECIST 1.1;\n* Good function of the major organs;\n* Female subjects of childbearing age should agree that contraception must be used during the study and within 6 months after the end of the study; the serum pregnancy test is negative within 7 days before study enrollment and must be non-lactating subjects; male subjects should agree that contraception must be used during the study and within 6 months after the end of the study period.\n\nExclusion Criteria:\n\n* Treatment with a KRAS G12C mutation inhibitor or docetaxel at any previous time;\n* NSCLC with mutations of other driver genes;\n* Symptomatic or progressive aggravation of central nervous system metastasis or cancerous meningitis. Subjects with a history of brain metastasis may be considered to be selected if they are clinically stable;\n* Patients with a previous history of epilepsy；presence of superior vena cava syndrome;\n* Cardiovascular system meets any condition:\n\n  1. New York Heart Association (NYHA) Heart Function Grade II and above congestive heart failure;\n  2. Severe cardiac arrhythmias requiring medical treatment;\n  3. Acute myocardial infarction, severe or unstable angina pectoris, coronary or peripheral artery bypass surgery within 6 months prior to enrollment;\n  4. Left ventricular ejection fraction (LVEF) \\<50%;\n  5. QT interval (QTcF) at prolonged;\n  6. Hypertension that is not effectively controlled;\n* Subjects with stroke or other severe cerebrovascular disease within 6 months before enrollment;\n* History of deep vein thrombosis or any other serious thromboembolism within 3 months prior to enrollment;\n* History of interstitial lung disease, radiation pneumonitis, and immune-associated pneumonia previously treated with steroids, Or active non-infectious pneumonia with interstitial lung disease, radiation pneumonia, and immune-related pneumonia during the screening period, Presence of active tuberculosis, pneumoconiosis or grade 2 other type of pneumonia, or pulmonary function tests confirming severely impaired pulmonary function;\n* Severe bone damage due to tumor bone metastasis may occur at present or after randomization;\n* Active or uncontrolled serious infection (≥grade 2 infection of common toxicity criteria for adverse events (CTC AE)) or fever of unknown origin \\> 38.5°C;\n* The third space effusion (including pleural effusion, abdominal effusion or pericardial effusion), poor clinical control or the need for local symptomatic treatment such as puncture and drainage;\n* Known impaired gastrointestinal (GI) function or known GI diseases that may significantly affect the absorption or metabolism of oral drugs.\n\nPrevious history of major surgery in the digestive tract (esophagus, gastrointestinal tract) that may alter the absorption or inability to swallow drugs in the study treatment;\n\n* Toxicity of previous antitumor therapy, except alopecia, pigmentation, clinically insignificant laboratory abnormalities) has not recovered to grade 1, and peripheral nerve toxicity has not recovered to grade 2 ( CTCAE v5.0);\n* Human immunodeficiency virus (HIV) antibody positive, liver cirrhosis or active viral hepatitis;\n* Active syphilis;\n* Patients with renal failure requiring hemodialysis or peritoneal dialysis;\n* Poor diabetes control \\[fasting blood glucose (FBG)\\> 10 mmol/L\\];\n* Previous history of organ transplantation or readiness to undergo organ transplantation;\n* Weight of \\<40 kg and BMI of \\<18.5 kg/m2, or weight loss of\\> 5% within 3 months before enrollment;\n* Major surgical treatment or significant traumatic injury within 4 weeks prior to the first dose of this study;\n* Receiving palliative radiotherapy with local lesions within 2 weeks before the first dose of this study;\n* Pregnant or lactating subjects;\n* With the combination of other primary malignancies\n* Serious mental or mental illness or history of substance abuse or serious alcohol abuse;\n* Known allergy to the investigational medicinal product or any ingredient in the formulation;\n* Any other significant clinical abnormality or disease that the investigator considers poses a risk to subject safety or interferes with the medication and evaluation of the clinical study.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
