        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "BBO-10203",
              "type": "EXPERIMENTAL",
              "description": "Participants enrolled in this cohort will receive BBO-10203 tablets orally (different dose levels will be evaluated) once daily as monotherapy. This cohort will enroll patients with HER2-positive advanced breast cancer, HR-positive HER2-negative advanced breast cancer, advanced colorectal cancer, and advanced lung cancer.",
              "interventionNames": [
                "Drug: BBO-10203"
              ]
            },
            {
              "label": "BBO-10203 + Trastuzumab",
              "type": "EXPERIMENTAL",
              "description": "Participants enrolled in this cohort will receive BBO-10203 tablets orally in combination with trastuzumab. This cohort will enroll patients with HER2-positive advanced breast cancer.",
              "interventionNames": [
                "Drug: BBO-10203",
                "Drug: Trastuzumab"
              ]
            },
            {
              "label": "BBO-10203 + Fulvestrant",
              "type": "EXPERIMENTAL",
              "description": "Participants enrolled in this cohort will receive BBO-10203 tablets orally in combination with fulvestrant. This cohort will enroll patients with HR-positive, HER2-negative advanced breast cancer.",
              "interventionNames": [
                "Drug: BBO-10203",
                "Drug: Fulvestrant",
                "Drug: Ribociclib"
              ]
            },
            {
              "label": "BBO10203 + Fulvestrant + Ribociclib",
              "type": "EXPERIMENTAL",
              "description": "Participants enrolled in this cohort will receive BBO-10203 tablets orally in combination with fulvestrant and ribociclib as determined in the dose escalation. This cohort will enroll patients with HR-positive, HER2-negative advanced breast cancer.",
              "interventionNames": [
                "Drug: BBO-10203",
                "Drug: Fulvestrant",
                "Drug: Ribociclib"
              ]
            },
            {
              "label": "BBO10203 + FOLFOX + Bevacizumab",
              "type": "EXPERIMENTAL",
              "description": "Participants enrolled in this cohort will receive BBO-10203 tablets orally in combination with FOLFOX and bevacizumab. This cohort will enroll patients with KRAS-mutant advanced colorectal cancer.",
              "interventionNames": [
                "Drug: BBO-10203",
                "Drug: FOLFOX",
                "Drug: Bevacizumab"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "BBO-10203",
              "description": "Participants will receive assigned dose of BBO-10203 orally once daily",
              "armGroupLabels": [
                "BBO-10203",
                "BBO-10203 + Fulvestrant",
                "BBO-10203 + Trastuzumab",
                "BBO10203 + FOLFOX + Bevacizumab",
                "BBO10203 + Fulvestrant + Ribociclib"
              ]
            },
            {
              "type": "DRUG",
              "name": "Trastuzumab",
              "description": "Participants will receive trastuzumab as infusion or subcutaneous injection every 21 days",
              "armGroupLabels": [
                "BBO-10203 + Trastuzumab"
              ]
            },
            {
              "type": "DRUG",
              "name": "Fulvestrant",
              "description": "Patients will receive Fulvestrant as an intramuscular injection every 28 days (additional dose on C1D15)",
              "armGroupLabels": [
                "BBO-10203 + Fulvestrant",
                "BBO10203 + Fulvestrant + Ribociclib"
              ]
            },
            {
              "type": "DRUG",
              "name": "Ribociclib",
              "description": "Patients will receive Ribociclib orally once a day (21 days on treatment, 7 days off)",
              "armGroupLabels": [
                "BBO-10203 + Fulvestrant",
                "BBO10203 + Fulvestrant + Ribociclib"
              ]
            },
            {
              "type": "DRUG",
              "name": "FOLFOX",
              "description": "Patients will receive FOLFOX as infusion every 14 days",
              "armGroupLabels": [
                "BBO10203 + FOLFOX + Bevacizumab"
              ]
            },
            {
              "type": "DRUG",
              "name": "Bevacizumab",
              "description": "Patients will receive bevacizumab as infusion every 28 days",
              "armGroupLabels": [
                "BBO10203 + FOLFOX + Bevacizumab"
              ]
            }
          ]
        },
