        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Mobile Screening Group",
              "description": "Participants receiving lung cancer screening via a mobile unit (truck) operated by trained nurses. This includes spirometry, blood pressure measurement, blood cholesterol testing, low-dose CT scan, and optional biospecimen collection.",
              "interventionNames": [
                "Diagnostic Test: Low-dose Chest CT Screening",
                "Diagnostic Test: Spirometry",
                "Diagnostic Test: Cardiovascular Risk Assessment",
                "Behavioral: Smoking Cessation Support",
                "Other: Optional Biospecimen Collection (Bio-ILYAD)"
              ]
            },
            {
              "label": "Non-Mobile Screening Group",
              "description": "Participants receiving the same screening procedures at a fixed hospital-based site (Lyon Sud), with possible involvement of medical or non-medical staff depending on availability.",
              "interventionNames": [
                "Diagnostic Test: Low-dose Chest CT Screening",
                "Diagnostic Test: Spirometry",
                "Diagnostic Test: Cardiovascular Risk Assessment",
                "Behavioral: Smoking Cessation Support",
                "Other: Optional Biospecimen Collection (Bio-ILYAD)"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "Low-dose Chest CT Screening",
              "description": "Participants undergo a low-dose chest CT scan to screen for early lung cancer and assess associated conditions (emphysema, coronary calcifications, osteoporosis).",
              "armGroupLabels": [
                "Mobile Screening Group",
                "Non-Mobile Screening Group"
              ]
            },
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "Spirometry",
              "description": "Assessment of lung function through spirometry, with optional plethysmography and diffusion testing to detect COPD and PRISM patterns.",
              "armGroupLabels": [
                "Mobile Screening Group",
                "Non-Mobile Screening Group"
              ]
            },
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "Cardiovascular Risk Assessment",
