        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Intrathecal pemetrexed Cohort",
              "type": "ACTIVE_COMPARATOR",
              "description": "Phase 1 : Intrathecal pemetrexed (40 mg, twice weekly, every 3 weeks, for 2 cycles).\n\nPhase 2 : Standard intrathecal chemotherapy regimen (pemetrexed 40 mg, every 3 weeks, for 4 cycles).\n\nPhase 3 : Intrathecal chemotherapy (pemetrexed 40 mg, every 4 weeks) until intracranial progression.",
              "interventionNames": [
                "Drug: Intrathecal pemetrexed"
              ]
            },
            {
              "label": "risk-adaptive proton craniospinal irradiation cohort",
              "type": "EXPERIMENTAL",
              "description": "Phase 1 : Intrathecal pemetrexed (40 mg, twice weekly, every 3 weeks, for 2 cycles).\n\nPhase 2 : 1）Intermediate-risk patients receive proton craniospinal irradiation (pCSI) at 30 GyE in 10 fractions；2）High-risk patients receive pCSI at 30 GyE in 10 fractions with concurrent low-dose.\n\nPhase 3 : Intrathecal chemotherapy (pemetrexed 40 mg, every 4 weeks) until intracranial progression.",
              "interventionNames": [
                "Radiation: proton craniospinal irradiation",
                "Drug: Intrathecal pemetrexed"
              ]
            }
          ],
          "interventions": [
            {
              "type": "RADIATION",
              "name": "proton craniospinal irradiation",
              "description": "Phase 1: Intrathecal pemetrexed 40 mg, biw, q3w, for 2 cycles (via Ommaya reservoir). CSF ctDNA (maxVAF) tested at baseline (C0) and post-induction (C1) for risk stratification:\n\nLow-risk: ΔctDNA \\> 80% reduction or clearance. Intermediate-risk: ΔctDNA 20%-80% reduction. High-risk: ΔctDNA \\< 20% reduction.\n\nPhase 2:\n\nLow-risk: Pemetrexed 40 mg, q3w, 4 cycles (no randomisation). Intermediate/High-risk - Cohort A (Control): Pemetrexed 40 mg, q3w, 4 cycles.\n\nIntermediate/High-risk - Cohort B (Experimental):\n\nIntermediate: Proton craniospinal irradiation (pCSI) 30 GyE/10 fractions. High: pCSI 30 GyE/10 fractions + concurrent low-dose intrathecal pemetrexed 30 mg (days 1 \\& 8) as radiosensitizer.\n\nPhase 3: Pemetrexed 40 mg, q4w, until intracranial progression. Supportive/Concomitant: Mandatory folic acid and vitamin B12 premedication for pemetrexed; background systemic EGFR-TKI therapy p",
              "armGroupLabels": [
                "risk-adaptive proton craniospinal irradiation cohort"
              ]
            },
            {
              "type": "DRUG",
              "name": "Intrathecal pemetrexed",
              "description": "he goal of this clinical trial is to learn if a risk-adaptive consolidation therapy, guided by cerebrospinal fluid (CSF) circulating tumor DNA (ctDNA) clearance kinetics after induction intrathecal pemetrexed, can improve intracranial progression-free survival (iPFS) compared to standard intrathecal pemetrexed consolidation in patients with leptomeningeal metastasis (LM) from EGFR-mutant non-small cell lung cancer (NSCLC) that has progressed on third-generation EGFR-TKIs. It will also learn about the safety and tolerability of proton craniospinal irradiation (pCSI) in this setting.",
              "armGroupLabels": [
                "Intrathecal pemetrexed Cohort",
                "risk-adaptive proton craniospinal irradiation cohort"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Intracranial progression-free survival (iPFS)",
              "description": "Intracranial progression-free survival (iPFS) is defined as the time from enrollment to the date of intracranial progression or death from any cause, whichever occurs first.For subjects without observed intracranial progression or death, iPFS will be censored at the time of the last valid and adequate intracranial tumour assessment. iPFS analysis will be based on the Full Analysis Set (FAS). The median iPFS and its 95% CI will be estimated using the Kaplan-Meier method, and progression-free survival curves will be generated. Treatment group comparison will be performed using stratified log-rank test, and hazard ratio (HR) with 95% CI will be estimated using the Cox proportional hazards model.",
              "timeFrame": "up to 2 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Overall survival (OS)",
              "description": "Overall Survival (OS) is defined as the time from enrollment to death from any cause. For subjects not followed up to death, OS will be censored at the time of the last valid survival follow-up. OS analysis will be based on the Full Analysis Set (FAS). The median OS (if applicable) and its 95% CI will be estimated using the Kaplan-Meier method, and survival curves will be plotted. Treatment group comparison will be performed using stratified log-rank test, and HR with 95% CI will be estimated using the Cox proportional hazards model.",
              "timeFrame": "up to 2 years"
            },
            {
              "measure": "The lead time from achieving a 20% change in CSF ctDNA to radiographic progression per RANO-LM criteria",
              "description": "This endpoint is defined as the time interval from the first detection of a ≥20% change (increase or decrease) in CSF ctDNA maxVAF relative to the preceding baseline value to the date of subsequent radiographic intracranial progression confirmed by independent review committee (IRC) per RANO-LM criteria. This analysis will be performed only in subjects with both baseline and at least one on-treatment paired CSF sample and who achieve a ≥20% ctDNA change during treatment. The median lead time and its 95% CI will be estimated using the Kaplan-Meier method, with ctDNA change date as time zero and radiographic progression as the event. If the distribution is skewed, the lead time will be presented descriptively as median with interquartile range.",
              "timeFrame": "up to 2 years"
            },
            {
              "measure": "Incidence and Severity of Adverse Events, Serious Adverse Events, Treatment-Related Adverse Events, Immune-Related Adverse Events, and Laboratory Abnormalities",
              "description": "The number and percentage of participants experiencing adverse events (AEs), serious adverse events (SAEs), treatment-related adverse events (TRAEs), immune-related adverse events (irAEs), and clinically significant laboratory abnormalities will be assessed. Events will be summarized by type, frequency, severity grade, seriousness, and relationship to study treatment according to the National Cancer Institute Common Terminology Criteria for Adverse Events (NCI-CTCAE), version 6.0.",
              "timeFrame": "up to 2 years"
            },
            {
              "measure": "Change from Baseline in the European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire-Core 30 Global Health Status/Quality of Life Score",
              "description": "The European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire-Core 30 (EORTC QLQ-C30) Global Health Status/Quality of Life scale consists of 2 items. The raw score is linearly transformed to a score ranging from 0 to 100. Higher scores indicate better global health status and quality of life.Change from baseline will be assessed at each scheduled post-baseline visit. Changes will be summarized descriptively by treatment group. Between-group differences will be evaluated using a mixed-effects model for repeated measures, including baseline score, treatment group, visit, and treatment-by-visit interaction.",
              "timeFrame": "up to 2 years"
            },
            {
              "measure": "Change from Baseline in the MD Anderson Symptom Inventory-Brain Tumor Module Mean Symptom Severity Score",
              "description": "The MD Anderson Symptom Inventory-Brain Tumor Module (MDASI-BT) assesses 13 core cancer-related symptoms and 9 brain tumor-specific symptoms experienced during the previous 24 hours. Each symptom is rated on an 11-point numeric rating scale ranging from 0, meaning \"not present,\" to 10, meaning \"as bad as you can imagine.\"The mean symptom severity score is calculated as the mean of the completed symptom items and ranges from 0 to 10. Higher scores indicate greater symptom severity.Change from baseline will be assessed at scheduled post-baseline visits. Between-group differences will be evaluated using a mixed-effects model for repeated measures, including baseline score, treatment group, visit, and treatment-by-visit interaction.",
              "timeFrame": "up to 2 years"
            },
            {
              "measure": "Change from Baseline in the Montreal Cognitive Assessment Total Score",
              "description": "Cognitive function will be assessed using the Montreal Cognitive Assessment (MoCA). The MoCA evaluates visuospatial and executive function, naming, attention, language, abstraction, delayed recall, and orientation.The total score ranges from 0 to 30. Higher scores indicate better cognitive performance. Scoring, including any protocol-specified education adjustment, will be conducted according to the authorized version of the instrument.Change from baseline in the total score will be assessed at scheduled post-baseline visits. Between-group differences will be evaluated using a mixed-effects model for repeated measures, including baseline score, treatment group, visit, and treatment-by-visit interaction.",
              "timeFrame": "up to 2 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Voluntary participation with written informed consent obtained prior to any study-specific procedures, and willingness and ability to comply with scheduled visits, the treatment plan, laboratory tests, and other study requirements.\n2. Male or female patients aged between 18 and 75 years (inclusive) at the time of signing informed consent.\n3. Primary tumour confirmed as non-small cell lung cancer (NSCLC) by cytology or histology, harbouring EGFR-sensitive mutations (including 19del and exon 21 L858R). Testing reports for EGFR mutation status must be available; if no prior report exists, submission of archived tissue or baseline biopsy for assessment is mandatory.\n4. Leptomeningeal metastasis (LM) diagnosed according to the EANO-ESMO guidelines, based on cerebrospinal fluid (CSF) cytology and/or imaging evidence of leptomeningeal enhancement or ventriculomegaly.\n5. Disease progression of LM documented after treatment with third-generation EGFR-TKIs (including osimertinib, almonertinib, or furmonertinib). Patients may continue their current EGFR-TKI therapy during the study, provided that extracranial disease remains stable.\n6. The patient has had an Ommaya reservoir implanted or has undergone Ommaya reservoir placement prior to study entry, and is willing to undergo intrathecal injections via the reservoir throughout the study.\n7. Extracranial disease is stable, defined as no progressive extracranial lesions (per RECIST v1.1) within 28 days prior to enrollment. Continuation of background systemic EGFR-TKI therapy is permitted.\n8. Life expectancy ≥ 3 months as assessed by the investigator.\n9. Karnofsky Performance Status (KPS) ≥ 70 at screening.\n10. Medically fit to tolerate intrathecal pemetrexed and proton craniospinal irradiation (pCSI), as determined by the investigator.\n11. Adequate organ and bone marrow function as defined below (within 14 days prior to initiation of study treatment), without having received blood transfusions, granulocyte colony-stimulating factor (G-CSF), or hematopoietic growth factors within 14 days prior to screening:\n\n    * Hematology:\n\n      * Haemoglobin (Hb) ≥ 90 g/L;\n      * Absolute Neutrophil Count (ANC) ≥ 1.5 × 10⁹/L;\n      * Platelets (PLT) ≥ 75 × 10⁹/L.\n    * Blood Chemistry:\n\n      * Total Bilirubin (TBIL) ≤ 2.0 × ULN (≤ 3.0 × ULN for patients with Gilbert's syndrome);\n      * Alanine Aminotransferase (ALT) and Aspartate Aminotransferase (AST) ≤ 5.0 × ULN;\n      * Serum Creatinine (Cr) ≤ 1.5 × ULN or Calculated Creatinine Clearance (CrCl) ≥ 50 mL/min (using the Cockcroft-Gault formula):\n      * Male: CrCl = ((140 - age) × weight) / (72 × serum creatinine)\n      * Female: CrCl = ((140 - age) × weight) / (72 × serum creatinine) × 0.85 (Note: Weight in kg; Serum creatinine in mg/dL)\n    * Coagulation Function:\n\n      * International Normalized Ratio (INR) ≤ 2.0 or Prothrombin Time (PT) ≤ 6 seconds above the upper limit of normal.\n12. Female subjects of childbearing potential must have a negative urine or serum pregnancy test within 7 days prior to the first dose of study treatment. If the urine test cannot be definitively confirmed as negative, a serum pregnancy test must be performed, and the serum result will be considered definitive.\n13. Female subjects of childbearing potential who are sexually active with unsterilised male partners must agree to use highly effective contraception starting at screening and continue for 180 days after the last dose of study treatment.\n14. Sexually active male subjects who have not undergone sterilisation and who are sexually active with female partners of childbearing potential must agree to use effective contraception starting at screening and continue for 180 days after the last dose of study treatment. Decisions regarding cessation of contraception beyond this timeframe should be discussed with the investigator.\n15. Subjects must be willing and able to comply with the study protocol, including scheduled visits, treatment administration, laboratory tests, imaging assessments, and CSF sample collections via the Ommaya reservoir.\n\nExclusion Criteria:\n\n* Patients with concurrent primary tumors of the brain or spinal cord.\n* Patients with severe central nervous system diseases (including severe cerebral herniation or coma).\n* Patients with life-threatening or uncontrolled systemic diseases, such as uncontrolled hypertension or active bleeding tendency.\n* Patients with other concurrent malignancies, except for basal cell carcinoma of the skin and carcinoma in situ.\n* Patients who have previously received whole-brain radiotherapy or photon radiotherapy to involved fields of the brain and spinal cord.\n* Patients judged by the investigator to be unsuitable for participation, or who have factors that may affect compliance with the protocol.\n* Toxicity from prior treatment has not recovered to normal or to grade 1 per NCI-CTCAE version 6.0.\n* Patients with drug allergy or metabolic disorders to the drugs used in this protocol.\n* Pregnant or lactating women, or female patients who plan to become pregnant during the study period or within 6 months after the last dose.\n* Patients who are concurrently participating in other clinical studies\n* Patients with pre-existing cardiac dysfunction.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "75 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
