[{"role": "assistant", "content": "", "tool_calls": [{"id": "call_xm0a0lrf", "type": "function", "function": {"name": "clinicaltrialsgov-mcp-server_clinicaltrials_list_studies", "arguments": "{"query":{"cond":"sedentary"},"filter":{"overallStatus":["COMPLETED"]},"pageSize":20}"}}]}, {"role": "tool", "content": [{"type": "text", "text": "{
  "studies": [
    {
      "protocolSection": {
