          "briefTitle": "Physical Activity and Leisure-time Study (PALS)",
          "officialTitle": "TV Commercial Stepping: Can America's Top Sedentary Activity be Made More Active",
          "acronym": "PALS"
        },
        "statusModule": {
          "statusVerifiedDate": "2012-10",
          "overallStatus": "COMPLETED",
