            "type": "ESTIMATED"
          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "SPONSOR"
          },
          "leadSponsor": {
            "name": "University of Tennessee",
            "class": "OTHER"
          }
        },
        "oversightModule": {
          "oversightHasDmc": false
        },
        "descriptionModule": {
          "briefSummary": "Physical inactivity is a major public health problem and a primary contributing factor to the obesity epidemic. While most Americans do not meet the physical activity (PA) guidelines (30 min/day, 5 day/wk), they do report watching several hours of TV each day, and frequently site \"lack of time\" as a barrier for engaging in PA. The Physical Activity and Leisure-time Study examines an approach convert sedentary TV watching into active TV watching time by having adults step in place during commercials (TV commercial stepping).",
          "detailedDescription": "This randomized controlled trial will examine the effects of a PA prescription of TV commercial stepping for at least 90 min/day of TV programming, with that of walking at least 30 min/day (30 min walk) on daily step counts, TV viewing, and diet during a 24 week PA intervention. Sedentary, overweight or obese, adults will be randomly assigned to either the TV commercial stepping, or 30 min walk group during a 24-week behavioral PA intervention. Both groups will attend 8 sessions, but receive different PA goals. PA, TV watching time, diet, and anthropometric data will be collected at 0, 12, and 24 weeks. It is hypothesized that the TV commercial stepping condition will, show an equal increase in PA at 12 and 24 weeks as compared to the 30-min walk condition. Neither group is hypothesized to demonstrate changes in TV viewing time, dietary intake, or weight."
        },
        "conditionsModule": {
          "conditions": [
            "Physical Activity",
            "Weight"
          ],
          "keywords": [
            "Physical activity intervention",
            "walking",
            "TV",
            "sedentary"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE1"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "SINGLE",
              "whoMasked": [
                "PARTICIPANT"
              ]
            }
          },
          "enrollmentInfo": {
            "count": 58,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "30-min walk",
              "type": "ACTIVE_COMPARATOR",
              "description": "Instructed to use \"brisk\" walking (at least 30 min/day in bouts of at least 10 min) at least 5 days/week. Participants were permitted to exercise in one long bout (30 min) or divide the exercise into multiple bouts as long as the bout length was 10 min or greater.",
              "interventionNames": [
                "Behavioral: 30-min walk"
              ]
            },
            {
              "label": "TV commercial stepping",
              "type": "EXPERIMENTAL",
              "description": "Instructed to stand and \"briskly\" step in place, or \"briskly\" walk continuously around the room/house for the duration of each commercial break during at least 90 min of TV programming on at least 5 days/week. Rather than exercising continuously for at least 10-minute bouts, participants performed multiple (\\~9 or 10), short (\\~3-5 min) bouts, conveniently incorporated into their daily TV viewing time.",
              "interventionNames": [
                "Behavioral: TV commercial stepping"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "TV commercial stepping",
              "description": "Participants were instructed to stand and \"briskly\" step in place, or \"briskly\" walk continuously around the room/house for the duration of each commercial break during at least 90 min of TV programming on at least 5 days/week. Both conditions will receive an ankle mounted Omron pedometer, so they were able to track their steps each day. Participants were not given instructions concerning diet modification or modifying TV viewing time during a 6 month behavioral physical activity intervention",
              "armGroupLabels": [
                "TV commercial stepping"
              ],
              "otherNames": [
                "novel exercise prescription"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "30-min walk",
              "description": "Participants were instructed to use \"brisk\" walking (at least 30 min/day in bouts of at least 10 min) at least 5 days/week. Both conditions will receive an ankle mounted Omron pedometer, so they were able to track their steps each day. Participants were not given instructions concerning diet modification or modifying TV viewing time during a 6 month behavioral physical activity intervention",
              "armGroupLabels": [
                "30-min walk"
              ],
              "otherNames": [
                "standard physical activity prescription"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Physical Activity (Steps/Day)",
              "description": "Change in pedometer measured steps per day between 0 and 6 months",
              "timeFrame": "0 and 6 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Total Energy Intake",
              "description": "Change in total energy intake(kcals/day) between 0 and 6 months",
              "timeFrame": "0 and 6 months"
            },
            {
              "measure": "TV Related Energy Intake",
              "description": "Change in energy intake (kcals/day) while watching TV between 0 and 6 months",
              "timeFrame": "0 and 6 months"
            },
            {
              "measure": "Weight",
              "description": "Change in weight in kgs between 0 and 6 months",
              "timeFrame": "0 and 6 months"
            },
            {
              "measure": "TV Viewing Time",
              "description": "Change in self-reported TV viewing time per day between 0 and 6 months",
              "timeFrame": "0 and 6 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* 25 to 65 years of age\n* BMI between 25 and 45 kg/m2\n* watch ≥14 hours per week of TV\n* ability to follow instructions and record data\n* ability to walk 1/4 mile without stopping\n\nExclusion Criteria:\n\n* history of myocardial infraction, angina, stroke, heart failure, or uncontrolled cardiac arrhythmias\n* a resting blood pressure greater than 180 mm Hg systolic and/or 100 mm Hg diastolic\n* other physical or medical limitations for engaging in physical activity\n* no television in the home\n* baseline physical activity level exceeding 7,499 steps per day as determined by the Omron pedometer\n* currently participating in a program to increase PA\n* intended to move outside the East Tennessee area within the time frame of the intervention\n* were pregnant, lactating, less than 6 months post-partum, or planned to become pregnant during the time frame of the intervention\n* unwilling to attend group intervention meetings, assessments or to complete an activity diary for the duration of the study.",
          "healthyVolunteers": true,
          "sex": "ALL",
