          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Neuromuscular exercise",
              "description": "Fustra20 Neck \\& Back is individually guided, graded neuromuscular exercise program which is conducted twice a week for 20 times. Each session lasts one hour. After 20 sessions participants are encouraged to continue exercising at home with a help of an individual home exercise plan including diary of compliance.\n\nThe main targets are to\n\n* improve movement control in different posture and movements of the neck and back\n* improve flexibility with active functional movements\n* improve pelvic, spine and shoulder-neck stability using co-contraction of several muscle groups, and thus enhancing gross movement of the whole kinetic chain\n* improve muscular endurance of shoulder neck area, trunk, pelvis and lower extremities",
              "armGroupLabels": [
                "Neuromuscular exercise"
              ]
            }
          ]
        },
