        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "interventionModelDescription": "This study follows a parallel, non-randomized interventional model. Participants were assigned to one of two arms based on the hospital where they received care, following standard clinical practice. No crossover occurred between groups. Each arm received a multicomponent exercise intervention with similar structure and objectives, delivered either in-person or at home with digital support. The primary comparison focuses on functional outcomes and fall incidence between the two settings.",
            "primaryPurpose": "PREVENTION",
            "maskingInfo": {
              "masking": "NONE",
              "maskingDescription": "No masking was implemented. All participants and study personnel were aware of group assignments."
            }
          },
