            "count": 127,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Home-based Exercise with Digital Support (ViviFil App)",
              "type": "EXPERIMENTAL",
              "description": "Participants in this arm followed a personalized multicomponent exercise program at home using the VIVIFIL mobile application. The program included strength, balance, flexibility, and aerobic exercises adapted to each participant's functional capacity (based on SPPB score). The VIVIFIL App was installed on participants' smartphones or provided devices and included daily video-guided sessions, automatic progression, and a chat function for communication with healthcare professionals who provided remote monitoring.",
              "interventionNames": [
                "Behavioral: VIVIFIL App Program"
              ]
            },
            {
              "label": "In-person Supervised Exercise at Geriatric Day Hospital",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants in this arm attended supervised multicomponent exercise sessions at the Geriatric Day Hospital, 2-4 times per week for 8 weeks. Each session lasted 45-60 minutes and was delivered by trained professionals. Exercises included strength training, balance exercises, flexibility, and aerobic conditioning. Programs were tailored based on the participant's initial functional assessment.",
              "interventionNames": [
                "Behavioral: Hospital-Based Multicomponent Exercise"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "VIVIFIL App Program",
              "description": "A digitally supported multicomponent exercise program delivered through the VIVIFIL mobile application. Participants followed a daily home-based routine including strength, balance, flexibility, and aerobic exercises, adapted to their functional reserve. The app provided video instructions, progression tracking, and a chat for remote communication with healthcare professionals.",
              "armGroupLabels": [
                "Home-based Exercise with Digital Support (ViviFil App)"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Hospital-Based Multicomponent Exercise",
              "description": "A supervised multicomponent exercise program delivered at a geriatric day hospital by trained professionals. Sessions lasted 45-60 minutes, 2-4 times per week for 8 weeks. Exercises included strength training, balance, flexibility, and aerobic components, adjusted to the participant's functional status.",
              "armGroupLabels": [
                "In-person Supervised Exercise at Geriatric Day Hospital"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Change in Short Physical Performance Battery (SPPB) Score",
              "description": "The SPPB is a standardized assessment tool that includes gait speed, chair stand, and balance tests. Scores range from 0 to 12, with higher scores indicating better physical performance. The primary outcome is the change in total SPPB score from baseline to 8 weeks.",
              "timeFrame": "Baseline and 8 weeks"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Change in 4-Meter Gait Speed",
              "description": "Gait speed (m/s) is measured over a 4-meter walk. The best of three trials is recorded. Higher speed reflects better functional capacity.",
              "timeFrame": "Baseline and 8 weeks"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Change in Timed Up and Go (TUG) Test",
              "description": "The TUG test assesses functional mobility. Participants are timed as they rise from a chair, walk 3 meters, turn, return, and sit. A lower time indicates better performance.",
              "timeFrame": "Baseline and 8 weeks"
            },
            {
              "measure": "Change in Frailty Status (Standardised Frailty Criteria)",
              "description": "Frailty status is assessed using criteria including weight loss, grip strength, exhaustion, slow gait, and low activity. Participants are classified as robust, pre-frail, or frail.",
              "timeFrame": "Baseline and 8 weeks"
            },
            {
              "measure": "Number of Falls During the Intervention Period",
              "description": "Total number of falls reported by participants during the 8-week intervention period. Falls were self-reported and monitored by the research team.",
              "timeFrame": "8 weeks"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Age 70 years or older\n* Attending a specialized falls clinic at one of the participating hospitals\n* Able to ambulate independently or with the aid of one or two canes\n* At least one of the following:\n\n  1. A fall with consequences requiring medical attention in the past year\n  2. Two or more falls in the past 12 months\n  3. Self-reported gait or balance disturbance\n  4. Self-reported fear of falling\n\nExclusion Criteria:\n\n* Terminal illness with a life expectancy of less than 6 months\n* Refusal or inability to provide informed consent",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "70 Years",
          "stdAges": [
            "OLDER_ADULT"
          ]
        },
