            "class": "OTHER"
          },
          "briefTitle": "Flywheel Resistance Training and Traditional Resistance Training in Older Women With Sedentary Behaviors",
          "officialTitle": "Effect of 10 Months of Flywheel Resistance Training Versus Traditional Resistance Training on Depressive Symptoms, Physical and Executive Function in Older Women With Sedentary Behaviors",
          "acronym": "FET"
        },
        "statusModule": {
          "statusVerifiedDate": "2026-01",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
