        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Pablo Augusto Garcia Agostinho",
            "investigatorTitle": "Ph.D. Student in Physical Education, Principal Investigator",
            "investigatorAffiliation": "Federal University of Vicosa"
          },
          "leadSponsor": {
