        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Active group",
              "description": "Participants will be divided into two groups according to their physical activity level using the International Physical Activity Scale. Individuals with high physical activity levels will be included in this group."
            },
            {
              "label": "Inactive Group",
              "description": "cipants will be divided into two groups according to their physical activity level using the International Physical Activity Scale. Individuals with low physical activity levels will be included in this group."
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Nelson Hand Reaction Test",
              "description": "A ruler is used for the Nelson hand reaction test. Sit on the chair in a comfortable position with the forearm and hand on the table. Thumb and index finger tips are brought in parallel to each other 8-10 cm outside the table. The ruler is held between the thumb and forefinger. In this position, the test ruler is released and the ruler is asked to catch it. The value at the top of the thumb is saved when the ruler is captured. A total of five attempts are made and the best three results are averaged and noted.",
              "timeFrame": "Day 1"
            },
            {
              "measure": "Reaction Time Measurement with Computer",
              "description": "Reaction time is recorded through a program on computers or tablets. The alerts sent are in visual or auditory form. In reaction measurement, stimuli appear on the screen (5-15 seconds), which are not clear when. In order to eliminate the resulting image or auditory stimulus, it gives by pressing the specified key on the keyboard or screen. The applied test is recorded by the computer. A total of five attempts are made. It is noted by averaging the three best results.",
              "timeFrame": "Day 1"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "International Physical Activity Questionnaire Short Form (IPAQ-SF)",
              "description": "The International Physical Activity Questionnaires (IPAQ) comprises a set of 4 questionnaires.\n\nLong (5 activity domains asked independently) and short (4 generic items) versions for use by either telephone or self-administered methods are available",
              "timeFrame": "Day 1"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion criteria;\n\n* Being between the ages of 20 - 30,\n* Healthy individuals,\n* Absence of carpal tunnel syndrome, Exclusion criteria ;\n* Not having a musculosketal or neurological disease that limits mobility\n* Absence of upper extremity sequelae,",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "20 Years",
          "maximumAge": "30 Years",
          "stdAges": [
            "ADULT"
          ],
          "studyPopulation": "The 'Phalen Test' will be applied in order to eliminate the risk of finding a carpal tunnel for the people included in the study. The subjects included in the study will be classified according to their physical activity status by giving the \"International Physical Activity Questionnaire (Short)\". Records of the subjects' dominant hands will be taken and included in the analysis process.",
