        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "CARLOS MARTIN SANCHEZ",
            "investigatorTitle": "Principal Investigator",
            "investigatorAffiliation": "University of Salamanca"
