          },
          "briefTitle": "Improving Physical Activity of Older People in Community Through Trained Volunteers: the ImPACt Study",
          "officialTitle": "Improving Physical Activity of Older People in Community Through Trained Volunteers: the ImPACt Study"
        },
        "statusModule": {
