          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "interventionModelDescription": "This pilot study is being conducted to inform feasibility of the next phase of this research project.",
            "primaryPurpose": "PREVENTION",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
