          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Maternal Cardiovascular health (CVH) Intervention",
              "type": "EXPERIMENTAL",
              "description": "The pilot maternal CVH intervention will be delivered by NFP partners starting as early as NFP program enrollment in the first trimester after confirmation of a viable pregnancy and no later than the 28th week of pregnancy and will continue up to 6 months postpartum. The visit schedule will be consistent with the NFP visit structure to deliver intervention content at regularly scheduled visits that are typically 60 minutes long (weekly visits for the first month following enrollment followed by twice monthly visits until delivery). The pilot study will include an enhanced behavioral component target decreased sedentary time and increase physical activity and utilizing a technology/monitoring component. All women be monitored using a wrist-worn actigraphy device to record daily activity, intermittent home blood pressure self-monitoring, intermittent home weight self-monitoring, and carbon monoxide monitoring administered by the NFP nurse.",
              "interventionNames": [
                "Behavioral: Maternal CVH Intervention"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Maternal CVH Intervention",
              "description": "All participants will be enrolled into the intervention arm of this pilot study.",
              "armGroupLabels": [
                "Maternal Cardiovascular health (CVH) Intervention"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Feasibility of Integrating a Cardiovascular Health Module to the Existing Nurse-Family Partnership (NFP) Home Visiting Program as Measured by Qualitative Feedback From Home Visitors.",
              "description": "Feasibility will be determined good acceptability by NFP nurses as assessed qualitatively during group discussions. Nurses will use their experience as home visitors to provide feedback to study personnel on whether they are able to successfully integrate new visit content into their usual workflow. They will further give suggestions for future improvement after completion of this pilot study.",
              "timeFrame": "6 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Nulliparous pregnant woman\n2. Age ≥ 18 years old\n3. Enrolled in and receiving the Nurse-Family Partnership program through the Geisinger Clinic or UPMC Home Health Care of Central PA\n4. English speaking\n5. Women with a singleton viable pregnancy confirmed by NFP home visitors\n6. Access to reliable internet service required for data collection\n7. A minimum of 5 women with use of nicotine containing products (cigarette, cigar, hookah, chewing tobacco, e-cigarette, patch) within the past 3 months\n\nExclusion Criteria:\n\n1. Unable or unwilling to comply with the study visits and procedures\n2. Participation in a concurrent interventional study\n3. Diagnosis of cancer\n4. A personal history of complex congenital heart disease\n5. A fetus in the current pregnancy with known chromosomal abnormalities or birth defects inconsistent with survival to 2 years will be excluded",
