        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Physical Activity Increase (GLB-MOD)",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants randomized to this arm will follow the traditional GLB program with an activity goal of 150 minutes per week of moderately intense physical activity similar to a brisk walk. Progression of the activity goal each week is slow and safe with increases of no more than 30 minutes per week. Participants are requested to try and achieve 20-30 minutes per day of moderate activity but, to allow for flexibility, that amount can be split into 10 minute increments. Self-reported monitoring for this group includes keeping track of weight, daily food intake as well the number of minutes each day spent being active as part of their planned activity goal. This is all recorded in the self-monitoring keeping track book.",
              "interventionNames": [
                "Behavioral: Physical Activity Increase (GLB-MOD)"
              ]
            },
            {
              "label": "Sedentary Time Decrease (GLB-SED)",
              "type": "ACTIVE_COMPARATOR",
              "description": "The GLB curriculum will be adapted to direct participants to decrease the time they spend sitting in a day rather than to increase moderate+ physical activity as is the case in the current GLB program. In order for the participant to become aware of how much time they spend sitting and where most of their sitting time occurs, they will fill out a \"7 Day Sedentary Diary\" that consists of daily entry of time spent sitting over the course of one week. Participants will be asked to eliminate a 45 minute sitting bout in a day with non-sitting activity. They will initially be asked to eliminate 45 minutes of sitting for two days in that week. This will increase one day a week until 7 days in a week are met.",
              "interventionNames": [
                "Behavioral: Sedentary Time Decrease (GLB-SED)"
              ]
            },
            {
              "label": "6-month delayed (DELAYED)",
              "type": "OTHER",
              "description": "Those assigned to the DELAYED group at baseline will wait for 6 months to begin intervention. During the delayed time period, these participants will receive periodic health information newsletters. At the end of 6 months, the DELAYED participants will be randomly assigned to GLB-MOD or GLB-SED intervention, and will begin their intervention program at that time.",
              "interventionNames": [
                "Other: 6-month delayed (DELAYED)"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Physical Activity Increase (GLB-MOD)",
              "description": "The Group Lifestyle Balance (GLB) program was adapted from the original DPP lifestyle intervention. As in the original DPP lifestyle program, the GLB goals are to achieve and maintain a 7% weight loss, and to safely and progressively increase physical activity to 150 minutes/week of moderately intense physical activity similar to a brisk walk.\n\nThe curriculum will be administered in intervention groups with an average of 10-15 individuals per group; sessions will be conducted by trained coaches, with participants attending 22 sessions over one year.\n\nThe two intervention arms will only differ in the aerobic activity portion of the intervention, which is covered in sessions #4, #10 and 19 as well as participant record keeping and goal setting in regards to activity/inactivity progression.",
              "armGroupLabels": [
                "Physical Activity Increase (GLB-MOD)"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Sedentary Time Decrease (GLB-SED)",
              "description": "As in the original DPP, the GLB goal for weight is to achieve and maintain a 7% weight loss. For this intervention arm, instead of focusing on increasing moderate physical activity, the GLB curriculum will be adapted to address decreasing sitting time. Participants will have a goal of decreasing sitting time by 45 minutes/day. The curriculum will be administered in intervention groups with an average of 10-15 individuals per group; sessions will be conducted by trained coaches, with participants attending 22 sessions over one year.\n\nThe two intervention arms will only differ in the aerobic activity portion of the intervention, which is covered in sessions #4, #10 and 19 as well as participant record keeping and goal setting in regards to activity/inactivity progression.",
              "armGroupLabels": [
                "Sedentary Time Decrease (GLB-SED)"
              ]
            },
            {
              "type": "OTHER",
              "name": "6-month delayed (DELAYED)",
              "description": "Individuals assigned to 6 month delay will wait for 6 months from baseline to be randomly assigned to one of the two interventions and will begin intervention at that time. During the waiting period they will receive health information newsletters.",
              "armGroupLabels": [
                "6-month delayed (DELAYED)"
              ]
            }
          ]
        },
