            }
          ],
          "interventions": [
            {
              "type": "OTHER",
              "name": "Tailored Internet Communication with Relational Agent",
              "description": "The Tailored Internet Intervention will include a \"relational agent\" component, which is an animated conversational agent that builds a working relationship with subjects over time and uses this alliance to boost intervention effectiveness and retention to the Tailored Internet Communications web site.",
              "armGroupLabels": [
