              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Exercise",
              "description": "Regular Exercise is defined as any planned physical activity (e.g., brisk walking, aerobics, jogging, bicycling, swimming, rowing, basketball, etc.) performed to increase physical fitness. Such activity should be performed 5 times or more per week for 30 minutes per session, consistent with CDC guidelines.",
              "timeFrame": "Percentage of baseline at-risk participants who reach the Regular Exercise criteria at 24 months."
            },
            {
              "measure": "Sun Exposure",
              "description": "Consistently protecting themselves from the sun every time they were out in the sun for 15+ minutes is defined as 1) using sunscreens with a sun protection factor (SPF) of 15 or more, wearing protective clothing (for example, a hat with a wide brim, shirts, and pants), and avoiding or limiting exposure to the sun during the mid-day hours (10 am - 4 pm).",
              "timeFrame": "Percentage of baseline at-risk participants who reach the Sun Protection criteria at 24 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Exercise",
              "timeFrame": "Increase in number of minutes of physical activity per week (150 minutes of moderate intensity or 75 minutes of vigorous intensity) measured by the International Physical Activity Questionnaire (IPAT)"
            },
            {
              "measure": "Sun Exposure",
              "timeFrame": "Increase in number of sun protection behaviors as measured by the Sun Protection Behavior Scale (SPBS), which consists of three scales: sunscreen use, sun avoidance and protective clothing, and hat use."
            }
          ]
        },
