        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "#HerHEART Risk Score in AYA From Baseline",
              "description": "Risk is assessed based on answers surrounding the most critical diet and lifestyle factors that can influence a person's CVD risk. The factors include exercise, intake of fruits, vegetables, grains, nuts, sugary beverages and red/processed meats, and exercise. The Healthy Heart Score algorithm will be used to calculate the relative percent risk score of participants. Participants with a higher percent risk score have a higher risk for CVD based on their current reported habits. Those at low risk will have a risk score \\<10%, moderate risk a risk score between 10 and 15%, and high risk a score above 15%.",
              "timeFrame": "Baseline, 3 months post-enrollment"
            },
            {
              "measure": "Overall Composite of Diet Score",
              "description": "Diet score = (0.03626 × grams/d of cereal fiber + 0.18283 \\[if fruits + vegetables ≥3 servings/d\\] + 0.14522 \\[if nuts 0.1-1 servings/d + 0.2444 \\[if nuts \\>1 servings/d\\]- 0.14631 × servings/d of sugar-sweetened beverages - 0.15624 × servings/d of red and processed meats)\\*10 A higher score implies better diet quality. An increase in diet score correlates with a better outcome.",
              "timeFrame": "Baseline, 3 months months post-enrollment"
            },
            {
              "measure": "Fruit and Vegetable Intake",
              "description": "Intake will be measured with number of servings per day. Increase in servings/day correlates with a better outcome.",
              "timeFrame": "Baseline, 3 months post- post-enrollment"
            },
            {
              "measure": "Red and Processed Meats Intake",
              "description": "Intake will be measured with number of servings per day. A decrease in consumption is associated with a better outcome.",
              "timeFrame": "Baseline, 3 months post-enrollment"
            },
            {
              "measure": "Sugar and Sweetened Beverages",
              "description": "Intake will be measured with number of servings per week. A decrease in consumption is associated with a better outcome.",
              "timeFrame": "Baseline, 3 months post-enrollment"
            },
            {
              "measure": "Nut Consumption",
              "description": "Intake will be measured with number of servings per week. An increase in intake is associated with a better outcome.",
              "timeFrame": "Baseline, 3 months post-intervention"
            },
            {
              "measure": "Alcohol Consumption",
              "description": "Number of participants who consume alcohol will be collected. No alcohol consumption is associated with a better outcome.",
              "timeFrame": "Baseline, 3 months post-enrollment"
            },
            {
              "measure": "Nicotine Use",
              "description": "Self-reported smoker status will be obtained and classified as: Never smoke, used to smoke, current smoker. Investigators will look at changes in smoking status where a decrease in use is associated with a better outcome.",
              "timeFrame": "Baseline, 3 months post-enrollment"
            },
            {
              "measure": "Cereal Fiber",
              "description": "Consumption of cereal will be measured in g/day. An increase in cereal fiber is associated with a better outcome.",
              "timeFrame": "Baseline, 3 months post-enrollment"
            },
            {
              "measure": "Physical Activity",
              "description": "Physical activity will be measured in number of hours per week. Increase in physical activity associated with a better outcome.",
              "timeFrame": "Baseline, 3 months post-enrollment"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "BMI From Baseline",
              "description": "AYA participant's BMI will be measured during the clinic appointment when participant is recruited. AYA participants will then be asked to return for a study visit 3 months post intervention where their BMI will be measured again. Change in BMI will be measured with a decrease in BMI being associated with a positive outcome and an increase in BMI being associated with a negative outcome.",
              "timeFrame": "Baseline, 3 month post-enrollment"
            },
            {
              "measure": "Systolic Blood Pressure (BP) From Baseline",
              "description": "AYA participants' systolic BP (SBP) will be measured during the clinic appointment when the participant is recruited. AYA participants will then be asked to return for a study visit 3 months post-intervention where their BP will be measured again. Change in SBP will be measured with a decrease in SBP being associated with a positive outcome and an increase in SBP being associated with a negative outcome.",
              "timeFrame": "Baseline, 3 month post-enrollment"
            },
            {
              "measure": "Diastolic Blood Pressure (BP) From Baseline",
              "description": "AYA participants' diastolic BP (DBP) will be measured during the clinic appointment when the participant is recruited. AYA participants will then be asked to return for a study visit 3 months post-intervention where their BP will be measured again. Change in DBP will be measured with a decrease in diastolic BP being associated with a positive outcome and an increase in BP being associated with a negative outcome.",
              "timeFrame": "Baseline, 3 month post-enrollment"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria (AYAs):\n\n* Patient at CHOA Hughes Spalding Adolescent Medicine Practice or the Grady Health System Teen Program\n* Age 13-21 years\n* Self-identifying as non-Hispanic Black or White race (inclusive of Hispanic ethnicity)\n* Self-identifying as female\n* Visit type is annual wellness/health check, behavioral/mental health, or reproductive/gynecological health\n* Consistent access to a mobile device with internet capability\n\nExclusion Criteria (AYAs):\n\n* Cognitive impairment limiting ability to complete study procedure\n* Spoken and written language other than English\n* Diagnosis of hypertension, diabetes, or hyperlipidemia requiring medications, or atherosclerotic cardiovascular disease\n* Past or current diagnosis of a DSM-V eating disorder\n* Diagnosis of schizophrenia, bipolar disorder, or psychiatric hospitalization in the past 12 months\n* Pregnant at the time of the study.\n\nInclusion Criteria (HCPs) to complete feasibility surveys:\n\n* Clinical team member (physician or nurse practitioner, nurse, social worker, psychologist, health educator, medical assistant, dietitian) at the CHOA Hughes Spalding Adolescent Medicine Practice or the Grady Health System Teen Program\n* Practicing at one of the study sites at least twice per month on average over the past year\n\nExclusion Criteria (HCPs)\n\n* Member of the research study team",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "13 Years",
          "stdAges": [
            "CHILD",
            "ADULT",
            "OLDER_ADULT"
          ]
