        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "1) CBT for smoking cessation + personalized PA plan + Fitbit Versa 3 ®.",
              "type": "EXPERIMENTAL",
              "description": "The intervention will be delivered in groups (maximum 4 participants) for a total of 6 weeks. Sessions (1.5 hours) will take place once per week. Personalized PA objectives will be set during the treatment.\n\nParticipants in this arm will wear the Fitbit Versa 3® during the treatment (6 weeks).",
              "interventionNames": [
                "Behavioral: Cognitive-behavioral therapy for smoking cessation",
                "Behavioral: Personalized PA plan",
                "Device: Fitbit Versa 3"
              ]
            },
            {
              "label": "2) CBT for smoking cessation + personalized PA plan",
              "type": "ACTIVE_COMPARATOR",
              "description": "This intervention include the same components as described above. The exception will be that participants will not be requested to wear the Fitbit Versa 3®.",
              "interventionNames": [
                "Behavioral: Cognitive-behavioral therapy for smoking cessation",
                "Behavioral: Personalized PA plan"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Cognitive-behavioral therapy for smoking cessation",
              "description": "Treatment components will include psychoeducation on the consequences of tobacco use and the benefits of quitting; therapeutic commitment; self-monitoring of cigarette smoking; brief advice on healthy eating behaviors and sleep hygiene, physiological feedback (based on CO levels), training in self-control strategies, stimulus control, management of craving with alternative activities, diaphragmatic breathing, weekly personalized physical activity objectives, and relapse prevention strategies. The protocol consists of a nicotine fading procedure, which consists of a weekly reduction in nicotine intake of 30% (based on both tobacco brands and the number of cigarettes) from the first to the fifth session.",
              "armGroupLabels": [
                "1) CBT for smoking cessation + personalized PA plan + Fitbit Versa 3 ®.",
                "2) CBT for smoking cessation + personalized PA plan"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Personalized PA plan",
              "description": "The treatment provider will fix an objective (e.g. go for brisk walking for 30 minutes 3 times this week) for each participant every week according to his/her current PA level, time availability, likes, and fitness level.",
              "armGroupLabels": [
                "1) CBT for smoking cessation + personalized PA plan + Fitbit Versa 3 ®.",
                "2) CBT for smoking cessation + personalized PA plan"
              ]
            },
            {
              "type": "DEVICE",
              "name": "Fitbit Versa 3",
              "description": "Wearable activity tracker with the functionalities of a watch function, including time, date, calendar, and weather (connection to the internet is required). Physical activity monitoring (steps per day, active minutes per day, plants climbed, heart rate monitoring, time, intensity, caloric expenditure, and exercise type of exercise session), sleep monitoring (sleep time, sleep phases time, sleep quality), stress levels managing and guided breathing application are the main health-related functionalities.",
              "armGroupLabels": [
                "1) CBT for smoking cessation + personalized PA plan + Fitbit Versa 3 ®."
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Acceptability of the activity tracker",
              "description": "Acceptability of the activity tracker is measured using the Participant Experience Questionnaire (PEQ) at the end of treatment. This scale ranges from 10 to 50. A higher score means higher acceptability.",
              "timeFrame": "End-of-treatment (6-weeks)"
            },
            {
              "measure": "Tobacco use",
              "description": "This variable is operationalized as changes in cigarettes/day, carbon monoxide (CO) changes, and self-reported and verified abstinence (i.e., ≤4 ppm).",
              "timeFrame": "From Enrollment to End-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            },
            {
              "measure": "Feasibility of treatment and activity tracker use",
              "description": "Feasibility is operationalized as treatment completion, attendance to sessions and adherence to Fitbit Versa 3 use.",
              "timeFrame": "End-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            },
            {
              "measure": "Physical activity",
              "description": "Physical activity (PA) is operationalized as steps per day, plants climbed per day, distance covered per day (kilometers), light physical activity (minutes per day), moderate physical activity (minutes per week), vigorous physical activity (minutes per week), and sedentary time (hours per day). These outcomes will be measured using an adapted version of the International Physical Activity Questionnaire (IPAQ) and Fitbit Versa 3®.",
              "timeFrame": "In-treatment, from enrollment to end-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            },
            {
              "measure": "Activity tracker perceived utility",
              "description": "Perceived utility with the activity tracker is measured using dichotomous (yes/no) ad-hoc; questions about the utility of the activity tracker for smoking cessation, increasing physical activity, and improving sleep quality.",
              "timeFrame": "End-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Anxiety symptoms",
              "description": "Anxiety symptoms are measured using Generalized Anxiety Disorder-7 (GAD-7). This questionnaire ranges from 0 to 21. Higher punctuation means higher anxiety levels symptoms.",
              "timeFrame": "From Enrollment to End-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            },
            {
              "measure": "Depression symptoms",
              "description": "Depression symptoms are measured using the Patient Health Questionnaire-9 (PHQ-9). This questionnaire ranges from 0 to 14. A higher punctuation means higher depression symptom levels.",
              "timeFrame": "From Enrollment to End-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            },
            {
              "measure": "Hypothetical demand for cigarettes",
              "description": "CPT (Cigarette purchase task) (Items: Maximum number of cigarettes smoked per day, maximum expenditure in cigarettes per day and maximum expenditure per pack)",
              "timeFrame": "Enrollment"
            },
            {
              "measure": "Emotional dysregulation of negative valence emotions",
              "description": "Emotional dysregulation of negative emotions is measured with the Difficulties in emotion regulation scale-16 (DERS-16). This scale ranges from 16 to 80 points. A higher score means more difficulties in emotion regulation of negative valence emotions.",
              "timeFrame": "From Enrollment to End-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            },
            {
              "measure": "Emotional dysregulation of positive valence emotions",
              "description": "Emotional dysregulation of positive emotions is measured with Difficulties in Emotion Regulation Scale-Positive (DERS-P). This scale ranges from 13 to 65. A higher score means more difficulties in emotion regulation of positive valence emotions.",
              "timeFrame": "From Enrollment to End-of-treatment (6-weeks), one-, three-, six-, -month follow-up."
            },
            {
              "measure": "Delay Discounting",
              "description": "Single and cross-commodity computerized Delay Discounting task of money and tobacco (delay of one day, one week, one month and six month time)",
