          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Hallucinogens and psychoactive substances",
              "description": "One of the following or placebo will be given:\n\nHallucinogens: DMT, 4-phosphoryloloxy-N-diethyltryptamine, dipropyltryptamine (DPT), ketamine, dextromethorphan, mescaline, PCP, psilocybin, salvinorin-A, LSD, d-lysergic acid amide (LSA), MDMA, cannabis\n\nSedatives/anxiolytics: alprazolam, diazepam, lorazepam, secobarbital, temazepam, triazolam, zolpidem\n\nAntihistamines: diphenhydramine, chlorpheniramine\n\nStimulants: d-amphetamine, caffeine, ephedrine, methylphenidate, diethylproprion\n\nOpioids: heroin, morphine, oxycodone, hydrocodone, methadone, codeine\n\nOther: alcohol, scopolamine, nicotine\n\nEach volunteer will receive a hallucinogen on at least one of five sessions. More drugs are listed than will be administered to increase the degree to which volunteers are \"blind\" to the drugs being studied. It is important that the volunteer and research staff be blinded to specific drug conditions to minimize confounding the results with expectations about the nature of drug effects.",
              "armGroupLabels": [
                "Female volunteers",
                "Male volunteers"
              ],
              "otherNames": [
                "Hallucinogens",
                "Sedatives & anxiolytics",
                "Antihistamines",
                "Stimulants",
                "Opioids",
                "Alcohol",
                "Scopolamine",
                "Nicotine"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Rating of \"Drug Liking\" on the End of Day Questionnaire",
              "description": "Volunteer-completed questionnaire assesses the subjective liking of the drug condition for the session",
              "timeFrame": "Completed at the end of the experimental session (approximately 8 hours after capsule administration)"
            }
          ],
          "secondaryOutcomes": [
