          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Motivational Interviewing Intervention for ETS Reduction",
              "description": "The intervention is designed to motivate caregivers to reduce a child's ETS exposure by establishing a complete home and car smoking ban and by considering smoking cessation. Caregivers will receive 2 home visits \\& 2 telephone session, both with a health counselor. Caregivers will be provided with feedback on air nicotine levels and child salivary cotinine levels. The main target for the intervention will be the primary caregiver of the child because the primary caregiver is ultimately responsible for protecting the child from ETS exposure. Any and all household members may participate in the intervention visits but are not required to do so.",
              "armGroupLabels": [
                "Behavioral"
              ]
            },
            {
