          "briefTitle": "Effect of Peer Mentoring and Blood Pressure Self-monitoring on Hypertension Control.",
          "officialTitle": "Effectiveness of Peer Mentoring and Blood Pressure Self-monitoring for Blood Pressure Control in Vulnerable Population in Argentina. A Randomized Clinical Trial."
        },
        "statusModule": {
          "statusVerifiedDate": "2017-09",
          "overallStatus": "COMPLETED",
