              "label": "Peer mentoring",
              "type": "EXPERIMENTAL",
              "description": "Peers will be patients with hypertension that have already been adequately controlled within the last six months. They will be selected within each center by the staff of the center and invited to participate in the study.",
              "interventionNames": [
                "Behavioral: Peer mentoring"
              ]
            },
            {
              "label": "Self-monitoring",
              "type": "EXPERIMENTAL",
              "description": "Each participant will receive a blood pressure monitor. The study nurse will teach the participant on how to use the device.",
              "interventionNames": [
                "Behavioral: Self-monitoring"
              ]
            },
            {
              "label": "Control",
              "type": "NO_INTERVENTION",
              "description": "Usual care"
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Peer mentoring",
              "description": "Peers will be assigned to participants according to common socio-demographic characteristics. Each peer will be assigned up to 5 participants.",
              "armGroupLabels": [
                "Peer mentoring"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Self-monitoring",
              "description": "Along with providing patients with a BP monitor, a \"commitment contract\" will be signed, in which participants commit themselves to measure their blood pressure at home at least once a week during the 3 months of the intervention. Each participant will be given a form to weekly recording their blood pressure values.",
              "armGroupLabels": [
                "Self-monitoring"
              ]
            }
          ]
        },
