          "briefTitle": "Galantamine Effects on Nicotine Responses in Smokers",
          "officialTitle": "Galantamine Effects on Nicotine Responses in Smokers"
        },
        "statusModule": {
          "statusVerifiedDate": "2015-07",
          "overallStatus": "COMPLETED",
