              ]
            }
          ],
          "interventions": [
            {
              "type": "DEVICE",
              "name": "Individualized carbon monoxide (iCO) monitor",
              "description": "a personal monitor for a breath test for carbon monoxide (CO)",
              "armGroupLabels": [
                "COach2Quit"
              ]
            },
            {
              "type": "OTHER",
