              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Smoking Status Using a Point of Care Test for Measuring Carbon Monoxide (CO)",
              "description": "A point of care test for measuring carbon monoxide (CO) will be conducted via the piCO Smokerlyzer from OPS Medical, designed specifically for smoking cessation programs and tobacco control programs. Carbon monoxide will be measured in an exhaled breath in parts-per-million (ppm). A reading of ≤ 10ppm will indicate abstinence.",
              "timeFrame": "baseline"
            },
            {
              "measure": "Smoking Status Using a Point of Care Test for Measuring Carbon Monoxide (CO)",
              "description": "A point of care test for measuring carbon monoxide (CO) will be conducted via the piCO Smokerlyzer from OPS Medical, designed specifically for smoking cessation programs and tobacco control programs. Carbon monoxide will be measured in an exhaled breath in parts-per-million (ppm). A reading of ≤ 10ppm will indicate abstinence.",
              "timeFrame": "1 month"
            },
            {
              "measure": "Number of Participants With Color Change for Urine Test for Measuring Cotinine",
              "description": "A point of care urine test for measuring cotinine will also be conducted via the SmokeScreen® test from GFC Diagnostics Ltd. to verify smoking status. A color change to red/orange indicates a positive sample, with a darker color indicating greater nicotine intake.",
              "timeFrame": "baseline"
            },
            {
              "measure": "Number of Participants With Color Change for Urine Test for Measuring Cotinine",
              "description": "A point of care urine test for measuring cotinine will also be conducted via the SmokeScreen® test from GFC Diagnostics Ltd. to verify smoking status. A color change to red/orange indicates a positive sample, with a darker color indicating greater nicotine intake.",
              "timeFrame": "1 month"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Reasons for Quitting Scale",
              "description": "We used the Reasons for Quitting (RFQ) scale to measure motivation to quit smoking. The scale is used to measure intrinsic and extrinsic motivation for quitting smoking. Each item in the scale is evaluated using a 5-point Likert scale regarding how true the statement is about the participant's motivation to quit smoking (Not at all true, a little bit true, moderately true, quite true, extremely true). Each option takes on a numerical score from 0 (not at all true) to 4 (extremely true). Scores are summed across all items in the scale and divided by the number of items in the scale to obtain the RFQ score. The range of possible scores is 0 to 4. A higher score indicates greater motivation to quit smoking.",
              "timeFrame": "baseline"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* ≥18 years of age\n* current, daily smokers\n* agree to participate and anticipate to be living in Baltimore for at least 2 months\n* own a phone that is compatible with the app\n* be willing to set at baseline assessment a quit date within 2 weeks\n\nExclusion Criteria:\n\n* are suffering from any unstable medical condition precluding the use of the CO monitor (e.g. severe COPD)\n* are currently using smokeless tobacco including e-cigarettes\n* are currently using nicotine replacement therapy or other smoking cessation treatment\n* are pregnant, determined by participant self-report\n* have a negative baseline result on both urine cotinine AND CO monitor",
          "healthyVolunteers": false,
