        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Smoking Status Using a Point of Care Test for Measuring Carbon Monoxide (CO)",
              "description": "A point of care test for measuring carbon monoxide (CO) will be conducted via the piCO Smokerlyzer from OPS Medical, designed specifically for smoking cessation programs and tobacco control programs. Carbon monoxide will be measured in an exhaled breath in parts-per-million (ppm). A reading of ≤ 10ppm will indicate abstinence.",
              "populationDescription": "Thirteen participants were lost to follow-up (9 at the 14-day visit and 4 at the 30-day visit) and the sample size for the analysis was 89. There were no significant differences in baseline characteristics between participants lost to follow-up and participants who completed the study.",
              "reportingStatus": "POSTED",
              "paramType": "MEDIAN",
              "dispersionType": "Inter-Quartile Range",
              "unitOfMeasure": "parts per million",
              "timeFrame": "baseline",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Control",
                  "description": "A certified smoking cessation interventionist (SCI) will deliver standardized smoking cessation counseling using the National Cancer Institute (NCI) 5 A's model.\n\nCessation counseling: The advice to quit smoking message will follow NCI's 5 A's model for smoking cessation counseling. This is a simple smoking cessation counseling strategy with 5 discrete components: (1) Ask about smoking at every opportunity; (2) Advise the patient to quit smoking; (3) Assess readiness to quit; (4) Assist the patient in quitting; and (5) Arrange follow-up."
                },
                {
                  "id": "OG001",
                  "title": "COach2Quit",
                  "description": "A certified smoking cessation interventionist (SCI) will deliver standardized smoking cessation counseling using the National Cancer Institute's 5 A's model.\n\nParticipants in the COach2Quit arm will be provided with an individualized carbon monoxide (iCO) monitor along with instructions on the use of the monitor and the COach2Quit application.\n\nIndividualized carbon monoxide (iCO) monitor: a personal monitor for a breath test for carbon monoxide (CO)\n\nCOach2Quit smartphone application: This smartphone application works in conjunction with the iCO monitor\n\nCessation counseling: The advice to quit smoking message will follow NCI's 5 A's model for smoking cessation counseling. This is a simple smoking cessation counseling strategy with 5 discrete components: (1) Ask about smoking at every opportunity; (2) Advise the patient to quit smoking; (3) Assess readiness to quit; (4) Assist the patient in quitting; and (5) Arrange follow-up."
                }
              ],
