        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Salivary cotinine or anabasine testing (metabolites of nicotine)",
              "description": "The primary measure of smoking cessation will be prolonged abstinence for 6 months, which will be measured by salivary cotinine testing or by urinary anabasine testing (for those participants using nicotine replacement therapy). Saliva samples will be analyzed using semi-quantitative immunochromatographic assay test strips at the University of Pennsylvania. Urine samples will be analyzed using gas chromatography at the Associated Regional and University Pathologists (ARUP) Lab, at the University of Utah.",
              "timeFrame": "at 6 months following the patient selected target quit date."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Salivary cotinine or anabasine testing (metabolites of nicotine)",
              "description": "Another secondary outcome variable will be the proportion of participants achieving point prevalence abstinence at 14 days, 30 days, 6 months and 12 months after the quit date.",
              "timeFrame": "at 14 and 30 days, and 6 months following the patient selected target quit date and relapse rate 12 months after the target quit date."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Active smoker of 5 cigarettes per day for at least 6 months;\n* At least 18 years old;\n* Current full- or part-time employee of CVS or be a family member or friend of a current full- or part-time employee of CVS.\n\nExclusion Criteria:\n\n* Use a form of tobacco other than cigarettes while participating in the study (as this may influence biochemical testing);\n* Are unable or unwilling to access the internet;\n* Are unable to provide informed consent.\n* Due to the web-based nature of this study, people without reliable computer and internet access will also be excluded.",
