        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Treatment Period 1: Enhanced Self-Care (ESC)",
              "type": "ACTIVE_COMPARATOR",
              "description": "This arm includes participants who are randomized to ESC in Treatment Period 1.\n\nDepending on their response to Treatment 1 measured at 12 Weeks post-initial randomization, participants in this arm will stay on ESC or be randomized to augment ESC with an additional treatment during Treatment Period 2.",
              "interventionNames": [
                "Behavioral: Enhanced Self-Care (ESC)"
              ]
            },
            {
              "label": "Treatment Period 1: Acceptance and Commitment Therapy (ACT)",
              "type": "ACTIVE_COMPARATOR",
              "description": "This arm includes participants who are randomized to ACT in Treatment Period 1.\n\nDepending on their response to Treatment 1 measured at 12 Weeks post-initial randomization, participants in this arm will stay on ACT, augment ACT with an additional treatment, or switch to a new treatment during Treatment Period 2.",
              "interventionNames": [
                "Behavioral: Acceptance and Commitment Therapy (ACT)"
              ]
            },
            {
              "label": "Treatment Period 1: Evidence-Based Exercise and Manual Therapy (EBEM)",
              "type": "ACTIVE_COMPARATOR",
              "description": "This arm includes participants who are randomized to EBEM in Treatment Period 1.\n\nDepending on their response to Treatment 1 measured at 12 Weeks post-initial randomization, participants in this arm will stay on EBEM, augment EBEM with an additional treatment, or switch to a new treatment during Treatment Period 2.",
              "interventionNames": [
                "Behavioral: Evidence-Based Exercise and Manual Therapy (EBEM)"
              ]
            },
            {
              "label": "Treatment Period 1: Duloxetine",
              "type": "ACTIVE_COMPARATOR",
              "description": "This arm includes participants who are randomized to Duloxetine in Treatment Period 1.\n\nDepending on their response to Treatment 1 measured at 12 Weeks post-initial randomization, participants in this arm will stay on Duloxetine, augment Duloxetine with an additional treatment, or switch to a new treatment during Treatment Period 2.",
              "interventionNames": [
                "Drug: Duloxetine"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Enhanced Self-Care (ESC)",
              "description": "The Enhanced Self-Care intervention will be comprised of educational modules on evidence-based cognitive-behavioral self-management skills for pain. These modules will be provided digitally for self-administration over a period of 12 weeks. There will be no therapist associated with the delivery of these educational materials; however, after the first four modules, email or text messages will be used to make personalized recommendations for accessing additional modules based upon identified problems from the baseline assessment. Additionally, the walking program module will utilize Fitbit step tracking to allow participants to monitor their walking progress.",
              "armGroupLabels": [
                "Treatment Period 1: Enhanced Self-Care (ESC)"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Acceptance and Commitment Therapy (ACT)",
              "description": "ACT is a form of cognitive behavioral therapy that is well established for the treatment of chronic pain. The goal of ACT is to build psychological flexibility thereby interrupting pain avoidance behavior patterns. Participants randomized to ACT will take part in 12 sessions over the course of 12 weeks. Sessions will be delivered as a combination of 4 remote face-to-face visits with a therapist and 8 therapist-supported online sessions (self-directed online modules supported by provider coaching). Online sessions will focus on helping participants accept pain, connect with negative thoughts and emotions, develop mindfulness and identify and commit to values and goals that are important to them. During face-to-face sessions with the therapist, participants will be encouraged to share their experience of skills practice and mastery, provide examples of skill use at home, and describe what barriers they encountered.",
              "armGroupLabels": [
                "Treatment Period 1: Acceptance and Commitment Therapy (ACT)"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Evidence-Based Exercise and Manual Therapy (EBEM)",
              "description": "Licensed physical therapists (PTs) or Doctors of Chiropractic (DCs) will rely on evidence-based guidance to direct decision-making on the particular type of manual and exercise therapy that may be best suited to an individual study participant. Special attention will be paid to the clinician's choice of language in regard to the purpose and expected outcomes of manual therapy in order to avoid enhancing catastrophizing ideations or preference for passive interventions. A total of 10 sessions will be provided over an 8-week treatment period. Two sessions per week are provided in the first two weeks followed by weekly sessions over the next 6 weeks. Treatment sessions will last approximately 60 minutes each.",
              "armGroupLabels": [
                "Treatment Period 1: Evidence-Based Exercise and Manual Therapy (EBEM)"
              ]
            },
            {
              "type": "DRUG",
              "name": "Duloxetine",
              "description": "Duloxetine is a serotonin norepinephrine reuptake inhibitor (SNRI) that is FDA-approved for use in Chronic Low-Back Pain, and, as such, is included as a recommended therapy in nearly all current treatment guidelines for low back pain. Study participants will be treated with duloxetine for 12 weeks during the active treatment phase. At the time of randomization, the approved drug pharmacy at each study site will dispense between 185 and 192 duloxetine 30 mg capsules and provide to participants. This will ensure enough capsules to maintain up to a 60 mg dosage through the 12-week intervention phase and to taper the dose in the 13th week if needed.",
              "armGroupLabels": [
                "Treatment Period 1: Duloxetine"
              ],
              "otherNames": [
                "Cymbalta"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Patient-Reported Pain Intensity and Interference Score",
              "description": "Patient-reported pain intensity and interference is measured by the Pain, Enjoyment of Life, and General Activity (PEG) scale. The PEG is a series of 3 questions. Results range from -10 to 10, with higher scores indicating increased pain intensity and interference at 24 Weeks compared to Baseline.",
              "timeFrame": "Baseline, 24 Weeks"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Patient-Reported Outcomes Measurement Information System-Pain Interference",
              "description": "Pain interference is measured by the 4-item PROMIS (Patient-Reported Outcomes Measurement Information System) Pain Interference scale (PROMIS-PI, 4a). The PROMIS-PI, 4a is a series of 4 questions, and measures self-reported consequences of pain on relevant aspects of one's life. Results range from -34 to 34 (t-scores range from 41.6 to 75.6). For each t-score, 50 indicates the population mean with a standard deviation of 10. Lower scores indicate lower pain interference and a better outcome. PROMIS measures are not used for clinical decision making but to describe participant symptoms.",
              "timeFrame": "Baseline, 24 Weeks"
            },
            {
              "measure": "Number of Participants Self-Reporting Taking Opioids",
              "description": "The number of participants self-reporting taking opioids (\"Yes\" response) is measured by a single question, \"Are you currently taking any opioid pain medication on a daily basis?\".",
              "timeFrame": "24 Weeks"
            },
            {
              "measure": "Patient-Reported Outcomes Measurement Information System- Physical Function",
              "description": "Physical function is measured by the Patient-Reported Outcomes Measurement Information System-Physical Function (PROMIS-PF) Short Form 6b. The PROMIS-PF Short Form 6b is a series of 6 questions. T-scores range from 21.6 to 58.7 and for each t-score, 50 indicates the population mean with a standard deviation of 10. Results range from -37.1 to 37.1, with higher physical function scores indicating a better outcome and increased physical functioning at 24 Weeks compared to Baseline. A higher physical function is the better outcome. PROMIS measures are not used for clinical decision making but to describe participant symptoms.",
              "timeFrame": "Baseline, 24 Weeks"
            },
            {
              "measure": "Patient-Reported Outcomes Measurement Information System (PROMIS) - Depression Score",
              "description": "Depression score is measured by the Patient-Reported Outcomes Measurement Information System (PROMIS) 4-item depression scale from the PROMIS 29 profile. The PROMIS 4-item depression scale from the PROMIS 29 profile is a series of 4 questions. T-scores range from 41.0 to 79.4), and for each t-score, 50 indicates the population mean with a standard deviation of 10. Results range from -38.4 to 38.4, with higher scores indicating increased depression at 24 Weeks compared to Baseline. A lower depression score is the better outcome. PROMIS measures are not used for clinical decision making but to describe participant symptoms.",
              "timeFrame": "Baseline, 24 Weeks"
            },
            {
              "measure": "Patient-Reported Outcomes Measurement Information System-Emotional Distress-Anxiety",
              "description": "Anxiety score is measured by the Patient-Reported Outcomes Measurement Information System-Emotional Distress-Anxiety (PROMIS-EDA) scale 4a. The PROMIS-EDA 4a is a series of 4 questions. T-scores range from 40.3 to 81.6, and for each t-score, 50 indicates the population mean with a standard deviation of 10. Results range from -41.3 to 41.3, with higher scores indicating increased anxiety at 24 Weeks compared to Baseline. A lower anxiety score is the better outcome. PROMIS measures are not used for clinical decision making but to describe participant symptoms.",
              "timeFrame": "Baseline, 24 Weeks"
            },
            {
              "measure": "Patient-Reported Outcomes Measurement Information System - Sleep Disturbance",
              "description": "Sleep disturbance is measured by the Patient-Reported Outcomes Measurement Information System (PROMIS) short form 6a. The PROMIS short form 6a is a series of 6 questions. T-scores range from 31.7 to 76.1 and for each t-score, 50 indicates the population mean with a standard deviation of 10). Results range from -44.4 to 44.4, with higher scores indicating increased sleep disturbance at 24 Weeks compared to Baseline. A lower sleep disturbance score is the better outcome. PPROMIS measures are not used for clinical decision making but to describe participant symptoms.",
              "timeFrame": "Baseline, 24 Weeks"
            },
            {
              "measure": "Sleep Duration",
              "description": "Sleep duration is measured by the Back Pain Consortium (BACPAC) sleep duration question, \"During the past month, how many hours and minutes of actual sleep did you get at night? (This may be different than the number of hours and minutes you spent in bed).\" Participants respond with a number of hours and minutes. Results range from -24 to 24 hours, with higher number of hours indicating increased sleep duration at 24 Weeks compared to Baseline.",
              "timeFrame": "Baseline, 24 Weeks"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\nTo be eligible, an individual must meet all of the following inclusion criteria:\n\n* Ability to read and understand English\n* Provision of signed and dated informed consent form(s)\n* Willing and able to receive study-related messages and survey links via email\n* Willing and able to receive study-related phone calls\n* Age 18 years old or older\n* Low-back pain for at least 3 months and occurring on at least half the days in the past 6 months\n* Contraindicated to no more than one of the study interventions at the time of eligibility assessment(s)\n* Eligible to receive at least three of the four study interventions and willing to receive any intervention for which they are eligible\n* A PEG score 4 or higher prior to the Run-in period\n* Willing and able to undergo required phenotyping\n* Regular reliable access to an internet-enabled device such as a smart phone, tablet, or laptop computer\n* Meet Run-in period engagement eligibility criteria:\n\n  o Completion of two Run-in study information modules prior to period 1 randomization (Visit 0)\n* Low-back pain more severe than pain in other parts of the body\n* Available to complete the full study protocol (approximately 9 months)\n\nExclusion Criteria:\n\nAn individual who meets any of the following criteria will be excluded from participation in this study:\n\n* Pregnant at the time of Visit 0 (Baseline)\n* Affirmative participant response to any of the following conditions:\n\n  * Progressive neurodegenerative disease\n  * History of discitis osteomyelitis (spine infection) or spine tumor\n  * History of ankylosing spondylitis, rheumatoid arthritis, polymyalgia rheumatica, psoriatic arthritis, or lupus\n  * History of cauda equina syndrome or spinal radiculopathy with functional motor deficit (strength \\<4/5 on manual motor testing)\n  * Diagnosis of any vertebral fracture in the last 6 months\n  * Osteoporosis requiring pharmacologic treatment other than vitamin D, calcium supplements, or bisphosphonates.\n  * History of any bone-related cancer or cancer that metastasized to the bone\n  * Currently in treatment for any non-skin cancer or plan to start non-skin cancer treatment in the next 12 months\n  * History of any non-skin cancer treatment in the last 24 months\n  * Visual or hearing difficulties that would preclude participation\n  * Uncontrolled drug/alcohol addiction\n  * Individuals actively pursuing disability or workers compensation or involved in active personal injury-related litigation\n  * Currently participating in another interventional pain study\n* Any condition that, in the opinion of the investigator, would preclude the patient from being able to safely participate in in the trial",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
