        "participantFlowModule": {
          "preAssignmentDetails": "While 1014 participants in total were enrolled in the trial, 805 were randomized. This was due to participant withdrawal or participant ineligibility during the run-in period between the enrollment visit and randomization.",
          "groups": [
            {
              "id": "FG000",
              "title": "Acceptance and Commitment Therapy (ACT) Alone",
              "description": "This arm included both participants who had a strong response to Acceptance and Commitment Therapy (ACT) in Period 1 and participants who were not assessed for response at the end of Period 1. In Period 1, participants randomized to ACT took part in 12 therapy sessions over the course of 12 weeks. Each participant was scheduled for a combination of 4 remote face-to-face visits and 8 therapist-supported online sessions, which included a self-directed module combined with personalized provider coaching delivered via an online messaging system. In Period 2, strong responders were encouraged to continue to practice ACT skills at home without therapist supervision and were given access to an additional 11 ACT audio modules."
            },
            {
              "id": "FG001",
              "title": "ACT Plus Duloxetine, Moderate Treatment Response",
              "description": "This arm included participants who had a moderate response to ACT in Period 1 and started Duloxetine in Period 2 while continuing ACT treatment."
            },
            {
              "id": "FG002",
              "title": "ACT Plus Evidence Based Exercise and Manual Therapy (EBEM), Moderate Period 1 Treatment Response",
              "description": "This arm included participants who had a moderate response to ACT in Period 1 and started Evidence Based Exercise and Manual Therapy (EBEM) treatment in Period 2 while continuing ACT."
            },
            {
              "id": "FG003",
              "title": "ACT Plus Enhanced Self-Care Therapy (ESC), Moderate Period 1 Treatment Response",
              "description": "This arm included participants who had a moderate response to ACT in Period 1 and started Enhanced Self-Care Therapy (ESC) treatment in Period 2 while continuing ACT."
            },
            {
              "id": "FG004",
              "title": "ACT Plus Duloxetine, Low Period 1 Treatment Response",
              "description": "This arm included participants who had a low response to ACT in Period 1 and started Duloxetine treatment in Period 2 while continuing ACT."
