        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Patient-Reported Pain Intensity and Interference Score",
              "description": "Patient-reported pain intensity and interference is measured by the Pain, Enjoyment of Life, and General Activity (PEG) scale. The PEG is a series of 3 questions. Results range from -10 to 10, with higher scores indicating increased pain intensity and interference at 24 Weeks compared to Baseline.",
              "populationDescription": "The analysis population is the all-randomized population to Stage 1 interventions.",
              "reportingStatus": "POSTED",
              "paramType": "LEAST_SQUARES_MEAN",
              "dispersionType": "95% Confidence Interval",
              "unitOfMeasure": "score on a scale",
              "timeFrame": "Baseline, 24 Weeks",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Stage 1: Acceptance and Commitment Therapy (ACT)",
                  "description": "ACT is a form of cognitive behavioral therapy that is well established for the treatment of chronic pain. The goal of ACT is to build psychological flexibility thereby interrupting pain avoidance behavior patterns. Participants randomized to ACT will take part in 12 sessions over the course of 12 weeks. Sessions will be delivered as a combination of 4 remote face-to-face visits with a therapist and 8 therapist-supported online sessions (self-directed online modules supported by provider coaching). Online sessions will focus on helping participants accept pain, connect with negative thoughts and emotions, develop mindfulness and identify and commit to values and goals that are important to them. During face-to-face sessions with the therapist, participants will be encouraged to share their experience of skills practice and mastery, provide examples of skill use at home, and describe what barriers they encountered."
                },
                {
                  "id": "OG001",
                  "title": "Stage 1: Duloxetine",
                  "description": "Duloxetine is a serotonin norepinephrine reuptake inhibitor (SNRI) that is FDA-approved for use in Chronic Low-Back Pain, and, as such, is included as a recommended therapy in nearly all current treatment guidelines for low back pain. Study participants will be treated with duloxetine for 12 weeks during the active treatment phase. At the time of randomization, the approved drug pharmacy at each study site will dispense between 185 and 192 duloxetine 30 mg capsules and provide to participants. This will ensure enough capsules to maintain up to a 60 mg dosage through the 12-week intervention phase and to taper the dose in the 13th week if needed."
                },
                {
                  "id": "OG002",
                  "title": "Stage 1: Evidence Based Exercise and Manual Therapy (EBEM)",
                  "description": "Licensed physical therapists (PTs) or Doctors of Chiropractic (DCs) will rely on evidence-based guidance to direct decision-making on the particular type of manual and exercise therapy that may be best suited to an individual study participant. Special attention will be paid to the clinician's choice of language in regard to the purpose and expected outcomes of manual therapy in order to avoid enhancing catastrophizing ideations or preference for passive interventions. A total of 10 sessions will be provided over an 8-week treatment period. Two sessions per week are provided in the first two weeks followed by weekly sessions over the next 6 weeks. Treatment sessions will last approximately 60 minutes each."
                },
                {
                  "id": "OG003",
                  "title": "Stage 1: Enhanced Self-Care Therapy (ESC)",
                  "description": "The Enhanced Self-Care intervention will be comprised of educational modules on evidence-based cognitive-behavioral self-management skills for pain. These modules will be provided digitally for self-administration over a period of 12 weeks. There will be no therapist associated with the delivery of these educational materials; however, after the first four modules, email or text messages will be used to make personalized recommendations for accessing additional modules based upon identified problems from the baseline assessment. Additionally, the walking program module will utilize Fitbit step tracking to allow participants to monitor their walking progress."
                }
              ],
