      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "We phone-screened 101 waterpipe tobacco (WPT) smoker respondents; 54 were eligible and were enrolled; 4 withdrew before the home visit (due to travel/change of mind).\n\nWe phone-screened 51 non-smoker respondents; 31 were eligible and were enrolled; 1 non-smoker dropped out before the home visit (due to school/work schedule); 5 were excluded because of potential exposure to tobacco secondhand smoke (SHS) based on exhaled carbon monoxide (eCO) cut-off levels ≥3.6 ppm.(Deveci et al., 2004)",
          "groups": [
            {
              "id": "FG000",
              "title": "Waterpipe Tobacco (WPT) Smoking",
              "description": "In a repeated measures design, 50 adult male and female exclusive waterpipe tobacco (WPT) smokers will smoke weekly over a 3-week study period with 3 WPT smoking practices.\n\nWPT smoking: In a repeated measures design, 50 adult male and female exclusive WPT smokers will smoke WPT weekly over a 3-week study period with 3 WPT smoking practices as follows: 1) using room temperature water in the waterpipe (WP) jar, 2) adding ice cubes to the water in the WP jar, and 3) using a charcoal-free electronic WP head to heat the tobacco. Six Spot first morning urine samples will be provided by participants. Two urine samples per each of the 3 smoking sessions. Urine samples will be provided on the day of the WPT smoking session and the following day. Physiological measures will be taken at Baseline during the office visit and before and after each of the 3 WP tobacco smoking sessions."
            },
            {
              "id": "FG001",
              "title": "Control",
              "description": "A total of 25 adult male and female nonsmokers will be recruited as a control."
            }
          ],
