        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Comparing Cotinine Pre-to-post Change Between 2 Waterpipe Smoking Sessions: Heating Waterpipe Tobacco by (a) Charcoal vs (b) an Electric Head",
              "description": "Investigators will assess change in creatinine-adjusted urinary levels of cotinine (a metabolite of the addictive drug nicotine) in ng/mL, from pre-to post, at each of 2 waterpipe tobacco smoking sessions. For each of the 2 smoking sessions, smokers will provide two first morning spot urine samples--the day of the smoking session and the following morning. The two waterpipe tobacco smoking sessions are as follows: 1) using charcoal to heat the tobacco, and 2) using a charcoal-free electronic waterpipe head to heat the tobacco.",
              "populationDescription": "Participants will be recruited via intercept interviews from San Diego County, CA communities. Inclusion Criteria for Participants: 1) Adult waterpipe smoker: A male or female, 18 years or older, who smokes WP tobacco exclusively, smokes at least 1 WP head per month, and smokes at least 1 WP head per WP smoking session, smokes WP at home, agrees to smoke Starbuzz WP tobacco, and lives in a 'smoker home'; 2) Adult non-smoker: A male or female, 18 years or older, who lives in a 'non-smoker home'.",
              "reportingStatus": "POSTED",
              "paramType": "GEOMETRIC_MEAN",
              "dispersionType": "95% Confidence Interval",
              "unitOfMeasure": "ng/mL",
              "timeFrame": "On 2 days for each of two smoking sessions, smokers will provide 2 first morning spot urine samples--one urine sample on the morning of the day of the smoking session, and one urine sample on the morning of the following day.",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Charcoal-heated Waterpipe Smoking",
                  "description": "In a repeated measures design, 50 adult male and female exclusive WP smokers will smoke WP tobacco during the smoking session at their own home, using the traditional charcoal to heat the tobacco.\n\nTwo spot first morning urine samples will be provided by participants. Urine samples will be provided on the day of the WP tobacco smoking session and on the following day. Physiological measures will be taken before and after the WP tobacco smoking session."
                },
                {
                  "id": "OG001",
                  "title": "Electric-head-heated Waterpipe Smoking",
                  "description": "In a repeated measures design, 50 adult male and female exclusive WP smokers will smoke WP tobacco during the smoking session at their own home, using the traditional charcoal to heat the tobacco.\n\nTwo spot first morning urine samples will be provided by participants. Urine samples will be provided on the day of the WP tobacco smoking session and on the following day. Physiological measures will be taken before and after the WP tobacco smoking session."
                }
              ],
              "denoms": [
                {
                  "units": "Participants",
                  "counts": [
                    {
                      "groupId": "OG000",
                      "value": "50"
                    },
                    {
                      "groupId": "OG001",
                      "value": "50"
                    }
                  ]
                }
              ],
              "classes": [
                {
                  "categories": [
                    {
                      "measurements": [
                        {
                          "groupId": "OG000",
                          "value": "34.9",
                          "lowerLimit": "24.2",
                          "upperLimit": "50.5"
                        },
                        {
                          "groupId": "OG001",
                          "value": "26.4",
                          "lowerLimit": "18.3",
                          "upperLimit": "38.0"
                        }
                      ]
                    }
                  ]
                }
              ],
              "analyses": [
                {
                  "groupIds": [
                    "OG000",
                    "OG001"
                  ],
                  "nonInferiorityType": "OTHER",
                  "pValue": "0.115",
                  "statisticalMethod": "Wilcoxon signed-rank test",
                  "paramType": "z score",
                  "paramValue": "1.578",
                  "ciNumSides": "TWO_SIDED",
                  "otherAnalysisDescription": "We used the Wilcoxon signed-rank test (two-tailed alpha level p \\< 0.05), appropriate for within-subjects tests, to determine whether the pre-to-post change in biomarker levels for the Charcoal-heated tobacco smoking session (n=50) significantly different from the pre-to-post change in biomarker levels for the Electric Head-heated tobacco smoking session (using the same 50 participants after a weeklong washout period)."
                }
              ]
            },
            {
              "type": "PRIMARY",
