          "briefTitle": "Combined Effects of Balance and Cognitive Training in Patients With Multiple Sclerosis",
          "officialTitle": "Combined Effects of Balance and Cognitive Training on Executive Functions, Balance and Quality of Life in Patients With Multiple Sclerosis"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-02",
          "overallStatus": "RECRUITING",
          "expandedAccessInfo": {
