        },
        "organization": {
          "fullName": "Aga Khan University",
          "class": "OTHER"
        },
        "briefTitle": "CSF Free Kappa Light Chain for The Diagnosis of Demyelinating Disorders",
        "officialTitle": "CSF Free Kappa Light Chain for The Diagnosis of Demyelinating Disorders Taking Oligoclonal Banding Via Isoelectric Focusing Electrophoresis as Gold Standard: A Laboratory Study"
      },
      "statusModule": {
        "statusVerifiedDate": "2022-04",
        "overallStatus": "COMPLETED",
        "expandedAccessInfo": {
          "hasExpandedAccess": false
        },
        "startDateStruct": {
