        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Recommended Phase II Dose (RP2D)",
              "populationDescription": "The recommended phase II dose was determined during the phase 1b portion of the study, so only participants from the phase 1b cohorts are included for analysis.",
              "reportingStatus": "POSTED",
              "paramType": "NUMBER",
              "unitOfMeasure": "milligrams",
              "timeFrame": "Up to 28 days",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Phase 1b Cohorts",
                  "description": "Patients receive telaglenastat hydrochloride PO BID and osimertinib PO QD (starting cycle 1 day 16 of phase I). Patients undergo blood sample collection and may undergo x-ray imaging, CT scan, MRI, or PET scan throughout the study. Cycles repeat every 28 days in the absence of disease progression or unacceptable toxicity.\n\nBiospecimen Collection: Undergo blood sample collection\n\nComputed Tomography: Undergo CT scan\n\nMagnetic Resonance Elastography: Undergo MRI\n\nOsimertinib: Given PO\n\nPositron Emission Tomography: Undergo PET scan\n\nTelaglenastat Hydrochloride: Given PO\n\nX-Ray Imaging: Undergo x-ray imaging"
                }
              ],
              "denoms": [
                {
                  "units": "Participants",
                  "counts": [
                    {
                      "groupId": "OG000",
                      "value": "12"
                    }
                  ]
                }
              ],
              "classes": [
                {
                  "title": "Telaglenastat (CB-839) HCl",
                  "categories": [
                    {
                      "measurements": [
                        {
                          "groupId": "OG000",
                          "value": "800"
                        }
                      ]
                    }
                  ]
                },
                {
                  "title": "Osimertinib (AZD9291)",
                  "categories": [
                    {
                      "measurements": [
