          "briefTitle": "Real-world Study of HER2-overexpressed Advanced Solid Tumors After Progression of First-line Standard Therapy",
          "officialTitle": "A Non-interventional, Multi-cohort, Multi-center, Prospective Real-world Study of Treatment Pattern and Clinical Outcomes in Patients With HER2-overexpressed Advanced Solid Tumors After Progression of First-line Standard Therapy"
        },
        "statusModule": {
          "statusVerifiedDate": "2022-12",
          "overallStatus": "UNKNOWN",
          "lastKnownStatus": "NOT_YET_RECRUITING",
