            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Cohort1",
              "description": "Cohort1: About 186 patients with histologically or cytologically confirmed gastric/gastroesophageal junction (GEJ) adenocarcinoma with HER2 overexpression who received a regimen containing Disitamab Vedotin;",
              "interventionNames": [
                "Drug: Disitamab Vedotin"
              ]
            },
            {
              "label": "Cohort2",
              "description": "Cohort2: About 80 patients with histologically or cytologically confirmed HER2-overexpressed gastric cancer /GEJ adenocarcinoma who received an investigator-selected regimen in addition to Disitamab Vedotin;",
              "interventionNames": [
                "Drug: Disitamab Vedotin"
              ]
            },
            {
              "label": "Cohort3",
              "description": "Cohort3: Approximately 40 patients with other advanced solid tumors histologically or cytologically confirmed with HER2-overexpression and receiving a regimen containing Disitamab Vedotin.",
              "interventionNames": [
                "Drug: Disitamab Vedotin"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Disitamab Vedotin",
              "description": "Cohort 1: received a regimen containing Disitamab Vedotin. Cohort 2: received an investigator-selected regimen in addition to Disitamab Vedotin; Treatment options selected by the investigator: no treatment containing Disitamab Vedotin was given, and other systemic antitumor agents (including chemotherapy, such as paclitaxel, docetaxel, irinotecan, and fluorouracil) were selected by the investigator in line with clinical practice. Targeted therapy: such as apatinib, ramucirumab; Combination therapy: ramucirumab + paclitaxel; Immune checkpoint inhibitors such as PD1/PD-L1); Cohort 3: receiving a regimen containing Disitamab Vedotin.",
              "armGroupLabels": [
                "Cohort1",
