          },
          "briefTitle": "Radiation Therapy, Chemotherapy, and Bevacizumab in Treating Patients With Recurrent, Unresectable or Stage III or Stage IV Non-Small Cell Lung Cancer",
          "officialTitle": "Phase II Study of Radiation Followed by Paclitaxel, Carboplatin, and Bevacizumab (PCA) in Patients With Stage IIIB and IV Squamous Non-Small Cell Lung Cancer"
        },
        "statusModule": {
          "statusVerifiedDate": "2012-07",
          "overallStatus": "TERMINATED",
          "whyStopped": "Principal Investigator felt risk to patients was too high.",
          "startDateStruct": {
            "date": "2006-05"
          },
          "primaryCompletionDateStruct": {
