        },
        "descriptionModule": {
          "briefSummary": "The primary objective of this study is to estimate the frequency of FGFR2 fusions in archived intrahepatic cholangiocarcinoma (iCCA) or mixed hepatocellular-cholangiocarcinoma (HCC-CCA) tumor samples",
          "detailedDescription": "This is a non-interventional, observational study of archived human tissue samples; no surgical procedures will be required and no treatment will be provided as part of this study. Approximately 150 archived tissue samples obtained from patients with iCCA or mixed HCC-CCA will be analyzed for somatic alteration status and will include cholangiocarcinoma-specific FGFR2 fusion isoforms."
        },
        "conditionsModule": {
          "conditions": [
            "Intrahepatic Cholangiocarcinoma",
            "Mixed Hepatocellular Cholangiocarcinoma",
            "Cholangiocarcinoma"
          ],
          "keywords": [
            "FGFR2 fusion",
            "iCCA",
            "mixed HCC-CCA",
            "Intrahepatic Cholangiocarcinoma",
            "Mixed Hepatocellular Cholangiocarcinoma",
            "Cholangiocarcinoma",
            "ArQule"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "CASE_ONLY",
            "timePerspective": "CROSS_SECTIONAL"
          },
          "bioSpec": {
            "retention": "SAMPLES_WITH_DNA",
            "description": "A minimum of 1 cubic mm of tumor tissue (archival) with at least 50% nucleated tumor cell content is required."
          },
          "enrollmentInfo": {
            "count": 131,
            "type": "ACTUAL"
          }
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Estimate the frequency of FGFR2 fusions in archived iCCA or mixed HCC-CCA tumor tissue samples",
              "description": "Archived tumor samples will be collected and analyzed using a Next Generation Sequencing panel.",
              "timeFrame": "Archived tumor samples will be collected through study completion, up to 18 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Determine the frequency of potential actionable mutations or genetic alterations in iCCA or mixed HCC-CCA",
              "description": "Archived tumor samples will be collected and analyzed using a Next Generation Sequencing panel.",
              "timeFrame": "Archived tumor samples will be collected through study completion, up to 18 months"
            },
            {
              "measure": "Formulate genetic screening recommendations for newly diagnosed patients with iCCA or mixed HCC-CCA",
              "description": "Archived tumor samples will be collected and analyzed using a Next Generation Sequencing panel.",
              "timeFrame": "Archived tumor samples will be collected through study completion, up to 18 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* If required by law or local regulations (i.e., the sample is from an identifiable subject), signed written informed consent should be granted prior to use of the sample in the study\n* ≥ 18 years of age\n* Histologically or cytologically confirmed iCCA or mixed HCC-CCA, who are/were eligible for systemic therapy (samples collected prior to initiation of the systemic therapy may be submitted for testing)\n* Have one or more formalin fixed and paraffin embedded blocks available. If blocks are not evaluable, 7-10 unstained, non-baked slides with 5-micron thick sections with at least 20% tumor tissue should be available. (Potential participants who are scheduled to undergo surgical treatment may agree to provide surplus of tissues not required for diagnosis and have to provide informed consent prior to the surgery.)\n\nExclusion Criteria:\n\n* Not applicable: Patients must meet all of the inclusion criteria.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "One hundred and fifty archived tumor tissue samples from patients with iCCA or mixed HCC-CCA will be collected from five to fifteen research sites in the United States and Italy and/or from commercially available sources. No new surgical procedures will be required and no treatment will be provided as part of this study.",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
