        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Cohort I: Progression-Free Survival, as Determined by Investigator Using Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST v1.1)",
              "description": "PFS was defined as the time from randomization to the first occurrence of disease progression or relapse, as determined by the investigator, using RECIST v1.1. As per RECIST v1.1, progressive disease (PD) is defined as at least a 20% increase in the sum of diameters of target lesions, taking as reference the smallest sum on study (nadir), including baseline. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 millimeters (mm). The appearance of one or more new lesions is also considered progression.",
              "timeFrame": "Randomization up to disease progression or relapse, whichever occurs first (up to approximately 2 years)"
            },
            {
              "measure": "Cohort II, III: Percentage of Participants With Confirmed Overall Response (OR) (Partial Response [PR] or Complete Response [CR]), as Determined by the Investigator Using RECIST v1.1",
              "description": "OR was defined as the rate of a PR or CR occurring after randomization and confirmed \\>=28 days later as determined by the investigator using RECIST v1.1. As per RECIST v1.1, CR is defined as the disappearance of all target lesions. Any pathological lymph nodes (whether target or nontarget) must have reduction in short axis to \\<10 mm. PR is defined as at least a 30% decrease in the sum of diameters of all target and new measurable lesions.",
              "timeFrame": "Randomization up to disease progression or relapse, whichever occurs first (up to approximately 5.25 years)"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Cohort I, II, III: Overall Survival (OS)",
              "description": "OS was defined as the time from randomization to death from any cause",
              "timeFrame": "Randomization up to death from any cause (up to approximately 6.5 years)"
            },
            {
              "measure": "Cohort I: Percentage of Participants With Confirmed OR (PR or CR), as Determined by the Investigator Using RECIST v1.1",
              "description": "OR was defined as the rate of a PR or CR occurring after randomization and confirmed \\>=28 days later as determined by the investigator using RECIST v1.1. As per RECIST v1.1, CR is defined as the disappearance of all target lesions. Any pathological lymph nodes (whether target or nontarget) must have reduction in short axis to \\<10 mm. PR is defined as at least a 30% decrease in the sum of diameters of all target and new measurable lesions.",
              "timeFrame": "Randomization up to disease progression or relapse, whichever occurs first (up to approximately 2 years)"
            },
            {
              "measure": "Cohort I, II, III: Duration of Response (DOR), as Determined by the Investigator Using RECIST v1.1",
              "description": "DOR was defined as the time from the first occurrence of a documented objective response to the time of relapse, as determined by the investigator using RECIST v1.1 or death from any cause during the study, whichever occurred first.",
              "timeFrame": "Time from the first occurrence of documented objective response to time of relapse or death, whichever occurs first (up to approximately 6.5 years)"
            },
            {
              "measure": "Cohort I, II, III: Percentage of Participants With Unconfirmed Overall Response (OR_uc) (Unconfirmed PR or CR), as Determined by the Investigator Using RECIST v1.1",
              "description": "ORR\\_uc (ORR confirmation not required) was defined as the rate of a PR or CR occurring after randomization as determined by the investigator using RECIST v1.1, confirmation not required. As per RECIST v1.1, CR is defined as the disappearance of all target lesions. Any pathological lymph nodes (whether target or nontarget) must have reduction in short axis to \\<10 mm. PR is defined as at least a 30% decrease in the sum of diameters of all target and new measurable lesions.",
              "timeFrame": "Randomization up to disease progression or relapse, whichever occurs fist (up to approximately 6.5 years)"
            },
            {
              "measure": "Cohort II, III: Progression-Free Survival, as Determined by Investigator Using RECIST v1.1",
              "description": "PFS was defined as the time from randomization to the first occurrence of disease progression or relapse, as determined by the investigator, using RECIST v1.1. As per RECIST v1.1, PD is defined as at least a 20% increase in the sum of diameters of target lesions, taking as reference the smallest sum on study (nadir), including baseline. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 mm. The appearance of one or more new lesions is also considered progression.",
              "timeFrame": "Randomization up to disease progression or relapse, whichever occurs first (up to approximately 6.5 years)"
            },
