      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "One participant from Cohort III never started any treatment.",
          "recruitmentDetails": "The study recruited participants with metastatic or locally advanced, triple-negative adenocarcinoma of the breast who had not received prior systemic therapy for metastatic breast cancer. Locally advanced disease must not have been amenable to resection with curative intent.",
          "groups": [
            {
              "id": "FG000",
              "title": "Cohort I: Safety Run-In",
              "description": "Participants received cobimetinib plus paclitaxel until 12 participants completed one cycle of study treatment (28 days)."
            },
            {
              "id": "FG001",
              "title": "Cohort I: Placebo, Paclitaxel",
              "description": "Participants received a combination of cobimetinib placebo plus paclitaxel in 28-day cycles until disease progression, unacceptable toxicity, investigator decision, death, withdrawal of consent, or completion of study."
            },
            {
              "id": "FG002",
              "title": "Cohort I: Cobimetinib, Paclitaxel",
              "description": "Participants received a combination of cobimetinib plus paclitaxel in 28-day cycles until disease progression, unacceptable toxicity, investigator decision, death, withdrawal of consent, or completion of study."
            },
            {
              "id": "FG003",
              "title": "Cohort II:Cobimetinib,Paclitaxel,Atezolizumab",
              "description": "Participants received cobimetinib plus paclitaxel plus atezolizumab in 28-day cycles until disease progression, unacceptable toxicity, investigator decision, death, withdrawal of consent, or completion of study."
            },
            {
              "id": "FG004",
              "title": "Cohort III: Cobimetinib, Nab-Paclitaxel, Atezolizumab",
              "description": "Participants received cobimetinib plus nab-paclitaxel plus atezolizumab until disease progression, unacceptable toxicity, investigator decision, death, withdrawal of consent, or completion of study."
            }
          ],
