        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Cohort I: Progression-Free Survival, as Determined by Investigator Using Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST v1.1)",
              "description": "PFS was defined as the time from randomization to the first occurrence of disease progression or relapse, as determined by the investigator, using RECIST v1.1. As per RECIST v1.1, progressive disease (PD) is defined as at least a 20% increase in the sum of diameters of target lesions, taking as reference the smallest sum on study (nadir), including baseline. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 millimeters (mm). The appearance of one or more new lesions is also considered progression.",
              "populationDescription": "ITT population was defined as all enrolled participants, whether or not the assigned study treatment was received. Data were only collected from participants in the Cohort I Expansion Stage (Cohort I: Cobimetinib, Paclitaxel, Cohort I: Placebo, Paclitaxel) for this outcome measure.",
              "reportingStatus": "POSTED",
              "paramType": "MEDIAN",
              "dispersionType": "95% Confidence Interval",
              "unitOfMeasure": "Weeks",
              "timeFrame": "Randomization up to disease progression or relapse, whichever occurs first (up to approximately 2 years)",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Cohort I: Cobimetinib, Paclitaxel",
                  "description": "Participants received a combination of cobimetinib plus paclitaxel in 28-day cycles until disease progression, unacceptable toxicity, investigator decision, death, withdrawal of consent, or completion of study."
                },
                {
                  "id": "OG001",
                  "title": "Cohort I: Placebo, Paclitaxel",
