  "studies": [
    {
      "protocolSection": {
        "identificationModule": {
          "nctId": "NCT01711866",
          "orgStudyIdInfo": {
            "id": "PD0009"
          },
          "organization": {
            "fullName": "UCB Pharma",
            "class": "INDUSTRY"
          },
          "briefTitle": "A Phase 4, Open-label Study to Assess the Feasibility and Efficacy on Motor and Non-motor Symptoms of Switching From Pramipexole or Ropinirole to Rotigotine Transdermal Patch in Subjects With Advanced Idiopathic Parkinson's Disease",
          "officialTitle": "An Open-Label, Multicenter, Multinational Study to Assess the Feasibility of Switching Therapy From Pramipexole or Ropinirole to the Rotigotine Transdermal System and Its Effect on Motor and Non-Motor Symptoms in Subjects With Advanced Idiopathic Parkinson's Disease Phase 4"
        },
        "statusModule": {
          "statusVerifiedDate": "2014-02",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2012-09"
          },
          "primaryCompletionDateStruct": {
            "date": "2013-03",
            "type": "ACTUAL"
          },
          "completionDateStruct": {
            "date": "2013-03",
            "type": "ACTUAL"
          },
          "studyFirstSubmitDate": "2012-10-18",
          "studyFirstSubmitQcDate": "2012-10-18",
          "studyFirstPostDateStruct": {
            "date": "2012-10-22",
            "type": "ESTIMATED"
          },
          "resultsFirstSubmitDate": "2014-02-25",
          "resultsFirstSubmitQcDate": "2014-02-25",
          "resultsFirstPostDateStruct": {
            "date": "2014-04-07",
            "type": "ESTIMATED"
          },
          "lastUpdateSubmitDate": "2014-02-25",
          "lastUpdatePostDateStruct": {
            "date": "2014-04-07",
            "type": "ESTIMATED"
          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "SPONSOR"
          },
          "leadSponsor": {
            "name": "UCB BIOSCIENCES GmbH",
            "class": "INDUSTRY"
          },
          "collaborators": [
            {
              "name": "Otsuka Pharmaceutical Co., Ltd.",
              "class": "INDUSTRY"
            }
          ]
        },
        "oversightModule": {
          "oversightHasDmc": false
        },
        "descriptionModule": {
          "briefSummary": "The purpose of this study is to assess the safety and feasibility of switching subjects with advanced Parkinson's Disease (PD) from Pramipexole or Ropinirole to Rotigotine and to assess the effects of Rotigotine on motor and non-motor symptoms of Parkinson's Disease in subjects switched from previous treatment with either Pramipexole or Ropinirole."
        },
        "conditionsModule": {
          "conditions": [
            "Advanced Idiopathic Parkinson's Disease"
          ],
          "keywords": [
            "Rotigotine",
            "Neupro",
            "Switch",
            "Dopamine agonists"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE4"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 87,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Rotigotine",
              "type": "EXPERIMENTAL",
              "description": "First application of Rotigotine patch for 24 hours on Day 1, followed by application of a new patch each day of the Treatment Period.\n\n* Subjects on lower doses switch from Pramipexole or Ropinirole to equivalence doses of Rotigotine on Day 1 of the 28 days Treatment Period. On Day 8 (Visit 3) the dose will be evaluated and potentially adjusted up to a maximum dose of 8 mg / 24 hours.\n* Subjects on higher doses switch from the equivalent dose to 8 mg / 24 hours Rotigotine of Pramipexole or Ropinirole to 8 mg / 24 hours Rotigotine on Day 1 and the remainder of the dose of Pramipexole or Ropinirole is to be switched on Day 8 of the 28 days Treatment Period. On Day 15 (Visit 4) the dose will be evaluated and potentially adjusted up to a maximum dose of 16 mg / 24 hours.",
              "interventionNames": [
                "Drug: Rotigotine"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Rotigotine",
              "description": "Rotigotine up to 16 mg / 24 hours, 4 weeks.",
              "armGroupLabels": [
                "Rotigotine"
              ],
              "otherNames": [
                "Neupro"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Clinical Global Impression (CGI) Item 4 (Side Effects) at the End of the Treatment Period or Early Withdrawal Visit",
              "description": "The CGI Item 4 was used to assess side effects. It ranges from 0 to 4 as follows:\n\n* 0 = Side effects not assessable\n* 1 = No side effects\n* 2 = Side effects do not significantly interfere with subject's functioning\n* 3 = Side effects significantly interfere with the subject's functioning\n* 4 = Side effects outweigh therapeutic efficacy.",
              "timeFrame": "Day 28 (Visit 5) of the 28 days Treatment Period or Early Withdrawal Visit"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Patients Global Impressions of Change (PGIC) at the End of the Treatment Period or Early Withdrawal Visit",
              "description": "The PGIC is a 7-point categorical rating scale in which the subject rates the changes in functioning over time as follows:\n\n* 1 = Very much improved\n* 2 = Much improved\n* 3 = Minimally improved\n* 4 = No change\n* 5 = Minimally worse\n* 6 = Much worse\n* 7 = Very much worse.",
              "timeFrame": "Day 28 (Visit 5) of the 28 days Treatment Period or Early Withdrawal Visit"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Subject has idiopathic Parkinson's Disease of more than 3 years duration, as defined by the cardinal sign, bradykinesia, plus the presence of at least 1 of the following: resting tremor, rigidity, impairment of postural reflexes and is without any other known or suspected cause of Parkinsonism\n* Subject has motor fluctuations\n* Subject is not satisfactorily controlled following the investigator´s assessment on a total daily dose of Pramipexole or Ropinirole\n* Subject has sleep disturbance or early morning motor impairment\n* Subject has experienced nocturia for at least 3 nights within 7 days prior to the Baseline Visit\n* Subject is taking L-dopa in combination with Benserazide or Carbidopa and has been on a stable dose of L-dopa for at least 28 days prior to the Baseline Visit\n\nExclusion Criteria:\n\n* Subject has had therapy with Tolcapone or Budipine\n* Subject is receiving therapy with one of the following drugs either concurrently or within 28 days prior to Baseline (Visit 2): alpha-methyl dopa, metoclopramide, reserpine, neuroleptics, monoamine oxidase A (MAO-A) inhibitors, methylphenidate, or amphetamine\n* Subject has a history of symptomatic (not asymptomatic) orthostatic hypotension in the 6 months prior to Baseline (Visit 2)\n* Subject has a history of significant skin hypersensitivity to adhesive or other transdermal preparations, or recent unsolved contact dermatitis\n* Subject has a history of seizures or stroke within 1 year, or a history of myocardial infarction within the last 6 months prior to enrollment\n* Subject is pregnant or nursing, or is of childbearing potential but (i) not surgically sterile or (ii) not using adequate birth control methods (including at least 1 barrier method) or (iii) not sexually abstinent or (iv) not at least 2 years postmenopausal\n* Subject has a previous diagnosis of narcolepsy, sleep apnea syndrome, restless legs syndrome, or periodic limb movement disorder",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "30 Years",
          "maximumAge": "80 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
        "contactsLocationsModule": {
          "overallOfficials": [
            {
              "name": "UCB Clinical Trial Call Center",
              "affiliation": "+1 877 822 9493 (UCB)",
              "role": "STUDY_DIRECTOR"
            }
          ],
          "locations": [
            {
              "facility": "505",
              "city": "Anniston",
              "state": "Alabama",
              "country": "United States",
              "geoPoint": {
                "lat": 33.65983,
                "lon": -85.83163
              }
            },
            {
              "facility": "506",
              "city": "Atlantis",
              "state": "Florida",
              "country": "United States",
              "geoPoint": {
                "lat": 26.5909,
                "lon": -80.10088
              }
