        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Clinical Global Impression (CGI) Item 4 (Side Effects) at the End of the Treatment Period or Early Withdrawal Visit",
              "description": "The CGI Item 4 was used to assess side effects. It ranges from 0 to 4 as follows:\n\n* 0 = Side effects not assessable\n* 1 = No side effects\n* 2 = Side effects do not significantly interfere with subject's functioning\n* 3 = Side effects significantly interfere with the subject's functioning\n* 4 = Side effects outweigh therapeutic efficacy.",
              "populationDescription": "All 87 subjects of the Safety Set are included in the analysis of this outcome measure. Last Observation Carried Forward (LOCF) was used as a method of imputation for missing observations.",
              "reportingStatus": "POSTED",
              "paramType": "NUMBER",
              "unitOfMeasure": "participants",
              "timeFrame": "Day 28 (Visit 5) of the 28 days Treatment Period or Early Withdrawal Visit",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Rotigotine",
                  "description": "First application of Rotigotine patch for 24 hours on Day 1, followed by application of a new patch each day of the Treatment Period.\n\n* Subjects on lower doses switch from Pramipexole or Ropinirole to equivalence doses of Rotigotine on Day 1 of the 28 days Treatment Period. On Day 8 (Visit 3) the dose will be evaluated and potentially adjusted up to a maximum dose of 8 mg / 24 hours.\n* Subjects on higher doses switch from the equivalent dose to 8 mg / 24 hours Rotigotine of Pramipexole or Ropinirole to 8 mg / 24 hours Rotigotine on Day 1 and the remainder of the dose of Pramipexole or Ropinirole is to be switched on Day 8 of the 28 days Treatment Period. On Day 15 (Visit 4) the dose will be evaluated and potentially adjusted up to a maximum dose of 16 mg / 24 hours.\n\nRotigotine: Rotigotine up to 16 mg / 24 hours, 4 weeks."
                }
              ],
