        "descriptionModule": {
          "briefSummary": "This is a study of pembrolizumab plus gemcitabine/cisplatin versus placebo plus gemcitabine/cisplatin as first-line therapy in participants with advanced and/or unresectable biliary tract carcinoma. The primary hypothesis is pembrolizumab plus gemcitabine/cisplatin is superior to placebo plus gemcitabine/cisplatin with respect to overall survival (OS)."
        },
        "conditionsModule": {
          "conditions": [
            "Biliary Tract Carcinoma"
          ],
