        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Arm A (Pembrolizumab+Chemotherapy)",
              "type": "EXPERIMENTAL",
              "description": "Participants receive pembrolizumab, 200 mg intravenous (IV) infusion, every 3 weeks (Q3W), Day 1 of each 3-week cycle for up to 35 cycles PLUS gemcitabine, 1000 mg/m\\^2, IV infusion Q3W, Day 1 and Day 8 of each 3-week cycle until progressive disease or unacceptable toxicity PLUS cisplatin, 25 mg/m\\^2 IV infusion, Q3W, Day 1 and Day 8 of each 3-week cycle for up to 8 cycles. Eligible participants who stop the initial course of pembrolizumab with stable disease (SD) or better but progress after discontinuation will initiate a second course of pembrolizumab 200 mg IV Q3W, Day 1 of each 3-week cycle for up to 17 cycles. Treatment with gemcitabine can be stopped at anytime in first or second course due to toxicity or disease progression.",
              "interventionNames": [
                "Biological: Pembrolizumab",
                "Drug: Gemcitabine",
                "Drug: Cisplatin"
              ]
            },
            {
              "label": "Arm B (Placebo+Chemotherapy)",
              "type": "PLACEBO_COMPARATOR",
              "description": "Participants receive placebo to pembrolizumab, 200 mg IV infusion, every 3 weeks (Q3W), Day 1 of each 3-week cycle for up to 35 cycles PLUS gemcitabine, 1000 mg/m\\^2 IV infusion, Q3W, Day 1 and Day 8 of each 3-week cycle until progressive disease or unacceptable toxicity PLUS cisplatin, 25 mg/m\\^2 IV infusion, Q3W, Day 1 and Day 8 of each 3-week cycle for up to 8 cycles.",
              "interventionNames": [
                "Drug: Gemcitabine",
                "Drug: Cisplatin",
                "Drug: Placebo"
              ]
            }
          ],
