        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Overall Survival (OS)",
              "description": "Overall survival was defined as the time from randomization to death due to any cause.",
              "timeFrame": "Up to approximately 38 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Progression-free Survival (PFS) Per Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST 1.1) as Assessed by Response Evaluation Criteria in Solid Tumors Version 1.1 (BICR)",
              "description": "PFS was defined as the time from randomization to the first documented disease progression (PD) or death due to any cause, whichever occurred first. Per RECIST 1.1, PD was defined as ≥20% increase in the sum of diameters of target lesions. In addition to the relative increase of 20%, the sum must also have demonstrated an absolute increase of ≥5 mm. The appearance of one or more new lesions was also considered PD. PFS as assessed by BICR per RECIST 1.1 was presented.",
              "timeFrame": "Up to approximately 26 months"
            },
            {
              "measure": "Objective Response Rate (ORR) Per Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST 1.1) as Assessed by Blinded Independent Central Review (BICR)",
              "description": "ORR was defined as the percentage of participants who have a confirmed Complete Response (CR: disappearance of all target lesions) or Partial Response (PR: a ≥30% decrease in the sum of diameters \\[SOD\\] of target lesions) as assessed by BICR per RECIST 1.1, which was adjusted for this study to allow a maximum of 10 target lesions in total and 5 per organ.",
              "timeFrame": "Up to approximately 26 months"
            },
            {
              "measure": "Duration of Response (DOR) Per RECIST 1.1 as Assessed by BICR",
              "description": "For participants who demonstrated a confirmed CR (disappearance of all target lesions) or PR (at least a 30% decrease in the sum of diameters of target lesions) per RECIST 1.1, DOR was defined as the time from first documented evidence of a CR or PR until PD or death. DOR for participants who had not progressed or died at the time of analysis was to be censored at the date of their last tumor assessment. Per RECIST 1.1, PD was defined as at least a 20% increase in the sum of diameters of target lesions as well as an absolute increase of at least a 5 mm in the sum of diameters. The appearance of one or more new lesions was also considered PD. DOR assessments were based on BICR with confirmation. The DOR as assessed using RECIST 1.1 for all participants who experienced a confirmed CR or PR was presented.",
              "timeFrame": "Up to approximately 38 months"
            },
            {
              "measure": "Number of Participants Who Experience One or More Adverse Events (AE)",
              "description": "An adverse event (AE) was defined as any unfavorable and unintended sign including an abnormal laboratory finding, symptom or disease associated with the use of a medical treatment or procedure, regardless of whether it was considered related to the medical treatment or procedure, that occurred during the course of the study. Number of participants who experienced one or more AEs were reported.",
              "timeFrame": "Up to approximately 65 months"
            },
            {
              "measure": "Number of Participants Who Discontinued Study Intervention Due to an AE",
              "description": "An AE was defined as any unfavorable and unintended sign including an abnormal laboratory finding, symptom or disease associated with the use of a medical treatment or procedure, regardless of whether it was considered related to the medical treatment or procedure, that occurs during the course of the study. Number of participants who discontinued study intervention due to an AE were reported.",
              "timeFrame": "Up to approximately 63 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria\n\n* Has histologically confirmed diagnosis of advanced (metastatic) and/or unresectable (locally advanced) biliary tract cancer (intra-or extrahepatic cholangiocarcinoma or gallbladder cancer)\n* Has measurable disease based on Response Evaluation Criteria in Solid Tumors (RECIST 1.1), as determined by the site investigator\n* Participants with a history of hepatitis B or hepatitis C can be enrolled if they meet study criteria\n* Is able to provide archival tumor tissue sample or newly obtained core or excisional biopsy of a tumor lesion\n* Has a life expectancy of greater than 3 months\n* Has adequate organ function\n\nExclusion Criteria\n\n* Has had previous systemic therapy for advanced (metastatic) or unresectable (locally advanced) biliary tract cancer (intra-or extra hepatic cholangiocarcinoma or gallbladder cancer)\n* Has ampullary cancer\n* Has small cell cancer, neuroendocrine tumors, lymphoma, sarcoma, mixed tumor histology and/or mucinous cystic neoplasms\n* Has received prior therapy with an anti-programmed cell death 1 (anti-PD-1), anti- programmed cell death ligand 1 or 2 (anti-PD-L1, anti-PD-L2) agent or with an agent directed to another stimulatory or coinhibitory T-cell receptor (e.g., cytotoxic T-lymphocyte-associated protein 4 \\[CTLA-4\\], OX-40, CD137)\n* Has a known history of, or any evidence of, central nervous system (CNS) metastases and/or carcinomatous meningitis, as assessed by local site investigator\n* Has had an allogenic tissue/solid organ transplant",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
