          },
          "briefTitle": "Pembrolizumab Plus Epacadostat vs Pembrolizumab Plus Placebo in Metastatic Non-Small Cell Lung Cancer (KEYNOTE-654-05/ECHO-305-05)",
          "officialTitle": "A Phase 2, Randomized, Double-Blind Study of Pembrolizumab (MK-3475) Plus Epacadostat (INCB024360) Versus Pembrolizumab Plus Placebo as First-Line Treatment in Patients With Metastatic Non-Small Cell Lung Cancer Expressing High Levels of PD-L1"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-08",
