          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "The purpose of this study is to evaluate the efficacy and safety of pembrolizumab plus epacadostat compared to pembrolizumab plus placebo as first-line treatment in participants with metastatic non-small cell lung cancer (NSCLC) expressing high levels of programmed cell death ligand 1 (PD-L1)."
        },
        "conditionsModule": {
          "conditions": [
            "Lung Cancer"
          ],
          "keywords": [
            "non-small cell lung cancer",
            "programmed cell death 1 (PD-1) inhibitor",
            "indoleamine 2",
            "3-dioxygenase 1 (IDO1) inhibitor"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE2"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "QUADRUPLE",
              "maskingDescription": "With the implementation of Amendment 05 the study is no longer blinded.",
              "whoMasked": [
                "PARTICIPANT",
                "CARE_PROVIDER",
                "INVESTIGATOR",
                "OUTCOMES_ASSESSOR"
              ]
            }
          },
          "enrollmentInfo": {
            "count": 154,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Pembrolizumab + Epacadostat",
              "type": "EXPERIMENTAL",
              "description": "Participants received pembrolizumab 200 mg as an intravenous (IV) infusion, every three weeks (Q3W) starting on Day 1 of each cycle for up to 35 administrations in combination with epacadostat 100 mg orally, twice daily. Epacodostat administration was discontinued after the implementation of protocol amendment 05.",
              "interventionNames": [
                "Drug: Pembrolizumab",
                "Drug: Epacadostat"
              ]
            },
            {
              "label": "Pembrolizumab + Placebo",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants received pembrolizumab 200 mg by IV infusion, Q3W starting on Day 1 of each cycle for up to 35 administrations in combination with matching placebo orally, twice daily. Placebo administration was discontinued after the implementation of protocol amendment 05.",
              "interventionNames": [
                "Drug: Pembrolizumab",
                "Drug: Placebo"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Pembrolizumab",
              "description": "Pembrolizumab administered intravenously every 3 weeks.",
              "armGroupLabels": [
                "Pembrolizumab + Epacadostat",
                "Pembrolizumab + Placebo"
              ],
              "otherNames": [
                "MK-3475"
              ]
            },
            {
              "type": "DRUG",
              "name": "Epacadostat",
              "description": "Epacadostat administered orally twice daily.",
              "armGroupLabels": [
                "Pembrolizumab + Epacadostat"
              ],
              "otherNames": [
                "INCB024360"
              ]
            },
            {
              "type": "DRUG",
              "name": "Placebo",
              "description": "Matching placebo administered orally twice daily.",
              "armGroupLabels": [
                "Pembrolizumab + Placebo"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Objective Response Rate (ORR) of Pembrolizumab Plus Epacadostat Versus Pembrolizumab Plus Placebo",
              "description": "ORR is defined as the proportion of participants who have a confirmed complete response (CR) or partial response (PR) per Response Evaluation Criteria in Solid Tumors (RECIST) v1.1 based on blinded independent central review (BICR).",
              "timeFrame": "Up to approximately 6 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Progression-free Survival (PFS) of Pembrolizumab + Epacadostat Versus Pembrolizumab + Placebo",
              "description": "PFS is defined as the time from randomization to the first documented progressive disease per RECIST v1.1 based on BICR or death due to any cause, whichever occurs first.",
              "timeFrame": "Up to approximately 36 months"
            },
            {
              "measure": "Overall Survival (OS) of Pembrolizumab + Epacadostat Versus Pembrolizumab + Placebo",
              "description": "OS is defined as the time from randomization to death due to any cause.",
              "timeFrame": "Up to approximately 36 months"
            },
            {
              "measure": "Duration of Response (DOR) of Pembrolizumab + Epacadostat Versus Pembrolizumab + Placebo",
              "description": "DOR is defined as the time from the earliest date of qualifying response until earliest date of disease progression per RECIST v1.1 or death from any cause, whichever comes first.",
              "timeFrame": "Up to approximately 36 months"
            },
            {
              "measure": "Number of Participants With Adverse Events (AEs)",
              "description": "AE is defined as any untoward medical occurrence in a patient or clinical study participant, temporally associated with the use of study treatment, whether or not considered related to the study treatment.",
              "timeFrame": "Up to 37 months"
            },
            {
              "measure": "Number of Participants Who Discontinued Study Drug Due to AEs",
              "description": "AE is defined as any untoward medical occurrence in a patient or clinical study participant, temporally associated with the use of study treatment, whether or not considered related to the study treatment.",
              "timeFrame": "Up to 37 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Histologically or cytologically confirmed diagnosis of stage IV NSCLC without epidermal growth factor receptor (EGFR)-sensitizing mutation, ROS1 and/or anaplastic lymphoma kinase (ALK) translocation.\n* Measurable disease based on RECIST 1.1.\n* Tumor tissue that demonstrates programmed cell death ligand 1 (PD-L1) expression in ≥ 50% of tumor cells (tumor proportion score \\[TPS\\] ≥ 50%) as assessed by immunohistochemistry at a central laboratory.\n* Life expectancy of at least 3 months.\n* Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1.\n* Adequate organ function per protocol-defined criteria.\n\nExclusion Criteria:\n\n* Known untreated central nervous system metastases and/or carcinomatous meningitis.\n* History of (noninfectious) pneumonitis that required systemic steroids or current pneumonitis/interstitial lung disease.\n* Symptomatic ascites or pleural effusion.\n* Known history of an additional malignancy, except if the participant has undergone potentially curative therapy with no evidence of that disease recurrence for 5 years since initiation of that therapy.\n* Active autoimmune disease that has required systemic treatment in past 2 years.\n* Has had an allogeneic tissue/solid organ transplant.\n* Has a known history of human immunodeficiency virus (HIV) infection. HIV testing is not required unless mandated by the local health authority.\n* Has known history of or is positive for active Hepatitis B (HBsAg reactive) or has active Hepatitis C (HCV RNA). Note: Testing must be performed to determine eligibility.\n* History or presence of an abnormal electrocardiogram (ECG) that, in the Investigator's opinion, is clinically meaningful.\n* Use of protocol-defined prior/concomitant therapy.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
