      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "Phase 3 design of the study has been amended soon after it had started to a prospectively randomized phase 2 study. At the time of amendment existing participants were given a choice to move/participate in the new phase 2 study, and some participants who chose to discontinue the study at phase 3 were assigned to \"study terminated by sponsor\" as the reason for not completing the study in disposition table. The results posted are combined in the prospectively redesigned phase 2 trial.",
          "recruitmentDetails": "A total of 154 participants were randomized in 1:1 to either combination (Pembrolizumab+Epacadostat) and control (Pembrolizumab+Placebo) groups. As of Amendment 05, study design was changed to unblinded, open-label, and single-arm (epacadostat and placebo were removed).",
          "groups": [
            {
              "id": "FG000",
              "title": "Pembrolizumab + Epacadostat",
              "description": "Participants received pembrolizumab 200 mg as an intravenous (IV) infusion, every three weeks (Q3W) starting on Day 1 of each cycle for up to 35 administrations in combination with epacadostat 100 mg orally, twice daily. Epacodostat administration was discontinued after the implementation of protocol amendment 05."
            },
            {
              "id": "FG001",
              "title": "Pembrolizumab + Placebo",
              "description": "Participants received pembrolizumab 200 mg by IV infusion, Q3W starting on Day 1 of each cycle for up to 35 administrations in combination with matching placebo orally, twice daily. Placebo administration was discontinued after the implementation of protocol amendment 05."
            }
          ],
