        "descriptionModule": {
          "briefSummary": "This is a phase I/II multicenter, open-label umbrella platform study that will evaluate the safety and efficacy of investigational agents with pembrolizumab, plus chemotherapy or lenvatinib, for the treatment of participants with advanced esophageal cancer who have failed 1 prior line of therapy and have not been previously exposed to programmed cell death 1 protein (PD-1)/ programmed cell death ligand 1 (PD-L1) based treatment.\n\nWith protocol amendment 5 (effective: 17-November-2023), enrollment in study arms \"Pembrolizumab plus MK-4830 plus Chemotherapy\" and \"Pembrolizumab plus MK-4830 plus lenvatinib\" is discontinued.",
          "detailedDescription": "The master protocol is MK-3475-U06."
        },
        "conditionsModule": {
          "conditions": [
            "Esophageal Squamous Cell Carcinoma (ESCC)"
          ],
          "keywords": [
