            "Programmed Cell Death 1 (PD1, PD-1)",
            "Programmed Cell Death 1 Ligand 1 (PDL-1, PD-L1)",
            "Programmed Cell Death 1 Ligand 2 (PDL-2, PD-L2)"
          ]
        },
