        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Number of Participants Experiencing a Dose-limiting Toxicity (DLT) During Safety Lead-in Phase",
              "description": "A DLT is defined as any drug-related adverse event (AE) according to the National Cancer Institute Common Terminology for Adverse Events (NCI CTCAE) Version 5.0, observed during the DLT evaluation period that results in a change to a given dose or a delay in initiating the next cycle.",
              "timeFrame": "Up to approximately 3 weeks"
            },
            {
              "measure": "Number of Participants Experiencing an Adverse Event (AE) During Safety Lead-in Phase",
              "description": "An AE is any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of a study intervention.",
              "timeFrame": "Up to approximately 3 Weeks"
            },
            {
              "measure": "Number of Participants Who Discontinue Study Treatment Due to an AE During Safety Lead-in Phase",
              "description": "An AE is any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of a study intervention.",
              "timeFrame": "Up to approximately 3 weeks"
            },
            {
              "measure": "Objective Response Rate (ORR)",
              "description": "ORR is defined as the percentage of participants with Complete Response (CR: disappearance of all target lesions) or Partial Response (PR: at least a 30% decrease in the sum of diameters of target lesions) per Response Evaluation Criteria In Solid Tumors Version 1.1 (RECIST 1.1). The percentage of participants who experience CR or PR as assessed by Blinded Independent Central Review (BICR) will be presented.",
              "timeFrame": "Up to approximately 40 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Progression-Free Survival (PFS)",
              "description": "PFS is defined as the time from allocation to the first documented progressive disease (PD) as assessed by RECIST 1.1 or death due to any cause, whichever occurs first. PD is defined as ≥20% increase in the sum of diameters of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of ≥5 mm. The appearance of one or more new lesions is also considered PD. PFS as assessed by BICR will be presented.",
              "timeFrame": "Up to approximately 40 months"
            },
            {
              "measure": "Duration of Response (DOR)",
              "description": "For participants who demonstrate a confirmed Complete Response (CR: disappearance of all target lesions) or Partial Response (PR: at least a 30% decrease in the sum of diameters of target lesions) per RECIST 1.1, DOR is defined as the time from first documented evidence of CR or PR until progressive disease (PD) or death. Per RECIST 1.1, PD is defined as at least a 20% increase in the sum of diameters of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 mm. The appearance of one or more new lesions is also considered PD. DOR as assessed by BICR will be presented.",
              "timeFrame": "Up to approximately 40 months"
            },
            {
              "measure": "Overall Survival (OS)",
              "description": "OS is defined as the time from the date of allocation to death from any cause.",
              "timeFrame": "Up to approximately 40 months"
            },
            {
              "measure": "Number of Participants Experiencing at Least One Adverse Event (AE) During the Efficacy Phase",
              "description": "An AE is any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of a study intervention.",
              "timeFrame": "Up to approximately 40 months"
            },
            {
              "measure": "Number of Participants Who Discontinue Study Treatment Due to An AE During the Efficacy Phase",
              "description": "An AE is any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of a study intervention.",
              "timeFrame": "Up to approximately 104 weeks"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "The main inclusion and exclusion criteria include but are not limited to the following:\n\nInclusion Criteria:\n\n* Histologically or cytologically confirmed diagnosis of metastatic or locally advanced unresectable ESCC\n* Has experienced investigator documented radiographic or clinical disease progression on one prior line of standard therapy.\n* Has an evaluable baseline tumor sample (newly obtained or archival) for analysis\n* Has adequately controlled blood pressure (BP) with or without antihypertensive medications\n* Participants who have adverse events (AEs) due to previous anticancer therapies must have recovered to ≤Grade 1 or baseline. Participants with endocrine-related AEs who are adequately treated with hormone replacement or participants who have ≤Grade 2 neuropathy are eligible\n\nExclusion Criteria:\n\n* Direct invasion into adjacent organs such as the aorta or trachea\n* Has experienced weight loss \\>10% over approximately 2 months prior to first dose of study therapy\n* Has received an investigational agent or has used an investigational device within 4 weeks prior to study intervention administration\n* Diagnosis of immunodeficiency or is receiving chronic systemic steroid therapy or any other form of immunosuppressive therapy within 7 days prior to the first dose of study medication\n* Known additional malignancy that is progressing or has required active treatment within the past 3 years, except basal cell carcinoma of the skin, squamous cell carcinoma of the skin, or carcinoma in situ that has undergone potentially curative therapy\n* Known active central nervous system (CNS) metastases and/or carcinomatous meningitis\n* Active autoimmune disease that has required systemic treatment in past 2 years\n* History of human immunodeficiency virus (HIV) infection\n* History of Hepatitis B or known active Hepatitis C virus infection\n* History of allogenic tissue/solid organ transplant\n* Clinically significant cardiovascular disease within 12 months from first dose of study intervention\n* Participants with known gastrointestinal (GI) malabsorption or any other condition that may affect the absorption of lenvatinib\n* Has risk for significant GI bleeding, such as:\n* Has had a serious nonhealing wound, peptic ulcer, or bone fracture within 28 days prior to allocation/randomization\n* Has significant bleeding disorders, vasculitis, or has had a significant bleeding episode from the GI tract within 12 weeks prior to allocation/randomization",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
