        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Recurrence-Free Survival (RFS)",
              "description": "RFS was defined as the time from randomization to first documentation of disease recurrence (local, regional, or distant) as assessed by blinded independent central review (BICR) or by pathology consistent with HCC if required per the site's standard of care, or death due to any cause (both cancer and non-cancer causes of death), whichever occurred first. RFS was reported for each arm.",
              "timeFrame": "Up to approximately 69 months"
            },
            {
              "measure": "Overall Survival (OS)",
              "description": "OS was defined as the time from randomization to death due to any cause. OS was reported for each arm.",
              "timeFrame": "Up to approximately 69 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Number of Participants Who Experienced an Adverse Event (AE)",
              "description": "An AE was defined as any unfavorable and unintended sign, symptom, or disease (new or worsening) temporally associated with the use of study therapy, regardless of whether or not a causal relationship with the study therapy was determined. The number of participants who experienced an AE were reported.",
              "timeFrame": "Up to approximately 26 months"
            },
            {
              "measure": "Number of Participants Who Discontinued Study Treatment Due to an AE",
              "description": "An AE was defined as any unfavorable and unintended sign, symptom, or disease (new or worsening) temporally associated with the use of study therapy, regardless of whether or not a causal relationship with the study therapy was determined. The number of participants who discontinued study treatment due to an AE were reported.",
              "timeFrame": "Up to approximately 23 months"
            },
            {
              "measure": "Change From Baseline in European Organization for Research and Treatment of Cancer (EORTC) Quality of Life Questionnaire-Core 30 (QLQ-C30) Combined Global Health Status (GHS) / Quality of Life (QoL) Scale Score",
              "description": "The EORTC QLQ-C30 is a cancer specific health-related quality-of life (QoL) questionnaire. Participants responded to the questions regarding Global Health Status (GHS; \"How would you rate your overall health during the past week?\") and Quality of Life (\"How would you rate your overall quality of life during the past week?\") are scored on a 7-point scale (1= Very poor to 7=Excellent). The combined score of GHS (Item 29) and QoL (Item 30) was computed by averaging the raw scores of the 2 items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. A higher score indicated a better outcome. The change from baseline in GHS (EORTC QLQ-C30 Item 29) and QoL (EORTC QLQ-C30 Item 30) combined score was reported.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "Change From Baseline in EORTC QLQ-C30 Physical Functioning Scale Score",
              "description": "The EORTC QLQ-C30 is a cancer specific health-related quality of life questionnaire. Participants responded to 5 questions about their physical functioning (Items 1-5) are scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score of items 1 to 5 was computed by averaging the raw scores of the 5 items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. Higher scores indicated better physical functioning. The change from baseline in EORTC QLQ-C30 Physical Functioning (Items 1-5) combined score was reported.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "Change From Baseline in EORTC QLQ-C30 Role Functioning Scale Score",
              "description": "The EORTC QLQ-C30 is a cancer specific health-related quality of life questionnaire. The role functioning score was based on participant responses to questions scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score was computed by averaging the raw scores of Items 6 and 7 and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. Higher scores indicated better role functioning. The change from baseline in EORTC QLQ-C30 Role Functioning (Items 6 and 7) combined score was reported.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "Change From Baseline in EORTC QLQ-Hepatocellular Carcinoma Module (EORTC QLQ-HCC18) Abdominal Swelling Scale Score",
              "description": "The EORTC QLQ-HCC18 is an HCC-specific questionnaire, administered in addition to the EORTC QLQ-C30. The abdominal swelling scale score was based on participant responses to questions scored on a 4-point scale (1=Not at All to 4=Very Much). Using linear transformation, raw scores were standardized, so that scores range from 0-100. Higher scores indicated more severe symptoms/problems. Change from baseline in the EORTC QLQ-HCC18 abdominal swelling scale score was reported.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "Change From Baseline in EORTC QLQ-HCC18 Fatigue Scale Score",
              "description": "The EORTC QLQ-HCC18 is an HCC-specific questionnaire, administered in addition to the EORTC QLQ-C30. The fatigue scale score was based on participant responses to questions scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score was computed by averaging the raw scores of the items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. Higher scores indicated more severe symptoms/problems. Change from baseline in the EORTC QLQ-HCC18 fatigue scale score was reported.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "Change From Baseline in EORTC QLQ-HCC18 Pain Scale Score",
              "description": "The EORTC QLQ-HCC18 is an HCC-specific questionnaire, administered in addition to the EORTC QLQ-C30. The pain scale score was based on participant responses to questions scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score was computed by averaging the raw scores of the items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. Higher scores indicated more severe symptoms/problems. Change from baseline in the EORTC QLQ-HCC18 pain scale score was reported.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "Change From Baseline in Visual Analogue Scale (VAS) Score on the European Quality of Life (EuroQoL)-5 Dimensions, 5-level Questionnaire (EQ-5D-5L) Health Utility Score",
              "description": "The EQ-5D-5L is a standardized instrument for use as a measure of health outcome. The VAS is a component of the EQ-5D-5L that asked participants to rate their overall health on a vertical visual analogue scale, with the scale's ends labelled 'The best health you can imagine' (equivalent to a score of 0) and 'The worst health you can imagine' (equivalent to a score of 100).",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "Time to Deterioration (TTD) in the EORTC QLQ-C30 Combined GHS / QoL Scale Score",
              "description": "EORTC QLQ-C30 is a questionnaire to assess QoL of cancer patients. Participants responded to questions on GHS (\"How would you rate your overall health during the past week?\") and QoL (\"How would you rate your overall QoL during the past week?\") were scored on a 7-point scale (1= Very poor to 7=Excellent). The combined score of GHS (Item 29) and QoL (Item 30) was computed by averaging raw scores of the 2 items and applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. A higher score indicated a better outcome. TTD was defined as the time from baseline to first onset of ≥10-point negative change (decrease) from baseline in GHS-QoL combined score. A longer TTD indicated a better outcome.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "TTD in the EORTC QLQ-C30 Physical Functioning Scale Score",
              "description": "EORTC QLQ-C30 is a questionnaire to assess the overall QoL of cancer patients. Participants responded to 5 questions about their physical functioning (Items 1 to 5) are scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score of items 1 to 5 was computed by averaging the raw scores of the 5 items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. A higher score indicated a better outcome. TTD was defined as the time from baseline to first onset of ≥10-point negative change (decrease) from baseline in physical functioning (Items 1 to 5). A longer TTD indicated a better outcome.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "TTD in the EORTC QLQ-C30 Role Functioning Scale Score",
              "description": "EORTC QLQ-C30 is a questionnaire to assess the overall QoL of cancer patients. Participants responded to questions about their role functioning (Items 6 and 7) are scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score of Items 6 and 7 was computed by averaging the raw scores of the items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. A higher score indicated a better outcome. TTD was defined as the time from baseline to first onset of ≥10-point negative change (decrease) from baseline in physical functioning (Items 6 and 7). A longer TTD indicated a better outcome.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "TTD in the EORTC QLQ-HCC18 Abdominal Swelling Scale Score",
              "description": "The EORTC QLQ-HCC18 is an HCC-specific questionnaire, administered in addition to the EORTC QLQ-C30. The abdominal swelling scale score was based on participant responses to questions scored on a 4-point scale (1=Not at All to 4=Very Much). Using linear transformation, raw scores were standardized, so that scores range from 0-100. Higher scores indicated more severe symptoms/problems. The TTD in EORTC QLQ-HCC18 abdominal swelling scale score was reported, defined as the time to first onset of a ≥10 point decrease from baseline.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "TTD in the EORTC QLQ-HCC18 Fatigue Scale Score",
              "description": "The EORTC QLQ-HCC18 is an HCC-specific questionnaire, administered in addition to the EORTC QLQ-C30. The fatigue scale score was based on participant responses to questions scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score was computed by averaging the raw scores of the items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. Higher scores indicated more severe symptoms/problems. The TTD in EORTC QLQ-HCC18 fatigue scale score was reported, defined as the time to first onset of a ≥10 point decrease from baseline.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            },
            {
              "measure": "TTD in the EORTC QLQ-HCC18 Pain Scale Score",
              "description": "The EORTC QLQ-HCC18 is an HCC-specific questionnaire, administered in addition to the EORTC QLQ-C30. The pain scale score was based on participant responses to questions scored on a 4-point scale (1=Not at All to 4=Very Much). The combined score was computed by averaging the raw scores of the items and then applying a linear transformation to standardize the average score, so that the combined scores range from 0-100. Higher scores indicated more severe symptoms/problems. The TTD in EORTC QLQ-HCC18 pain scale score was reported, defined as the time to first onset of a ≥10 point decrease from baseline.",
              "timeFrame": "Baseline and up to approximately 120 weeks"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Has a diagnosis of HCC by radiological criteria and/or pathological confirmation.\n* Has an eligibility scan (CT of the chest, triphasic CT scan or MRI of the abdomen, and CT or MRI of the pelvis) confirming complete radiological response ≥4 weeks after complete surgical resection or local ablation. Randomization needs to occur within 12 weeks of the date of surgical resection or local ablation.\n* Has no radiologic evidence of disease prior to enrollment.\n* Has an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1 within 7 days prior to Cycle 1, Day 1.\n* Has a Child-Pugh class A liver score (5 to 6 points) within 7 days prior to Cycle 1, Day 1.\n* Has alpha fetoprotein (AFP) concentration lower than 400 ng/mL within 28 days prior to Cycle 1, Day 1.\n* Has controlled hepatitis B (Hep B).\n* Has recovered adequately from toxicity and/or complications from the local intervention (surgical resection or local ablation) prior to starting study treatment.\n* If female, is not pregnant or breastfeeding, and at least one of the following conditions applies: 1) Is not a woman of childbearing potential (WOCBP); or 2) Is a WOCBP and using a contraceptive method that is highly effective or be abstinent from heterosexual intercourse as their preferred and usual lifestyle (a WOCBP must have a negative pregnancy test within 72 hours before the first dose of study treatment).\n* If undergoing surgical resection, has submitted a tumor tissue sample during Screening.\n* Has adequate organ function.\n\nExclusion Criteria:\n\n* Has a known additional malignancy that is progressing or has required active antineoplastic treatment (including hormonal) or surgery within the past 3 years.\n* Has had esophageal or gastric variceal bleeding within the last 6 months.\n* Has clinically apparent ascites on physical examination.\n* Has had clinically diagnosed hepatic encephalopathy in the last 6 months.\n* Has received local therapy to liver ablation other than with radiofrequency or microwave ablation.\n* Has a history of (noninfectious) pneumonitis/interstitial lung disease that required steroids or has current pneumonitis/interstitial lung disease.\n* Has an active infection requiring systemic therapy.\n* Has dual active Hepatitis B Virus (HBV) and Hepatitis C Virus (HCV) infection at study entry.\n* Has a known history of human immunodeficiency virus (HIV) infection.\n* Has known active tuberculosis (TB; Bacillus tuberculosis).\n* Has received prior therapy with an anti-PD-1, anti-PD-L1, or anti PD-L2 agent or with an agent directed to another stimulatory or co-inhibitory T-cell receptor (eg, CTLA-4, OX-40, CD137).\n* Has received prior systemic anti-cancer therapy for HCC including investigational agents.\n* Is receiving any of the following prohibited concomitant therapies:1) Antineoplastic systemic chemotherapy or biological therapy; 2) Immunotherapy not specified in this protocol; 3) Investigational agents other than pembrolizumab; 4) Radiation therapy; 5) Oncological surgical therapy; or systemic glucocorticoids for any purpose other than to modulate symptoms from an AE that is suspected to have an immunologic etiology.\n* Has received a live vaccine within 30 days prior to the first dose of study treatment.\n* Is currently participating in or has participated in a study of an investigational agent or has used an investigational device within 4 weeks prior to Cycle 1, Day 1.\n* Has a diagnosis of immunodeficiency or is receiving chronic systemic steroid therapy or any other form of immunosuppressive therapy within 7 days prior to Cycle 1, Day 1.\n* Has severe hypersensitivity (≥Grade 3) to pembrolizumab and/or any of its excipients.\n* Has an active autoimmune disease that has required systemic treatment in past 2 years.\n* Has a known psychiatric or substance abuse disorder that would interfere with the participant's ability to cooperate with the requirements of the study.\n* Has had an allogenic tissue/solid organ transplant.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
