      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "Participants were screened for the status of 2 clinically validated, independent next generation biomarkers: T cell-inflamed gene expression profile (GEP) and tumor mutational burden (TMB). Participants were then assigned to 1 of 4 biomarker-defined groups (GEP low/TMB low, GEP low/TMB high, GEP high/TMB low, and GEP high/TMB high) and then randomized to different interventions.",
          "groups": [
            {
              "id": "FG000",
              "title": "Pembrolizumab + Lenvatinib",
              "description": "Participants received pembrolizumab 200 mg every 3 weeks (Q3W) intravenously (IV) plus lenvatinib 20 mg orally once daily until disease progression, or until the participant has received 35 administrations of pembrolizumab (approximately 2 years). Participants completing 35 infusions of pembrolizumab may continue with lenvatinib alone until disease progression or toxicity."
            },
            {
              "id": "FG001",
              "title": "Pembrolizumab + Quavonlimab",
              "description": "Participants received pembrolizumab 200 mg Q3W IV plus quavonlimab 25 mg every 6 weeks (Q6W) IV until disease progression, or until the participant has received 35 administrations of pembrolizumab (approximately 2 years)."
            },
            {
              "id": "FG002",
              "title": "Pembrolizumab + Favezelimab 200 mg",
              "description": "Participants received pembrolizumab 200 mg Q3W IV plus favezelimab 200 mg Q3W IV until disease progression, or until the participant has received 35 administrations of pembrolizumab (approximately 2 years)."
            },
            {
              "id": "FG003",
              "title": "Pembrolizumab + Favezelimab 800 mg",
              "description": "Participants received pembrolizumab 200 mg Q3W IV plus favezelimab 800 mg Q3W IV until disease progression, or until the participant has received 35 administrations of pembrolizumab (approximately 2 years)."
            }
          ],
