        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Objective Response Rate (ORR)",
              "description": "ORR was defined as the percentage of participants who have a confirmed complete response (CR: disappearance of all target lesions) or partial response (PR: At least a 30% decrease in the sum of diameters \\[SOD\\] of target lesions, taking as reference the baseline sum diameters) per Response Evaluation Criteria in Solid Tumors 1.1 (RECIST 1.1) as assessed by local site radiologic review. The percentage of participants who experience CR or PR as assessed by local site radiologic review with confirmatory assessment per RECIST 1.1 is presented. Participants were assigned to 1 of 4 biomarker-defined groups (GEP low/TMB low, GEP low/TMB high, GEP high/TMB low, and GEP high/TMB high) and randomized within-group to receive a combination treatment of study interventions. Per protocol, no participants within GEP Low/TMB Low biomarker group were assigned to receive Pembrolizumab + Favezelimab 800 mg.",
              "populationDescription": "All allocated participants who have received study treatment",
              "reportingStatus": "POSTED",
              "paramType": "NUMBER",
              "dispersionType": "95% Confidence Interval",
              "unitOfMeasure": "Percentage of Participants",
              "timeFrame": "Up to approximately 80 months",
              "groups": [
                {
                  "id": "OG000",
