        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Arm 1: Pembrolizumab/Vibostolimab coformulation + Docetaxel",
              "type": "EXPERIMENTAL",
              "description": "Participants receive pembrolizumab/vibostolimab (coformulation of 200 mg pembrolizumab and 200 mg vibostolimab) via intravenous (IV) infusion once every 3 weeks (Q3W) for up to 35 cycles up to approximately 2 years plus docetaxel 75 mg/m\\^2 via IV infusion Q3W. Each cycle will be 21 days.",
              "interventionNames": [
                "Biological: Pembrolizumab/Vibostolimab coformulation",
                "Drug: Docetaxel"
              ]
            },
            {
              "label": "Arm 2: Pembrolizumab/Vibostolimab coformulation",
              "type": "EXPERIMENTAL",
              "description": "Participants receive pembrolizumab/vibostolimab (coformulation of 200 mg pembrolizumab and 200 mg vibostolimab) via IV infusion Q3W for up to 35 cycles up to approximately 2 years. Each cycle will be 21 days.",
              "interventionNames": [
                "Biological: Pembrolizumab/Vibostolimab coformulation"
              ]
            },
            {
              "label": "Arm 3: Placebo + Docetaxel",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants receive normal saline placebo via IV infusion Q3W for up to 35 cycles up to approximately 2 years plus docetaxel 75 mg/m\\^2 IV infusion Q3W. Each cycle will be 21 days.",
              "interventionNames": [
                "Drug: Docetaxel",
                "Drug: Placebo"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Pembrolizumab/Vibostolimab coformulation",
              "description": "Pembrolizumab 200 mg + vibostolimab 200 mg/20 mL vial IV infusion Q3W up to approximately 2 years.",
              "armGroupLabels": [
                "Arm 1: Pembrolizumab/Vibostolimab coformulation + Docetaxel",
                "Arm 2: Pembrolizumab/Vibostolimab coformulation"
              ],
              "otherNames": [
                "MK-7684A"
              ]
            },
            {
              "type": "DRUG",
              "name": "Docetaxel",
              "description": "Docetaxel 75 mg\\^m2 IV infusion Q3W until discontinuation due to progressive disease or unacceptable toxicity. Docetaxel will serve as part of an experimental treatment in Arm 1, and as an active comparator in Arm 3.",
              "armGroupLabels": [
                "Arm 1: Pembrolizumab/Vibostolimab coformulation + Docetaxel",
                "Arm 3: Placebo + Docetaxel"
              ],
              "otherNames": [
                "Taxotere"
              ]
            },
            {
              "type": "DRUG",
              "name": "Placebo",
              "description": "Normal saline IV infusion Q3W up to approximately 2 years",
              "armGroupLabels": [
                "Arm 3: Placebo + Docetaxel"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Progression Free Survival (PFS) Per Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST 1.1) by Blinded Independent Central Review (BICR) Assessment",
              "description": "PFS is defined as the time from randomization to the first documented disease progression (PD) or death due to any cause, whichever occurs first. Per RECIST 1.1, PD is defined as ≥20% increase in the sum of diameters of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of ≥5 mm. The appearance of one or more new lesions is also considered PD. PFS as assessed by BICR is presented.",
              "timeFrame": "Up to approximately 21 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Objective Response Rate (ORR) Per RECIST 1.1 by BICR Assessment",
              "description": "ORR is defined as the percentage of participants who have a confirmed complete response (CR: Disappearance of all target lesions) or a partial response (PR: At least a 30% decrease in the sum of diameters of target lesions) per RECIST 1.1. The percentage of participants who experience a CR or PR as assessed by BICR based on RECIST 1.1 is presented.",
              "timeFrame": "Up to approximately 21 months"
            },
            {
              "measure": "Overall Survival (OS)",
              "description": "OS is defined as the time from randomization to the date of death due to any cause.",
              "timeFrame": "Up to approximately 21 months"
            },
            {
              "measure": "Duration of Response (DOR) Per RECIST 1.1 by BICR Assessment",
              "description": "For participants who demonstrate a confirmed CR (Disappearance of all target lesions) or confirmed PR (At least a 30% decrease in the sum of diameters of target lesions) per RECIST 1.1, DOR is defined as the time from first documented evidence of CR or PR until disease progression (PD) or death. Per RECIST 1.1, PD is defined as at least a 20% increase in the sum of diameters of target lesions. In addition to the relative increase of 20%, the sum must also have demonstrated an absolute increase of at least 5 mm. The appearance of one or more new lesions was also considered PD. The DOR as assessed by BICR is presented.",
              "timeFrame": "Up to approximately 21 months"
            },
            {
              "measure": "Number of Participants Who Experienced an Adverse Event (AE)",
              "description": "An AE was any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. The number of participants who experienced an AE is reported here.",
              "timeFrame": "Up to approximately 39 months"
            },
            {
              "measure": "Number of Participants Who Discontinued Study Treatment Due to an AE",
              "description": "An AE was any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. The number of participants who discontinued study treatment due to an AE is reported here.",
              "timeFrame": "Up to approximately 27 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Has a histologically or cytologically confirmed diagnosis of metastatic non-small cell lung cancer (NSCLC)\n* Has confirmation that epidermal growth factor receptor (EGFR), anaplastic lymphoma kinase (ALK), or reactive oxygen species (ROS) 1 directed therapy is not indicated as primary therapy\n* Has progressive disease (PD) on treatment with one prior anti-programmed cell death 1 (PD-1)/ programmed cell death ligand 1 (PD-L1) monoclonal antibody (mAb) administered either as monotherapy or in combination with other checkpoint inhibitors or other therapies\n\n  * Retreatment with the same anti-PD-L1/PD-L1 mAb is acceptable in the overall course of treatment\n* Has PD as determined by the investigator after platinum doublet chemotherapy for metastatic disease\n* Has measurable disease defined as at least 1 measurable lesion by computed tomography (CT) or magnetic resonance imaging (MRI), based on Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST 1.1)\n* Has provided tumor tissue for PD-L1 biomarker analysis from an archival sample or newly obtained core or excisional biopsy of a tumor lesion not previously irradiated\n* Has a life expectancy of at least 3 months\n* Has an Eastern Cooperative Oncology Group (ECOG) Performance Status of 0 to 1 assessed within 7 days prior to randomization\n* Male participants randomized to docetaxel are eligible to participant if they agree to refrain from donating sperm, and either 1) be abstinent from heterosexual intercourse; or 2) must agree to follow contraceptive guidance as per study protocol unless confirmed to be azoospermic during the intervention period and for at least 180 days after the last dose of docetaxel\n* Female participants must be not pregnant, not breastfeeding, and not be a woman of child-bearing potential (WOCBP). A WOCBP is eligible is she agrees to either use contraception, or be abstinent from heterosexual intercourse during the intervention period and for ≥120 days after the last dose of study intervention. If a WOCBP is randomized to docetaxel, she agrees not to donate eggs and either uses contraception or be abstinent from heterosexual intercourse during the treatment period and for ≥180 days after the last dose of docetaxel\n* Has adequate organ function\n\nExclusion Criteria:\n\n* Has known active or untreated central nervous system (CNS) metastases and/or carcinomatous meningitis\n* Has a known history of an additional malignancy, except if the participant has undergone potentially curative therapy with no evidence of that disease recurrence for at least 3 years since initiation of that therapy\n* Has received docetaxel as monotherapy or in combination with other therapies\n* Has received previous treatment with another agent targeting the T-cell immunoreceptor with immunoglobulin \\[Ig\\] and immunoreceptor tyrosine-based inhibitory motif \\[ITIM\\] domains (TIGIT) pathway\n* Has received radiotherapy within 2 weeks of start of study intervention. One week washout is permitted for palliative radiation to non-CNS disease\n* Has received a live or live-attenuated vaccine within 30 days before the first dose of study intervention\n* Is currently participating in or has participated in a study of an investigational agent or has used an investigational device within 4 weeks before the first dose of study intervention\n* Has severe hypersensitivity (≥Grade 3) to docetaxel or pembrolizumab/vibostolimab coformulation and/or any of its excipients\n* Has an active autoimmune disease that has required systemic treatment in past 2 years\n* Has a diagnosis of immunodeficiency or is receiving chronic systemic steroid therapy or any other form of immunosuppressive therapy within 7 days before the first dose of study intervention\n* Has interstitial lung disease, or history of pneumonitis requiring steroids for treatment\n* Has known history of active human immunodeficiency virus (HIV), Hepatitis B or Hepatitis C\n* Has had an allogenic tissue/solid organ transplant\n* Has a known psychiatric or substance abuse disorder that would interfere with the participant's ability to cooperate with the requirements of the study",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
