        "participantFlowModule": {
          "groups": [
            {
              "id": "FG000",
              "title": "Arm 1: Pembrolizumab/Vibostolimab Coformulation + Docetaxel",
              "description": "Participants received pembrolizumab/vibostolimab (coformulation of 200 mg pembrolizumab and 200 mg vibostolimab) via intravenous (IV) infusion once every 3 weeks (Q3W) for up to 35 cycles up to approximately 2 years plus docetaxel 75 mg/m\\^2 via IV infusion Q3W. Each cycle was 21 days."
            },
            {
              "id": "FG001",
              "title": "Arm 2: Pembrolizumab/Vibostolimab Coformulation",
              "description": "Participants received pembrolizumab/vibostolimab (coformulation of 200 mg pembrolizumab and 200 mg vibostolimab) via IV infusion Q3W for up to 35 cycles up to approximately 2 years. Each cycle was 21 days."
            },
            {
              "id": "FG002",
              "title": "Arm 3: Placebo + Docetaxel",
              "description": "Participants received normal saline placebo via IV infusion Q3W for up to 35 cycles up to approximately 2 years plus docetaxel 75 mg/m\\^2 via IV infusion Q3W. Each cycle was 21 days."
            }
