          "organization": {
            "fullName": "National Cancer Institute (NCI)",
            "class": "NIH"
          },
          "briefTitle": "Vaccine Therapy in Treating Patients Who Are Undergoing Surgery for Stage IB, Stage II, or Stage IIIA Non-Small Cell Lung Cancer",
          "officialTitle": "A Phase I Clinical Trial of Mature Autologous Dendritic Cells Loaded With Irradiated Autologous Tumor Cells for the Treatment of Non-Small Cell Lung Cancer (NSCLC)"
        },
        "statusModule": {
          "statusVerifiedDate": "2007-04",
          "overallStatus": "TERMINATED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2005-02"
          },
          "studyFirstSubmitDate": "2004-12-08",
          "studyFirstSubmitQcDate": "2004-12-08",
          "studyFirstPostDateStruct": {
