            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Experimental: Immunomodulatory DC vaccines to target prostate cancer",
              "type": "EXPERIMENTAL",
              "description": "Prostate tumor antigen-modified autologous DCs",
              "interventionNames": [
                "Biological: Immunomodulatory DC vaccines to target prostate cancer"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Immunomodulatory DC vaccines to target prostate cancer",
              "description": "1 to 2 injections, with an interval of one month, of 1\\~2x10\\^7 DC vaccine administered subcutaneously",
              "armGroupLabels": [
                "Experimental: Immunomodulatory DC vaccines to target prostate cancer"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Events of adverse effects after the DC vaccine injection",
              "description": "To assess the safety of autologous prostate cancer DC vaccine in vivo. The percentage of patients who have adverse effects will be evaluated by using the NCI CTCAE V4.0 criteria.",
              "timeFrame": "up to one month"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Rate of successful prostate cancer DC vaccine generation",
              "description": "The percentage of successful prostate cancer DC vaccine generation, which are derived from the monocytic cells of the subjects and pass the safety test after standard culture procedures, viable for at least one preparation, will be evaluated.",
              "timeFrame": "up to one month"
            },
            {
              "measure": "Ability of prostate cancer DC vaccines to induce anti-cancer reaction",
              "description": "Measurement of specific T cell concentration in blood sample",
              "timeFrame": "after 1 month from prostate cancer DC injection to 12 months after injection"
            },
            {
              "measure": "Ability of prostate cancer DC vaccines to induce an anti-cancer reaction",
              "description": "Objective response complete response (CR) is assessed by the Response Evaluation Criteria in Solid Tumors (RECIST) v1.1 criteria. CR indicates disappearance of all target lesions. Any pathological lymph nodes (whether target or non-target) must have shown reduction in short axis to \\<10 mm.",
              "timeFrame": "after 1 month from prostate cancer DC injection to 24 months after injection"
            },
            {
              "measure": "Ability of prostate cancer DC vaccines to induce an anti-cancer reaction",
              "description": "Objective response partial response (PR)) is assessed by the Response Evaluation Criteria in Solid Tumors (RECIST) v1.1 criteria. Partial response is at least a 30% decrease in the sum of the diameters of target lesions, taking as reference the baseline sum diameters.",
              "timeFrame": "after 1 month from prostate cancer DC injection to 24 months after injection"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Histologically confirmed adenocarcinoma of the prostate\n* ECOG performance status 0-1\n* Life expectancy ≥ 12 weeks\n* WBC ≥ 3,500/µL\n* Platelet count ≥ 100,000/µL\n* Hemoglobin ≥ 10.0 g/dL\n* Creatinine ≤ 2.0 mg/dL\n* Alkaline phosphatase ≤ 2.5 times upper limit of normal (ULN)\n* AST ≤ 2.5 times ULN\n* Fertile patients must use effective contraception\n* Willing to provide blood samples for research purposes\n* Able to complete questionnaire(s) alone or with assistance\n* Able to undergo leukapheresis\n* No known immunodeficiency\n* No other malignancy within the past 5 years except for basal cell or squamous cell carcinoma of the skin treated with local resection only\n* No concurrent serious illness\n* No known history of positive PPD skin test\n* Human immunodeficiency virus (HIV) and Hepatitis C virus (HCV) test negative.\n\nExclusion Criteria:\n\n* The patient was still using dexamethasone at a dose greater than 4 mg/day during mononuclear cell collection\n* Patients have a history of autoimmune diseases or other diseases requiring long-term use of hormones or immunosuppressive drugs\n* Patients with a history of allergies or allergies to immune cells and adjuvants of cellular products\n* Active infection with fever\n* Patients with neutropenia (\\> 10 days) that are difficult to correct after treatment\n* Infection with bacteria, fungi or viruses, uncontrolled\n* Patients with HIV and those living with active HBV and HCV\n* Severe organ failure (heart, liver, kidney, lung)\n* Patients who had previously been treated with cell therapy products and examined by team experts deemed not suitable for treatment\n* Anything that researchers believe may increase the risk of subjects or interfere with test results",
