        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "DC immunotherapy",
              "type": "EXPERIMENTAL",
              "description": "Intra-patient dose escalation of intravenous MIDRIX4-LUNG autologous DC vaccine",
              "interventionNames": [
                "Biological: Dendritic cell immunotherapy",
                "Biological: Antigen-specific DTH",
                "Biological: Control DTH"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Dendritic cell immunotherapy",
              "description": "Intravenous infusions of MIDRIX4-LUNG DCs every 2 weeks, using an intra-patient dose escalation scheme progressing along the following range: 10 x10E6 DCs (minimal dose), 20 x 10E6 DCs, 40 x 10E6 DCs, 80 x 10E6 DCs, 100 x 10E6 DCs (maximal dose), until exhaustion of the batch or occurrence of grade ≥3 toxicity event",
              "armGroupLabels": [
                "DC immunotherapy"
              ],
              "otherNames": [
                "DC vaccination"
              ]
            },
            {
              "type": "BIOLOGICAL",
              "name": "Antigen-specific DTH",
              "description": "Intradermal injection of 1 x 10E6 MIDRIX4-LUNG DCs at baseline and after completion of all i.v. DC vaccination rounds. This is used for assessment of induction of antigen-specific immune responses as part of in vivo immunomonitoring (delayed-type hypersensitivity cutaneous reaction as test read-out)",
              "armGroupLabels": [
                "DC immunotherapy"
              ],
              "otherNames": [
                "In vivo immunomonitoring - positive test"
              ]
            },
            {
              "type": "BIOLOGICAL",
              "name": "Control DTH",
              "description": "Intradermal injection of 1 x 10E6 MIDRIX-CTRL DCs at baseline and after completion of all i.v. DC vaccination rounds. This is used for assessment of background (i.e. non-antigen-specific) reactivity (delayed-type hypersensitivity cutaneous reaction as test read-out)",
              "armGroupLabels": [
                "DC immunotherapy"
              ],
              "otherNames": [
                "In vivo immunomonitoring - negative control"
              ]
            }
          ]
        },
