          "briefTitle": "MIDRIXNEO-LUNG Dendritic Cell Vaccine in Patients With Non-small Cell Lung Cancer",
          "officialTitle": "Phase I Study of MIDRIXNEO-LUNG, an Autologous Neoantigen-targeted Dendritic Cell Immunotherapy in Patients With Non-small Cell Lung Cancer",
          "acronym": "MIDRIXNEO"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-04",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
