          "phases": [
            "PHASE1"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "interventionModelDescription": "intra-patient dose escalation scheme",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 6,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "DC immunotherapy",
              "type": "EXPERIMENTAL",
              "description": "Intra-patient dose escalation of intravenous MIDRIXNEO-LUNG autologous DC vaccine",
              "interventionNames": [
                "Biological: Dendritic cell immunotherapy",
                "Biological: Antigen-specific DTH",
                "Biological: Control DTH"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Dendritic cell immunotherapy",
              "description": "Intravenous infusions of MIDRIXNEO-LUNG DCs every 2 weeks, using an intra-patient dose escalation scheme progressing along the following range: 10 x10E6 DCs (minimal dose), 20 x 10E6 DCs, 40 x 10E6 DCs, 80 x 10E6 DCs, 100 x 10E6 DCs (maximal dose), until exhaustion of the batch or occurrence of grade ≥3 toxicity event",
              "armGroupLabels": [
                "DC immunotherapy"
              ],
              "otherNames": [
                "DC vaccination"
              ]
            },
            {
              "type": "BIOLOGICAL",
              "name": "Antigen-specific DTH",
              "description": "Intradermal injection of 1 x 10E6 MIDRIXNEO-LUNG DCs at baseline and after completion of all i.v. DC vaccination rounds. This is used for assessment of induction of antigen-specific immune responses as part of in vivo immunomonitoring (delayed-type hypersensitivity cutaneous reaction as test read-out)",
              "armGroupLabels": [
                "DC immunotherapy"
              ],
              "otherNames": [
                "In vivo immunomonitoring - positive test"
              ]
            },
            {
              "type": "BIOLOGICAL",
              "name": "Control DTH",
              "description": "Intradermal injection of 1 x 10E6 MIDRIX-CTRL DCs at baseline and after completion of all i.v. DC vaccination rounds. This is used for assessment of background (i.e. non-antigen-specific) reactivity (delayed-type hypersensitivity cutaneous reaction as test read-out)",
              "armGroupLabels": [
                "DC immunotherapy"
              ],
              "otherNames": [
                "In vivo immunomonitoring - negative control"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Safety and tolerability of preparing and administrating the autologous dendritic cell-based vaccine in surgically-treated non-small cell lung cancer patients",
              "description": "Toxicity measures as defined by common toxicity criteria v5.0. The maximal tolerated and/or feasible dose will be defined from the intra-patient dose excalation scheme",
              "timeFrame": "From the day of leukapheresis until 3-4 weeks after the last vaccine dose level, i.e. 3 to 5 months depending on the number of doses that can be administered"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Feasibility of producing sufficient dendritic cell for vaccination in surgically treated NSCLC",
              "description": "Success rate (%) of producing sufficient dendritic cells for vaccination",
              "timeFrame": "From the day of enrollment prior to surgery until the last vaccine dose level, i.e. 2 to 4 months depending on the number of doses that can be administered"
            },
            {
              "measure": "Biological activity of the vaccine (elicitation of immune responses against vaccine neoantigens) in vitro",
              "description": "Vaccine-induced immunological responses as measured by in vitro immunomonitoring assays",
              "timeFrame": "From the day of leukapheresis until 3-4 weeks after the last vaccine dose level, i.e. 3 to 5 months depending on the number of doses that can be administered. Whenever possible, repeat testing will be performed 3 and 6 months after vaccination."
            },
            {
              "measure": "Biological activity of the vaccine (elicitation of immune responses against vaccine neoantigens) in vivo",
              "description": "Vaccine-induced immunological responses as measured by in vivo immunomonitoring test (delayed-type hypersensitivity skin reaction)",
              "timeFrame": "From the day of leukapheresis until 3-4 weeks after the last vaccine dose level, i.e. 3 to 5 months depending on the number of doses that can be administered. Whenever possible, repeat testing will be performed 3 and 6 months after vaccination."
            },
            {
              "measure": "Clinical activity of this type of vaccine as reflected by relapse-free survival (months)",
              "description": "Relapse-free survival based on clinical and/or radiological event",
              "timeFrame": "From the day of leukapheresis onwards during 2 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Male and female patients older than 18 years with histologically or cytologically proven diagnosis of non-small cell lung cancer, considered functionally operable and surgically resectable (cT1-3 cN0-1 M0 per 8th TNM classification; cT4N0-1 are considered for surgery on a case-by-case basis) and patients considered resectable in an oligometastatic treatment plan\n* WHO-ECOG performance status 0 to 2 and absence of any persisting and assessable toxicity \\> CTC grade 2 due to a previous therapy (surgery and if applicable adjuvant chemotherapy)\n* Before patient registration and screening, written informed consent must be given for the interventional study and for the \"Prelevation and storage of human tissues and cells\" according to ICH/GCP and institutional practice.\n* Adequate organ function, including:\n\n  * Adequate bone marrow reserve: absolute neutrophil count \\> 1.5\\*10E9/L, platelet count \\> 100\\*10E9/L, and Hb \\> 9.0 g/dL\n  * Sufficient renal function as defined by eGFR \\> 40 ml/min\n  * Sufficient hepatic function as defined by total bilirubin ≤1.5× ULN OR direct bilirubin within normal limits for participants with total bilirubin levels \\>1.5× ULN; AST and ALT ≤ 2.5x ULN\n* Having passed all tests defined in the institutional Leukapheresis Donor Fitness Screening, including:\n\n  * Adequate peripheral vein access to perform leukapheresis\n  * Adequate coagulation function defined as international normalized ratio (INR) or prothrombin time (PT) ≤ 1.5 x ULN and activated partial thromboplastin time (aPTT) ≤ 1.5 x ULN unless the participant is receiving anticoagulant therapy\n  * Negative test results for HBs-antigen, anti-HBc-serology, anti-HCV serology, anti-HIV1-2 serology, anti-CMV IgM, anti-Syphilis (Treponema pallidum) serology\n  * Negative test results for Epstein-Barr virus (IgG and IgM) and for toxoplasmosis (IgG and IgM)\n  * For female participants: a negative serum beta-HCG test result less than 1 week before the day of leukapheresis\n* For female participants with child-bearing potential, the willingness to follow contraceptive guidance and pregnancy testing during the projected duration of the trial (see Appendix B on Contraceptive Guidance and Pregnancy Testing)\n* For male participants having a partner with child-bearing potential: agreement to use contraception during the projected duration of the trial, starting with the screening visit through 90 days after the last dose of trial treatment. Sperm donation must have been performed before anti-cancer treatment as per standard practice\n\nExclusion Criteria:\n\n* Presence of oncogenic driver genomic alterations for which a targeted therapy is available\n* Concomitant participation in another clinical interventional trial\n* Prior treatment with autologous or allogeneic dendritic cell-based vaccines\n* Prior malignancy, except for adequately treated basal cell, superficial or in situ cancer of the bladder or the cervix, or other cancer for which the patient has been disease-free for at least five years.\n* Dermatological pathology interfering with the in vivo immunomonitoring readout (DTH skin test)\n* Disease requiring chronic treatment with systemic glucocorticosteroids with a daily dose \\> 10 mg oral prednisolone or equivalent, or other immunosuppressive drugs. Inhaled corticosteroids and topical corticosteroids on skin sites other than those used for DTH are allowed.\n* Chronic or active concomitant infection requiring active therapy, including including HIV, viral hepatitis (HBV, HCV), CMV or fungal infection\n* Autoimmune disease requiring active treatment at the time of the study\n* Organ allograft\n* Chronic comorbidity (such as asthma, COPD, heart failure, renal failure, arterial hypertension or diabetes mellitus) that is uncontrolled or not stabilized under medication at the time of study enrollment, OR stable yet severe enough to constitute an unwarranted high risk for the investigational cellular therapy.\n* For female participants: pregnancy or lactation, or expecting to conceive or father children within the projected duration of the trial, starting with the screening visit through 90 days after the last dose of trial treatment\n* Any organic brain syndrome or other significant psychiatric abnormality which would comprise the ability to give informed consent and preclude participation in the full protocol and follow-up.\n* Any psychological, familial, sociological or geographical condition potentially hampering compliance with the study protocol and follow-up schedule; those conditions should be discussed with the patient before registration in the trial",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
