        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Selpercatinib - Treatment A (TRT A)",
              "type": "EXPERIMENTAL",
              "description": "160 milligram (mg) Selpercatinib administered orally twice daily (BID) continuously in 21-day cycles.",
              "interventionNames": [
                "Drug: Selpercatinib"
              ]
            },
            {
              "label": "Pemetrexed and Platinum with or without Pembrolizumab - (TRT B)",
              "type": "ACTIVE_COMPARATOR",
              "description": "Pemetrexed 500 milligrams per meter squared (mg/m2) administered intravenously (IV) on Day 1, every 3 weeks (Q3W), plus investigator's choice of carboplatin area under the concentration versus time curve 5 (AUC 5 \\[maximum dose of 750 mg\\] IV), or cisplatin (75 mg/m2 cisplatin IV) on Day 1 Q3W for 4 cycles, plus investigator's choice with or without 200 mg pembrolizumab IV on Day 1 Q3W up to 35 cycles.",
              "interventionNames": [
