        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Progression Free Survival (PFS) by Blinded Independent Central Review (BICR) (With Pembrolizumab)",
              "description": "PFS is defined as the time from randomization until the occurrence of documented disease progression by the BICR, per Response Evaluation Criteria in Solid Tumors (RECIST) version 1.1 criteria, or death from any cause in the absence of BICR-documented progressive disease.",
              "timeFrame": "Baseline to Progressive Disease or Death from Any Cause Up to 31 Months"
            },
            {
              "measure": "PFS by BICR (With or Without Pembrolizumab)",
              "description": "PFS is defined as the time from randomization until the occurrence of documented disease progression by the BICR, per Response Evaluation Criteria in Solid Tumors (RECIST) version 1.1 criteria, or death from any cause in the absence of BICR-documented progressive disease.",
              "timeFrame": "Baseline to Progressive Disease or Death from Any Cause Up to 31 Months"
            }
          ],
          "secondaryOutcomes": [
