            {
              "measure": "Overall Response Rate (ORR): Percentage of Participants With Complete Response (CR) or Partial Response (PR) by BICR (With Pembrolizumab)",
              "description": "ORR is defined as the number of participants who achieve a best overall response (BOR) of complete response (CR) or partial response (PR) divided by the total number of participants randomized to each treatment arm.",
              "timeFrame": "Baseline through Disease Progression or Death Up to 31 Months"
            },
            {
              "measure": "ORR: Percentage of Participants With CR or PR by BICR (With or Without Pembrolizumab)",
              "description": "ORR is defined as the number of participants who achieve a best overall response (BOR) of complete response (CR) or partial response (PR) divided by the total number of participants randomized to each treatment arm.",
              "timeFrame": "Baseline through Disease Progression or Death Up to 31 Months"
            },
            {
              "measure": "Duration of Response (DoR) by BICR (With Pembrolizumab)",
              "description": "DoR was defined as the time from the date that measurement criteria for CR or PR (whichever is first recorded) were first met until the first date that disease was recurrent or documented disease progression was observed, or the date of death from any cause in the absence of documented disease progression or recurrence. The DOR according to both BICR and investigator-assessed BOR was evaluated per RECIST 1.1 criteria.",
              "timeFrame": "Date of CR or PR to Date of Disease Progression or Death Due to Any Cause Up to 31 Months"
            },
