          "groups": [
            {
              "id": "FG000",
              "title": "Selpercatinib (TRT A)",
              "description": "160 milligram (mg) Selpercatinib administered orally, twice daily (BID) continuously in 21-day cycles."
            },
            {
              "id": "FG001",
              "title": "Pemetrexed and Platinum With or Without Pembrolizumab (TRT B)",
              "description": "Pemetrexed 500 milligrams per meter squared (mg/m2) administered intravenously (IV) on Day 1, every 3 weeks (Q3W), plus investigator's choice of carboplatin area under the concentration versus time curve 5 (AUC 5 \\[maximum dose 750 mg\\]) IV, or cisplatin 75mg/m2 IV on Day 1 Q3W for 4 cycles, plus investigator's choice with or without 200 mg pembrolizumab IV on Day 1 Q3W up to 35 cycles."
            }
