        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Progression Free Survival (PFS) by Blinded Independent Central Review (BICR) (With Pembrolizumab)",
              "description": "PFS is defined as the time from randomization until the occurrence of documented disease progression by the BICR, per Response Evaluation Criteria in Solid Tumors (RECIST) version 1.1 criteria, or death from any cause in the absence of BICR-documented progressive disease.",
              "populationDescription": "Intent to Treat (ITT) Pembrolizumab: Participants included in the ITT population who were stratified with the intent to receive pembrolizumab in the event of the control-arm assignment. Participants censored: TRT A: 80, TRT B: 34.",
              "reportingStatus": "POSTED",
              "paramType": "MEDIAN",
              "dispersionType": "95% Confidence Interval",
              "unitOfMeasure": "Months",
              "timeFrame": "Baseline to Progressive Disease or Death from Any Cause Up to 31 Months",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Selpercatinib (TRT A)",
                  "description": "160 mg Selpercatinib administered orally, BID continuously in 21-day cycles."
                },
                {
                  "id": "OG001",
                  "title": "Pemetrexed and Platinum With Pembrolizumab (TRT B)",
                  "description": "Pemetrexed 500 mg/m2, IV on Day 1 Q3W plus investigator's choice of carboplatin AUC 5 (maximum dose 750 mg) IV or cisplatin 75mg/m2, IV on Day 1 Q3W for 4 cycles, plus investigator's choice with 200 mg pembrolizumab IV on Day 1 Q3W up to 35 cycles."
