        },
        "descriptionModule": {
          "briefSummary": "The purpose of this trial is to investigate the efficacy of cetuximab in combination with chemotherapy in comparison to chemotherapy alone in patients with advanced non small cell lung cancer who did not received prior chemotherapy. Overall survival will be taken as primary measure of efficacy."
        },
        "conditionsModule": {
          "conditions": [
            "Non Small Cell Lung Cancer (NSCLC)"
          ],
          "keywords": [
            "Cetuximab",
            "Non small cell lung cancer",
            "Lung cancer",
            "Cisplatin/vinorelbine",
            "Monoclonal antibody",
            "Erbitux"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE3"
          ],
          "designInfo": {
