            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 1861,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Cetuximab plus chemotherapy",
              "type": "EXPERIMENTAL",
              "description": "cetuximab + cisplatin + vinorelbine",
              "interventionNames": [
                "Drug: cetuximab + cisplatin + vinorelbine"
              ]
            },
            {
              "label": "Chemotherapy alone",
              "type": "ACTIVE_COMPARATOR",
              "description": "cisplatin + vinorelbine alone",
              "interventionNames": [
                "Drug: cisplatin + vinorelbine"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "cetuximab + cisplatin + vinorelbine",
              "description": "cetuximab given as an intravenous (i.v.) infusion every week (400mg/m\\^2 initial dose and 250mg/m\\^2 subsequent doses) until progressive disease (PD) + cisplatin 80mg/m\\^2 i.v. infusion on day 1 of each 3-week cycle + vinorelbine 25mg/m\\^2 i.v. infusion on days 1 and 8 of each 3-week cycle.",
              "armGroupLabels": [
                "Cetuximab plus chemotherapy"
              ]
            },
            {
              "type": "DRUG",
              "name": "cisplatin + vinorelbine",
              "description": "cisplatin 80mg/m\\^2 i.v. infusion on day 1 of each 3-week cycle + vinorelbine 25mg/m\\^2 i.v. infusion on days 1 and 8 of each 3-week cycle.",
              "armGroupLabels": [
                "Chemotherapy alone"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Overall Survival Time (OS)",
              "description": "Time from randomization to death. Patients without event are censored at the last date known to be alive or at the clinical cut-off date, whatever is earlier.",
              "timeFrame": "Time from randomisation to death or last day known to be alive, reported between day of first patient randomised, Oct 2004, until cut-off date 18 Jul 2007"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Progression-free Survival Time",
              "description": "Duration from randomization until radiological progression (based on modified World Health Organisation (WHO) criteria) or death due to any cause.\n\nOnly deaths within 60 days of last tumor assessment are considered. Patients without event are censored on the date of last tumor assessment.",
              "timeFrame": "Time from randomization to disease progression, death or last tumor assessment, reported between day of first patient randomised, Oct 2004, until cut-off date 18 Jul 2007"
            },
            {
              "measure": "Best Overall Response Rate",
              "description": "The best overall response rate is defined as the proportion of subjects having achieved confirmed Complete Response + Partial Response as the best overall response according to radiological assessments (based on modified WHO criteria).",
              "timeFrame": "Evaluations were performed every 6 weeks until progression, reported between day of first patient randomised, Oct 2004, until cut-off date 18 Jul 2007"
            },
            {
              "measure": "Disease Control Rate",
              "description": "The disease control rate is defined as the proportion of subjects having achieved confirmed Complete Response + Partial Response + Stable Disease as best overall response according to radiological assessments (based on modified WHO criteria).",
              "timeFrame": "Evaluations were performed every 6 weeks until progression, reported between day of first patient randomised, Oct 2004, until cut-off date 18 Jul 2007"
            },
            {
              "measure": "Quality of Life (QOL) Assessment European Organisation for the Research and Treatment of Cancer (EORTC) QLQ-C30 Global Health Status",
              "description": "Mean global health status scores (EORTC QLQ-C30) against time for each treatment group. Scores were derived from mutually exclusive sets of items, with scale scores ranging from 0 to 100 after a linear transformation. Higher scores indicate a better QoL.",
              "timeFrame": "at baseline, at cycle 3, at month 6, reported between day of first patient randomised, Oct 2004, until cut-off date 18 Jul 2007"
            },
            {
              "measure": "Quality of Life Assessment (EORTC QLQ-C30) Social Functioning",
              "description": "Mean social functioning scores (EORTC QLQ-C30) against time for each treatment group. Scores were derived from mutually exclusive sets of items, with scale scores ranging from 0 to 100 after a linear transformation. Higher scores indicate a higher level of functioning.",
              "timeFrame": "at baseline, at cycle 3, at month 6, reported between day of first patient randomised, Oct 2004, until cut-off date 18 Jul 2007"
            },
            {
              "measure": "A Population Pharmacokinetic (PK) Analysis for Cetuximab in Non-Small Cell Lung Cancer (NSCLC) - Serum Cetuximab Concentrations",
              "description": "Population PK analysis was conducted using non-linear mixed effects modeling (NONMEM) software, integrating the PK data from this study and the Phase II study EMR 62 202-011.",
              "timeFrame": "Week 1, Day 1: baseline and end of infusion; Week 7, Day 43: within 12 h after cetuximab administration."
            },
            {
              "measure": "Safety - Number of Patients Experiencing Any Adverse Event",
              "description": "Please refer to Adverse Events section for further details",
              "timeFrame": "time from first dose up to 30 after last dose of study treatment, reported between day of first patient randomised, Oct 2004, until cut-off date 18 Jul 2007"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Diagnosis of histologically or cytologically confirmed NSCLC, stage IIIb with documented malignant pleural effusion or stage IV\n* Immunohistochemical evidence of EGFR expression on tumor tissue\n* Presence of at least 1 bi-dimensionally measurable index lesion, whereby index lesions must not lie in an irradiated area\n\nExclusion Criteria:\n\n* Previous exposure to monoclonal antibodies, signal transduction inhibitors or EGFR-targeting therapy\n* Previous chemotherapy for NSCLC\n* Documented or symptomatic brain metastasis\n* Superior vena cava syndrome contra-indicating hydration\n* Previous malignancy in the last 5 years except basal cell carcinoma of the skin or pre-invasive carcinoma of the cervix",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
