      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "Enrolled: 1,861 after consent to epidermal growth factor receptor (EGFR) assessment; 603 excluded (mainly non-fulfillment of inclusion or exclusion criteria). 1,258 screened for eligibility after consent for study procedures; 143 excluded (mainly non-fulfillment of inclusion or exclusion criteria). 1,125 subjects randomized.",
          "recruitmentDetails": "First/last subject (informed consent): October 2004/January 2006. Clinical data cut-off: 18 July 2007. Last subject completed 16 May 2012. Subjects randomized at 155 centers; Asia/Australia: 21; Europe: 120; South America: 14.",
          "groups": [
            {
              "id": "FG000",
              "title": "Cetuximab Plus Chemotherapy",
              "description": "cetuximab given as an intravenous (i.v.) infusion every week (400mg/m\\^2 initial dose and 250mg/m\\^2 subsequent doses) until progressive disease (PD) + cisplatin 80mg/m\\^2 i.v. infusion on day 1 of each 3-week cycle + vinorelbine 25mg/m\\^2 i.v. infusion on days 1 and 8 of each 3-week cycle.\n\nSafety population: includes all treated subjects."
            },
            {
              "id": "FG001",
              "title": "Chemotherapy Alone",
              "description": "cisplatin 80mg/m\\^2 i.v. infusion on day 1 of each 3-week cycle + vinorelbine 25mg/m\\^2 i.v. infusion on days 1 and 8 of each 3-week cycle.\n\nSafety population: includes all treated subjects."
            }
          ],
