              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Progression-free Survival 2 (PFS2)",
              "description": "PFS2 is defined as the time from randomization to progression per investigator after initiation of new anticancer therapy or death from any cause, whichever occurs first.",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "Change in QLQ-LC13 Subscale Scores",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
