        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Dose Escalation: Number of participants with Dose-limiting toxicities (DLT) during first cycle",
              "description": "Number of participants with DLTs, which are typically Grade 3 or higher adverse events will be summarized by dose level",
              "timeFrame": "28 days"
            },
            {
              "measure": "To evaluate incidence of treatment emergent adverse events and laboratory abnormalities",
              "description": "Type, incidence, severity, timing, seriousness and relationship to study treatment of adverse events and any laboratory abnormalities will be summarized by dose level",
              "timeFrame": "From baseline until end of study treatment or study completion (approximately 2 years)"
            },
            {
              "measure": "Evaluate pulse rate that is out of normal range and changes in pulse rate as compared to baseline",
              "description": "Identify pulse rate readings that are outside the normal range. The number and percentage of participants who experienced significant pulse rate change from baseline will be summarized by dose level",
              "timeFrame": "From baseline until end of study treatment or study completion (approximately 2 years)"
            },
            {
              "measure": "Evaluate blood pressure that is out of normal range and changes in blood pressure as compared to baseline",
              "description": "Identify systolic and diastolic readings that are outside the normal range. The number and percentage of participants who experienced significant blood pressure change from baseline will be summarized by dose level",
              "timeFrame": "From baseline until end of study treatment or study completion (approximately 2 years)"
            },
            {
              "measure": "To evaluate heart rate corrected QT interval and changes in corrected QT interval as compared to baseline",
              "description": "Determine the effect of the drug on QT prolongation. The number and percentage of participants who experienced QT interval prolongation will be summarized by dose level",
              "timeFrame": "From baseline until end of study treatment or study completion (approximately 2 years)"
            },
            {
              "measure": "To evaluate the preliminary antitumor activity of PF-07104091 as a single agent and in combination with palbociclib and in combination with letrozole or fulvestrant or fulvestrant alone by objective response rate (ORR) in dose expansion",
              "description": "Percentage of participants with a best overall response of complete response (CR) or partial response (PR) using RECIST 1.1",
              "timeFrame": "From baseline through disease progression or study completion (approximately 2 years)"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Maximum plasma concentration (Cmax) of PF-07104091 after a single dose and multiple dose",
              "description": "Peak concentration of PF-07104091 during selected cycles",
              "timeFrame": "Day 1 and Day 15 of Cycle 1 (each cycle is 28 days)"
            },
            {
              "measure": "Time to maximum plasma concentration (Tmax) of PF-07104091 after a single dose and multiple dose",
              "description": "Time to peak concentration of PF-07104091 during selected cycles",
              "timeFrame": "Day 1 and Day 15 of Cycle 1 (each cycle is 28 days)"
            },
            {
              "measure": "Area under the concentration versus time curve from time zero to the last quantifiable time point prior to the next dose (AUClast) of PF-07104091",
              "description": "AUC of PF-07104091 will be calculated at selected cycles",
              "timeFrame": "Day 1 and Day 15 of Cycle 1 (each cycle is 28 days)"
            },
            {
              "measure": "Area under the curve of PF-07104091 with or without food",
              "description": "AUC of PF-07104091 in plasma and whether absorption of the drug is affected when taken by food",
              "timeFrame": "From baseline through time to event on study or study completion (approximately 2 years)"
            },
            {
              "measure": "Maximum plasma concentration of PF-07104091 with or without food",
              "description": "Peak concentrations of PF-07104091 in plasma and whether absorption of the drug is affected when taken by food",
              "timeFrame": "From baseline through time to event on study or study completion (approximately 2 years)"
            },
            {
              "measure": "To document any preliminary evidence of antitumor activity of PF-07104091 as a single agent and in combination with palbociclib and in combination with letrozole or fulvestrant or fulvestrant alone by objective response rate (ORR) in dose escalation",
              "description": "Percentage of participants with a best overall response of CR or PR using RECIST 1.1",
              "timeFrame": "From baseline and every 8 weeks through disease progression or study completion (approximately 2 years)"
            },
            {
              "measure": "To document any preliminary evidence of antitumor activity of PF-07104091 by time to event endpoints",
              "description": "Time from first assessment of event endpoint to last assessment of using RECIST 1.1",
              "timeFrame": "From baseline through time to event on study or study completion (approximately 2 years)"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Participants with HR-positive HER2-negative advanced or metastatic breast cancer (received at least two prior lines in the advanced or metastatic setting including one prior line of combined CDK4/6 inhibitor and endocrine therapy and no more than two prior lines of cytotoxic chemotherapy)\n* Participants with locally recurrent/advanced or metastatic TNBC who have received up to 2 prior lines of chemotherapy in the advanced or metastatic setting\n* Participants with advanced platinum resistant epithelial ovarian cancer (EOC)/fallopian tube cancer/primary peritoneal cancer (PPC) (histologically or cytologically proven) who have received at least 1 systemic anti-cancer therapy containing a platinum analog\n* Participants with cytological diagnosis of advanced/metastatic SCLC\n* Participants with or cytological diagnosis of advanced/metastatic NSCLC\n* Participants with HR-positive HER2-negative advanced or metastatic breast cancer (second line plus setting) (histologically or cytologically proven).\n* Participants entering the study in the expansion cohort have at least one measurable lesion as defined by RECIST version 1.1 that has not been previously irradiated\n* Performance Status 0 or 1\n* Adequate bone marrow, hematological, kidney and liver function\n* Resolved acute effects of any prior therapy to baseline severity\n\nExclusion Criteria:\n\n* Participants with known symptomatic brain metastases requiring steroids\n* Participants with any other active malignancy within 3 years prior to enrollment\n* Major surgery within 3 weeks prior to study entry\n* Radiation therapy within 3 weeks prior to study entry.\n* Systemic anti cancer therapy within 4 weeks prior to study\n* Prior irradiation to \\>25% of the bone marrow\n* Participants with active, uncontrolled bacterial, fungal, or viral infection, including HBV, HCV, and known HIV or AIDS related illness\n* Active COVID-19/SARS-CoV2 infection\n* Baseline 12 lead ECG that demonstrates clinically relevant abnormalities that may affect participant safety or interpretation of study results\n* Any of the following in the previous 6 months: myocardial infarction, long QT syndrome, Torsade de Pointes, arrhythmias, serious conduction system abnormalities, unstable angina, coronary/peripheral artery bypass graft, symptomatic CHF, New York Heart Association class III or IV, cerebrovascular accident, transient ischemic attack, symptomatic pulmonary embolism, and/or other clinical significant episode of thrombo embolic disease.\n* Anticoagulation with vitamin K antagonists or factor Xa inhibitors is not allowed.\n* Hypertension that cannot be controlled by medications\n* Participation in other studies involving investigational drug(s) within 2 weeks prior to study entry.\n* Known or suspected hypersensitivity to active ingredient/excipients in PF 07104091.\n* Active inflammatory gastrointestinal disease, chronic diarrhea, known diverticular disease or previous gastric resection or lap band surgery.\n* Participants with advanced/metastatic, symptomatic, visceral spread, that are at risk of life threatening complications in the short\n* Participants with an indwelling catheter that has an external component such as those used for drainage of effusion(s) or central venous catheter that is externally\n* Previous high dose chemotherapy requiring stem cell rescue\n* Known abnormalities in coagulation such as bleeding diathesis, or treatment with anticoagulants precluding intramuscular injections of goserelin (if applicable).\n* Current use or anticipated need for food or drugs that are known strong CYP3A4/5 or UGT1A9 inhibitors or inducers\n* Current use or anticipated need for drugs that are known sensitive UGT1A1 substrates with narrow therapeutic\n* Serum pregnancy test positive at screening\n* Other medical or psychiatric condition",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
