      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "Study consisted of 2 parts: Part 1 (Dose Finding) \\& Part 2 (Dose Confirmation). Health care professionals (HCPs) who administered the study treatment to participants were not enrolled in the study. To evaluate the HCPs' reported experience with administration of atezolizumab SC \\& atezolizumab IV, the HCPs were asked to complete two questionnaires: 'HCP SC Versus IV Perspective' \\& 'HCP SC Perspective'.\n\nNo data other than the HCP's responses to these Questionnaires were collected in this study.",
          "recruitmentDetails": "A total of 438 participants with previously treated locally advanced or metastatic non-small cell lung cancer (NSCLC) who were cancer immunotherapy (CIT)-naïve and for whom prior platinum-based therapy failed took part in the study across 23 countries from 27 December 2018 to 22 November 2024. The study is considered \"Completed\" because all the pre-planned study activities and analyses have been performed.",
          "groups": [
            {
              "id": "FG000",
              "title": "Part 1 Cohort 1: Atezolizumab SC Co-mix 1800 mg",
              "description": "Participants received atezolizumab, 1800 milligrams (mg), co-mixed with rHuPH20, as SC injection on Cycle 1 Day 1 (1 cycle=21 days), followed by atezolizumab, 1200 mg, as an IV infusion, every 3 weeks (Q3W) on Day 1 of subsequent cycles (1 cycle=21 days) until disease progression (PD), loss of clinical benefit, unacceptable toxicity, or withdrawal of consent."
            },
            {
              "id": "FG001",
              "title": "Part 1 Cohort 2: Atezolizumab SC Co-mix 1200 mg",
              "description": "Participants received atezolizumab, 1200 mg, co-mixed with rHuPH20, as SC injection, Q2W, on Day 1 of the first 3 cycles (Cycle 1-3=14 days), followed by atezolizumab, 1200 mg, as an IV infusion, Q3W, on Day 1 of subsequent cycles (1 cycle=21 days) until PD, loss of clinical benefit, unacceptable toxicity, or withdrawal of consent."
            },
            {
              "id": "FG002",
              "title": "Part 1 Cohort 3: Atezolizumab SC Co-mix 1800 mg",
              "description": "Participants received atezolizumab, 1800 mg, co-mixed with rHuPH20, as SC injection, Q3W, on Day 1 of first 3 cycles, followed by atezolizumab, 1200 mg, as an IV infusion, Q3W on Day 1 for subsequent cycles (1 cycle=21 days) until PD, loss of clinical benefit, unacceptable toxicity, or withdrawal of consent."
            },
            {
              "id": "FG003",
              "title": "Part 2: Atezolizumab IV 1200 mg",
              "description": "Participants received atezolizumab, 1200 mg, as an IV infusion, Q3W, on Day 1 of each cycle (1 cycle=21 days) until PD, loss of clinical benefit, or unacceptable toxicity."
            },
            {
              "id": "FG004",
              "title": "Part 2: Atezolizumab SC 1875 mg",
              "description": "Participants received atezolizumab, 1875 mg, co-formulated with rHuPH20, as SC injection, on Day 1 of each cycle (1 cycle=21 days) until PD, loss of clinical benefit, or unacceptable toxicity."
            }
          ],
