            {
              "type": "SECONDARY",
              "title": "Part 2: Overall Satisfaction With Treatment Over Time, Assessed by the Modified Satisfaction With Therapy (SWT) Scale of the Cancer Therapy Satisfaction Questionnaire (CTSQ)",
              "description": "Modified SWT scale of the CTSQ consisted of seven items that measured seven domains related to satisfaction with cancer therapy. These include worthwhile, difficulty, benefits, feelings about side effects, form of therapy, overall satisfaction, and if participants would choose the therapy taking everything into consideration. Each domain is rated on a 5-point scale, with 1 representing the worst response and 5 representing the best response, except in the case of one reverse-scored item. Mean of the items were linearly transformed to obtain scores from 0-100, where 100 was the best possible score. Higher scores indicate higher satisfaction. Here, data for 'overall satisfaction' domain has been presented.",
              "populationDescription": "FAS included all randomized participants, with participants grouped according to their assigned treatment. Overall number analyzed is the number of participants with data available for analysis. Number analyzed is the number of participants with data available for analysis at the specified time point.",
              "reportingStatus": "POSTED",
              "paramType": "MEAN",
              "dispersionType": "Standard Deviation",
              "unitOfMeasure": "score on a scale",
              "timeFrame": "Day 1 Cycle 3 or Treatment Discontinuation Visit (if treatment discontinued at any visit before Cycle 3) (Cycle length = 21 days)",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Part 2: Atezolizumab IV 1200 mg",
                  "description": "Participants received atezolizumab, 1200 mg, as an IV infusion, Q3W, on Day 1 of each cycle (1 cycle=21 days) until PD, loss of clinical benefit, or unacceptable toxicity."
                },
                {
                  "id": "OG001",
                  "title": "Part 2: Atezolizumab SC 1875 mg",
                  "description": "Participants received atezolizumab, 1875 mg, co-formulated with rHuPH20, as SC injection, on Day 1 of each cycle (1 cycle=21 days) until PD, loss of clinical benefit, or unacceptable toxicity."
                }
              ],
