          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "This study will assess the efficacy and safety of the combination of ceralasertib and durvalumab versus standard of care docetaxel in patients with locally advanced and metastatic NSCLC after progression on prior anti-PD-(L)1 therapy and platinum-based chemotherapy.",
          "detailedDescription": "This study will consist of two treatment arms (Groups A and B).\n\nParticipants will be randomised in a 1:1 ratio to one of the two treatment groups:\n\n* Group A: Ceralasertib plus durvalumab combination therapy Each 28-day cycle will begin with ceralasertib administered orally followed by durvalumab administered intravenously.\n* Group B: Docetaxel monotherapy Each 21-day cycle will begin with the administration of docetaxel."
        },
        "conditionsModule": {
          "conditions": [
            "Advanced or Metastatic Non-Small Cell Lung Cancer"
          ],
          "keywords": [
            "Durvalumab",
            "Ceralasertib",
            "Docetaxel",
            "Lung cancer"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE3"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 594,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Group A: Ceralasertib plus durvalumab combination therapy",
              "type": "EXPERIMENTAL",
              "description": "Participants will be administered ceralasertib orally followed by durvalumab administered intravenously.",
              "interventionNames": [
                "Drug: Ceralasertib",
                "Drug: Durvalumab"
              ]
            },
            {
              "label": "Group B: Docetaxel monotherapy",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants will be administered docetaxel (standard of care) administered intravenously.",
              "interventionNames": [
                "Drug: Docetaxel"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Ceralasertib",
              "description": "Participants will receive ceralasertib oral tablets.",
              "armGroupLabels": [
                "Group A: Ceralasertib plus durvalumab combination therapy"
              ]
            },
            {
              "type": "DRUG",
              "name": "Durvalumab",
              "description": "Participants will receive durvalumab as an intravenous infusion.",
              "armGroupLabels": [
                "Group A: Ceralasertib plus durvalumab combination therapy"
              ]
            },
            {
              "type": "DRUG",
              "name": "Docetaxel",
              "description": "Participants will received docetaxel as an intravenous infusion.",
              "armGroupLabels": [
                "Group B: Docetaxel monotherapy"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Overall Survival (OS)",
              "description": "The superiority of ceralasertib plus durvalumab combination therapy relative to docetaxel will be demonstrated by assessment of OS (HR with 95% CI and p-value) in participants with advanced NSCLC after second- or third-line therapy and without actionable genomic alterations. OS is defined as time from randomisation until the date of death due to any cause.",
              "timeFrame": "Every 3 months (± 1 week) following objective progression of disease (PD) or treatment discontinuation (up to three years)"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Progression-Free Survival (PFS)",
              "description": "PFS will be defined as the time from the date of randomisation until the date of objective PD.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "Objective Response Rate (ORR)",
              "description": "ORR is defined as the proportion of participant who have a Complete Response (CR) or Partial Response (PR) per RECIST 1.1.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "Duration of Response (DoR)",
              "description": "DoR is defined as the time from the date of first documented response until date of documented progression per RECIST 1.1.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "Time To Response (TTR)",
              "description": "TTR is defined as the time from randomisation until the date of first documented objective response.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "Disease Control Rate (DCR)",
              "description": "DCR at 18 weeks is defined as the percentage of participants who have a CR or PR or who have stable disease (SD) for at least 17 weeks.",
              "timeFrame": "At Week 18"
            },
            {
              "measure": "Time to second progression or death (PFS2)",
              "description": "Time from randomisation to PFS2 will be defined as the time from the randomisation to the earliest of the progression event (following the initial progression), subsequent to first subsequent therapy or death.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "Overall Survival (OS) at 12 months",
              "description": "OS is defined as time from randomisation until the data of death due to any cause.",
              "timeFrame": "At 12 months"
            },
            {
              "measure": "Time To Deterioration (TTD) of health-related quality of life (QoL)",
              "description": "TTD is defined as the time from randomisation until the date of first confirmed deterioration.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "TTD of physical function",
              "description": "TTD in physical functioning is measured by the EORTC QLQ-C30 Physical Function subscale of the EORTC QLQ-C30.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "Plasma concentrations for ceralasertib plus durvalumab combination therapy",
              "description": "The PK plasma concentration of ceralasertib when administered in combination with durvalumab will be assessed.",
              "timeFrame": "Up to 3 years"
            },
            {
              "measure": "Number of participants with Adverse Evens (AEs)",
              "description": "The safety and tolerability of ceralasertib plus durvalumab combination therapy as compared with docetaxel will be assessed.",
              "timeFrame": "Up to 3 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Histologically or cytologically documented NSCLC that is locally advanced or metastatic according to Version 8 of the IASLC Staging Manual in Thoracic Oncology.\n* Documented epidermal growth receptor factor (EGFR) and anaplastic lymphoma kinase (ALK) wild-type status as determined at a local laboratory.\n* Documented radiological PD whilst on or after receiving the most recent treatment regimen.\n* Eligible for second- or third-line therapy and must have received an anti-PD-(L)1 therapy and a platinum doublet containing therapy for locally advanced or metastatic NSCLC either separately or in combination.\n* Eastern Cooperative Oncology Group (ECOG)/World Health Organization (WHO) performance status of 0 or 1.\n* Adequate organ function and marrow reserve\n* Minimum life expectancy of 12 weeks.\n* Body weight \\> 30 kg and no cancer-associated cachexia.\n* Negative pregnancy test (serum test) for women of childbearing potential (WOCBP).\n\nExclusion Criteria:\n\n* Participant with mixed SCLC and NSCLC histology.\n* History of another primary malignancy except for malignancy treated with curative intent with no known active disease ≥ 5 years before the first dose of study intervention.\n* Persistent toxicities (CTCAE Grade \\> 2) caused by previous anticancer therapy.\n* Active or prior documented autoimmune or inflammatory disorders.\n* Participants who have received more than one line of prior anti-PD-(L)1, either alone or in any combination.\n* Participants:\n\n  1. Must not have experienced a toxicity that led to permanent discontinuation of the prior anti-PD(L)1 therapy.\n  2. All AEs while receiving prior anti-PD(L)1 therapy must have completely resolved.\n  3. Must not have experienced a Grade ≥ 3 immune-mediated adverse event (imAE) or an immune-related neurologic or ocular AE of any grade while receiving prior anti-PD(L)1 therapy.\n  4. Must not have required the use of additional immunosuppression other than corticosteroids for the management of an AE, not have experienced recurrence of an AE if re-challenged, and not currently require maintenance doses of \\> 10 mg prednisone or equivalent per day.\n* Participants who have received more than one prior line of platinum-based chemotherapy in metastatic setting.\n* Participants who have received a prior ataxia telangiectasia and Rad3-related protein (ATR) inhibitor.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "130 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
