        "ipdSharingStatementModule": {
          "ipdSharing": "YES",
          "description": "Qualified researchers may request access to anonymized individual patient-level data (IPD) and related study documents of the eligible studies via the Data Sharing Portal. Details on GSK's data sharing criteria can be found at: https://www.gsk.com/en-gb/innovation/trials/data-transparency/",
          "infoTypes": [
            "STUDY_PROTOCOL",
            "SAP",
            "ICF",
            "CSR"
          ],
          "timeFrame": "Anonymized IPD will be made available within 6 months of publication of primary, key secondary and safety results for studies in product with approved indication(s) or terminated asset(s) across all indications.",
          "accessCriteria": "Anonymized IPD is shared with researchers whose proposals are approved by an Independent Review Panel and after a Data Sharing Agreement is in place. Access is provided for an initial period of 12 months but an extension may be granted, when justified, for up to 6 months.",
          "url": "https://www.gsk.com/en-gb/innovation/trials/data-transparency/"
        }
      },
      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "The results presented are until the primary completion date. Additional safety results will be submitted within a year of study completion.",
          "groups": [
            {
              "id": "FG000",
              "title": "Niraparib + Pembrolizumab",
              "description": "Participants with Non-Small Cell Lung Cancer (NSCLC) received 200mg (two 100mg tablets) or 300 mg (three 100mg tablets) Niraparib tablet orally once daily from days 1 to 21, depending on their body weight and platelet count, in combination with 200 mg of Pembrolizumab as IV infusion on Day 1 of every 21-day cycle (Q3W). Treatment was continued for a maximum duration of up to 35 cycles, or until radiographic progressive disease (PD), unacceptable toxicity, death, withdrawal of consent, or becoming lost to follow-up"
            },
            {
              "id": "FG001",
              "title": "Placebo + Pembrolizumab",
              "description": "Participants with NSCLC received Placebo tablet (two or three tablets) orally once daily from days 1 to 21, depending on their body weight and platelet count, in combination with 200 mg of Pembrolizumab as IV infusion on Day 1 of every 21-day cycle (Q3W). Treatment was continued for a maximum duration of up to 35 cycles, or until radiographic progressive disease (PD), unacceptable toxicity, death, withdrawal of consent, or becoming lost to follow-up"
            }
          ],
