            {
              "type": "SECONDARY",
              "title": "Changes From Baseline (CFB) in the European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire 13-item Lung Cancer-specific Module (EORTC QLQ-LC13)",
              "description": "EORTC QLQ-LC13 is a 13-items questionnaire used in clinical research to assess health-related quality of life in lung cancer patients. The QLQ-LC13 includes questions assessing lung cancer-associated symptoms (Coughing, hemoptysis, dyspnea and site specific pain), treatment-related side effects (sore mouth, dysphagia, peripheral neuropathy and alopecia) and pain medication. Scores are calculated and transformed to range from 0 to 100. For the disease symptoms and side-effects of treatment scales a higher score represents a higher level of symptoms/problems and a negative change from baseline value indicates reduction (i.e. improvement) in symptoms.",
              "populationDescription": "ITT Population included the Overall Number of Participants Analyzed. 'Number Analyzed' signifies participants evaluable for the specified time points. The \"0 participants\" analyzed represents that data was not collected at that particular time point for the respective Arms/Groups.",
              "reportingStatus": "POSTED",
              "paramType": "COUNT_OF_PARTICIPANTS",
              "unitOfMeasure": "Participants",
              "timeFrame": "Baseline (Predose); Day (D) 1 of Cycle (C)2, C3, C4, C5-C67 (odd cycles only); EoT (up to approx 49 months); Safety follow-up (SFU) 1 & 2 (up to approx 50 & 52 months)",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Niraparib + Pembrolizumab",
                  "description": "Participants with Non-Small Cell Lung Cancer (NSCLC) received 200mg (two 100mg tablets) or 300 mg (three 100mg tablets) Niraparib tablet orally once daily from days 1 to 21, depending on their body weight and platelet count, in combination with 200 mg of Pembrolizumab as IV infusion on Day 1 of every 21-day cycle (Q3W). Treatment was continued for a maximum duration of up to 35 cycles, or until radiographic progressive disease (PD), unacceptable toxicity, death, withdrawal of consent, or becoming lost to follow-up"
                },
                {
                  "id": "OG001",
                  "title": "Placebo + Pembrolizumab",
                  "description": "Participants with NSCLC received Placebo tablet (two or three tablets) orally once daily from days 1 to 21, depending on their body weight and platelet count, in combination with 200 mg of Pembrolizumab as IV infusion on Day 1 of every 21-day cycle (Q3W). Treatment was continued for a maximum duration of up to 35 cycles, or until radiographic progressive disease (PD), unacceptable toxicity, death, withdrawal of consent, or becoming lost to follow-up"
                }
              ],
