          "timeFrame": "All cause mortality, non-serious adverse events (Non-SAEs) and serious adverse events (SAEs) were collected up to 52 months.",
          "description": "Safety Population included of all randomized participant who took at least 1 dose of study treatment.",
          "eventGroups": [
            {
              "id": "EG000",
              "title": "Niraparib + Pembrolizumab",
              "description": "Participants with Non-Small Cell Lung Cancer (NSCLC) received 200mg (two 100mg tablets) or 300 mg (three 100mg tablets) Niraparib tablet orally once daily from days 1 to 21, depending on their body weight and platelet count, in combination with 200 mg of Pembrolizumab as IV infusion on Day 1 of every 21-day cycle (Q3W). Treatment was continued for a maximum duration of up to 35 cycles, or until radiographic progressive disease (PD), unacceptable toxicity, death, withdrawal of consent, or becoming lost to follow-up",
              "deathsNumAffected": 196,
              "deathsNumAtRisk": 329,
              "seriousNumAffected": 97,
              "seriousNumAtRisk": 329,
              "otherNumAffected": 293,
              "otherNumAtRisk": 329
            },
            {
              "id": "EG001",
              "title": "Placebo + Pembrolizumab",
              "description": "Participants with NSCLC received Placebo tablet (two or three tablets) orally once daily from days 1 to 21, depending on their body weight and platelet count, in combination with 200 mg of Pembrolizumab as IV infusion on Day 1 of every 21-day cycle (Q3W). Treatment was continued for a maximum duration of up to 35 cycles, or until radiographic progressive disease (PD), unacceptable toxicity, death, withdrawal of consent, or becoming lost to follow-up",
              "deathsNumAffected": 177,
              "deathsNumAtRisk": 329,
              "seriousNumAffected": 81,
              "seriousNumAtRisk": 329,
              "otherNumAffected": 261,
              "otherNumAtRisk": 329
            }
