        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Children from 0 to 18 years of age with epilepsy;\n* Treatment with one or more antiepileptic drug (s) studied (valproic acid, carbamazepine, phenobarbital, phenytoin, levetiracetam, lamotrigine, topiramate, oxcarbazepine, stiripentol, clobazam, brivaracétam, felbamate, lacosamide, rufinamide, gabapentine, pregabaline, sultiame, tiagabine, vigabatrine, mesuximide, primidone, perampanel, ethosuximide, zonisamide and cannabidiol);\n* Blood dosage of the drug (s) as part of their therapeutic follow-up in the Pharmacology laboratory of the Cochin hospital between 2007 and 2019\n\nExclusion Criteria:\n\n* patient with missing data on time of last drug taking, time of collection, co-treatments and / or dose administered;\n* patient with doubt about compliance",
          "healthyVolunteers": false,
          "sex": "ALL",
          "maximumAge": "18 Years",
          "stdAges": [
            "CHILD",
            "ADULT"
          ],
          "studyPopulation": "Minor patient treated by one or more antiepileptics and for which a blood test has been performed",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
