          "briefTitle": "Relation Between Venetoclax Plasma Concentration and Remission in Adults with Acute Myeloid Leukemia (PREDICLAX)",
          "officialTitle": "Study of the Association Between Residual Venetoclax Plasma Concentration and Composite Complete Remission in Adults with Newly Diagnosed Acute Myeloid Leukemia Ineligible for Intensive Chemotherapy (PREDICLAX)"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-02",
          "overallStatus": "RECRUITING",
          "expandedAccessInfo": {
