        "oversightModule": {
          "oversightHasDmc": true,
          "isFdaRegulatedDrug": true,
          "isFdaRegulatedDevice": false,
          "isUsExport": true
        },
        "descriptionModule": {
          "briefSummary": "Background: In combination with hypomethylating drugs, venetoclax has recently changed the therapeutic management of patients with newly diagnosed acute myeloid leukemia (AML) for whom standard induction chemotherapy was not an option. Over and above the clinical benefits of this combination, the data show that more than half the patients did not show remission criteria, even after the first month's exposure to venetoclax.\n\nHypothesis: To compare the mean residual venetoclax plasma concentrations obtained in patients who went into complete composite remission versus those who did not go into remission at the end of the first cycle of venetoclax + azacitidine treatment.\n\nMethod: According to the French law, this is a multicenter, non-comparative, open-label, single-arm, interventional study with minimal risks and constraints. Selection, information and inclusion will concern adult patients (≥60 years) with a confirmed diagnosis of AML according to ELN 2022 guidelines. Included patients will be treated as standard care with a combination of venetoclax+azacitidine. This research protocol will not modify their usual care."
        },
        "conditionsModule": {
          "conditions": [
            "Adult Acute Myeloid Leukemia"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "COHORT",
            "timePerspective": "PROSPECTIVE"
          },
          "bioSpec": {
            "retention": "SAMPLES_WITHOUT_DNA",
            "description": "* plasma is obtained through venipuncture\n* capillary blood is obtained by pricking a finger"
          },
          "enrollmentInfo": {
            "count": 100,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Patients with composite complete remission",
              "description": "Patients in composite complete remission following the first cycle of venetoclax (400 mg/day, orally, after a ramp-up phase of the first 3 days) + azacytidine (75mg/m²,intravenous, at the start of each cycle from day 1 to day 7)",
              "interventionNames": [
                "Biological: Blood sampling for venetoclax drug dosage (venous puncture)"
              ]
            },
            {
              "label": "Patients without composite complete remission",
              "description": "Patients not in composite complete remission following the first cycle of venetoclax (400 mg/day, orally, after a ramp-up phase of the first 3 days) + azacytidine (75mg/m²,intravenous, at the start of each cycle from day 1 to day 7)",
              "interventionNames": [
                "Biological: Blood sampling for venetoclax drug dosage (venous puncture)"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Blood sampling for venetoclax drug dosage (venous puncture)",
              "description": "8 blood samples for venetoclax and azole antifungal drugs identification and dosage will be taken by venous and capillary punctures throughout management of patients",
              "armGroupLabels": [
                "Patients with composite complete remission",
                "Patients without composite complete remission"
              ],
              "otherNames": [
                "Biological: Capillary Blood sampling for venetoclax drug dosage with Volumetric Absorptive Microsampling (VAMS™) technology with Mitra® device (CE-IVD /IVDR)",
                "Biological: Blood sampling for azole antifungal drug dosage (venous puncture)"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Comparison of mean plasma residual concentration of venetoclax",
              "description": "To compare the mean plasma residual concentration (ng/mL) of venetoclax (determined by LC-MS-MS) between patients who have entered composite complete remission (defined by the presence of remission criteria ≥ CRi, according to ELN 2022 guidelines) versus those who have not at the end of the first cycle of venetoclax+azacitidine treatment.",
              "timeFrame": "1 month"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Study relationship between mean plasma residual concentration of venetoclax and remission occurrence",
              "description": "To estimate mean residual plasma concentrations (Cres, ng/mL) of venetoclax and azole antifungals during patients' usual care. Then study the relationship between mean venetoclax Cres and the achievement (or non-achievement) of remission over time (according to ELN 2022 guidelines) .",
              "timeFrame": "24 months"
            },
            {
              "measure": "Study performance of mean venetoclax Cres",
              "description": "To evaluate the performance (ROC curve) of mean venetoclax Cres (ng/mL) as a predictive biomarker of event-free survival (EFS) at 6 and 12 months.",
              "timeFrame": "6 and 12 months"
            },
            {
              "measure": "Study survival",
              "description": "To estimate event-free survival (EFS), relapse-free survival (RFS) and overall survival (OS).",
              "timeFrame": "24 months"
            },
            {
              "measure": "Study early deaths",
              "description": "To estimate the proportion of early deaths at 30 and 60 days post-inclusion.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Study the variability of plasma venetoclax and antifungal concentrations over time",
              "description": "To estimate the inter-individual (IIV) and intra-individual (IOV) variability of plasma venetoclax and antifungal concentrations over time.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Study the impact of parameters in uni- and multivariate analyses.",
              "description": "To estimate the impact of the following parameters to the diagnosis of remission or Cres (venetoclax):\n\n* patient characteristics: age \\[years\\], BMI (\\[kg/m²\\], sex\\[male vs female\\], ECOG \\[1,2 or 3\\], comorbidities reported in inclusion criteria, number of cytopenia grade\\>2, according to CTCAE v5, white blood cell count \\[G/L\\], creatininemia \\[µmol/L\\], cytoreduction (yes or not).\n* disease: AML classification (ELN 2022 guidelines), blast counts (G/L), cytogenetic status (fail, normal or not) and report, genetic status and report, abnormal rearrangement of genetic material and report.\n* and (co-)treatments of interest: fluconazole, isavuconazole, itraconazole, posaconazole, voriconazole, cannabidiol, ciclosporine, clarithromycine, diltiazem, ritonavir, verapamil,milk thistle, licorice; bosentan, carbamazépine, efavirenz, enzalutamide, felbamate, phénytoïne, phénobarbital, rifampicine, St. John's wort, grapefruit, bitter orange, star fruit).",
              "timeFrame": "24 months"
            },
            {
              "measure": "Study adverse events of interest",
              "description": "To compare mean venetoclax Cres between patients who have experienced one or more of the 5 AEs of interest versus those who have not over time.",
              "timeFrame": "24 months"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "ancillary study 1: study a medical device (VAMS Mitra, Neoteryx) to collect blood capillary sample as an alternative to venous puncture",
              "description": "To compare venetoclax Cres (ng/mL) values obtained with the Mitra® (Neoteryx) medical device (CE) with those obtained after conventional venipuncture (ng/mL).",
              "timeFrame": "24 months"
            },
            {
              "measure": "ancillary study 2: study exposure of plasma venetoclax over 24h",
              "description": "To compute the total integrated area under the plasma venetoclax concentration-time curve (AUC) over 24h in 30 patients cared in CHU of Caen only and to identify the best time of sampling.\n\nPharmacokinetic sampling (day 2 or 3 of cycle 2): Cres (prédose, ng/mL) and post-dose: 2h, 4h, 6h, 8h, 12h, 18h, 24h.",
              "timeFrame": "24 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Subject must have a confirmed diagnosis of previously untreated AML (ELN 2022 criteria) within 28 days of the onset of symptoms. Only previous cytoreductive treatments (e.g. hydroxyurea) are authorized.\n2. Subject must be ineligible for standard cytarabine and anthracycline induction therapy according to the following criteria:\n\n   * Subject aged ≥ 75 years.\n   * OR subject aged between 60 and 74 with at least one of the following comorbidities:\n\n     * ECOG performance status: of 2 or 3.\n     * cardiac history: heart failure requiring treatment, left ventricular ejection fraction ≤ 50%, chronic stable angina.\n     * carbon monoxide diffusion capacity ≤ 65% or forced expiratory volume in one second ≤ 65%.\n     * creatinine clearance between 30 and 45 mL/min/m².\n     * liver damage (not related to AML) with total bilirubin between 1.5 and 3 × upper normal limit.\n     * any other comorbidity deemed by the physician to be incompatible with standard induction chemotherapy.\n3. Patients are eligible for the recommended standard treatment, i.e. a combination of venetoclax and a hypomethylating agent.\n4. Subjects must voluntarily sign and date an informed consent form authorized by the relevant authorities.\n5. The participation of the subject in another interventional study not interfering with the pathophysiological, pharmacological and clinical rationale of this protocol is possible.\n\nExclusion Criteria:\n\n1. blood leukocytes \\>25 G/L.\n2. Subject has already received anticancer treatment (drugs, surgery, radiotherapy) for AML, hematological malignancy or malignant cancer (within the last 2 years).\n3. Subjects with AML with central nervous system involvement or promyelocytic type (AML-M3).\n4. Subject to an uncontrolled intercurrent disease such as:\n\n   * infection (viral, bacterial or fungal) requiring treatment;\n   * symptomatic congestive heart failure;\n   * unstable angina pectoris\n   * cardiac arrhythmia\n   * psychiatric illness or drug addiction that would limit compliance with study requirements (risk of treatment non-adherence or low venous capital).\n5. Documented hypersensitivity to the drugs used to treat the subject.\n6. Subject has been exposed to potent CYP450 inducers or inhibitors (including grapefruit, Seville oranges) within 7 days prior to treatment initiation.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "60 Years",
          "maximumAge": "90 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "adult patients with untreated AML and ineligible for standard cytarabine and anthracycline induction therapy",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
