        },
        "oversightModule": {
          "oversightHasDmc": true
        },
        "descriptionModule": {
          "briefSummary": "This is an open randomized controlled study in children with mental retardation and refractory epilepsy in which treatment with ketogenic diet (KD) is compared with treatment with the antiepileptic drug (AED), not tried by the patient before, which we consider to be the most appropriate AED for the patient.",
          "detailedDescription": "There are two trials in the study:\n\n* To compare the effect of the ketogenic diet with the effect of the most appropriate AED after 4 months\n* To evaluate the effect of the ketogenic diet after 4 and 13 months on the children who have been randomized to this treatment, the seizure frequency is compared with the frequency before start of treatment"
        },
        "conditionsModule": {
          "conditions": [
            "Epilepsy",
            "Mental Retardation"
          ],
          "keywords": [
            "Epilepsy",
            "Children",
            "Mental retardation",
            "Ketogenic diet",
            "Diet"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE4"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 60,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Ketogenic diet",
              "type": "ACTIVE_COMPARATOR",
              "interventionNames": [
                "Dietary Supplement: Ketogenic diet"
              ]
            },
            {
              "label": "AED",
              "type": "ACTIVE_COMPARATOR",
              "description": "Most appropriate antiepileptic drug",
              "interventionNames": [
                "Drug: Antiepileptic drug (AED)"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Ketogenic diet",
              "description": "Ketogenic diet is a very strict high fat diet",
              "armGroupLabels": [
                "Ketogenic diet"
              ]
            },
            {
              "type": "DRUG",
              "name": "Antiepileptic drug (AED)",
              "description": "An AED,not used by the patient before, which we consider to be the most appropriate will be given orally or by gastrostomy. Serum concentration, the body weight, side effects and effects on the epilepsy will be considered when deciding the dose of the AED. Traditions for amount of medicine/kg body weight or optimal serum concentration at our center will be followed. This tradition will be the same as in other major European epilepsy centers but might propose lower, but not higher amounts than recommended by the drug company. Drugs from ACT groups N03A, N05BA, N05CD, H02A or S01EC will be used including prednisolon,levetiracetam, valproate, carbamazepine, oxcarbazepine, topiramate, felbamate, zonisamide, vigabatrin, tiagabil, lamotrigine, pregabalin, rufinamide, clobazam, clonazepam, tiagabine, gabapentin, phenytoin, phenobarbital, ethosuximide, acetazolamide, nitrazepam and other new antiepileptic drugs that might be released during the study period.",
              "armGroupLabels": [
                "AED"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Comparing amount of patients with 100%, >90% and >50% reduction in number of seizures between the two groups of seizures",
              "timeFrame": "4 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Comparing the parents´evaluation of change in quality of life and cognitive function between the two groups. The parents will answer a questionary.",
              "timeFrame": "Four months"
            },
            {
              "measure": "Comparing side effects between the two groups",
              "timeFrame": "Four months"
            },
            {
              "measure": "Comparing change in slow activity and epileptic activity by template matching on 24 hour EEG",
              "timeFrame": "Four months"
            },
            {
              "measure": "Investigating side effects and change in number of seizures, change in EEG, quality of life and cognitive function after 13 months of treatment with the ketogenic diet",
              "timeFrame": "13 months"
            },
            {
              "measure": "Is the effect of the ketogenic diet as good in children with severe mental retardation as in children with less severe learning disabilities?",
              "timeFrame": "4 and 12 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* The patient is mentally retarded\n* The patient has tried at least 3 different AED:s including one combination with two or more different AED:s.\n* The parents are willing to include their child in the study after written and verbal information.\n* Patients with all types of epilepsy can be included.\n* The patient has at least 6 seizures/month.\n* The patient is submitted to our epilepsy center.\n* The seizures are possible to count\n* The patient has either generalized epilepsy, multifocal epilepsy or an epilepsy where it is undetermined whether it is localized or generalized such as Dravet syndrome classified as G40.3-G40.9 in ICD X.\n\nExclusion Criteria:\n\n* The family is expected to have compliance problems with treatment and/or seizure registration.\n* The hospital which have submitted the patient is not willing to accept the inpatient stays and the procedures that are necessary for the project.\n* The patient's seizures are under acceptable control.\n* The patient has got a vagus nerve stimulator implanted within the last 18 months, has started a new antiepileptic drug within the last 2 months or has changed his antiepileptic drugs the last month.\n* The patient has a medical condition, for example a metabolic disease, where ketogenic diet is contraindicated.\n* The patient has a localized epilepsy classified as G40.0-G40.2 in ICD X.\n* The patient's nutritional status is not good enough or intake of fluid is to small to permit treatment with ketogenic diet.\n* The patient has within the last 2 months been using medications or herbal medications that has a considerable effect on glucose metabolism, such as oral glucocorticoids.\n* The patient has within the last 2 months been using medications or herbal medications that has a considerable effect on metabolism of AED:s.\n* The patient uses herbal medicine which can interact with AED or Ketogenic diet.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "2 Years",
          "maximumAge": "15 Years",
          "stdAges": [
            "CHILD"
          ]
        },
        "contactsLocationsModule": {
