      "resultsSection": {
        "participantFlowModule": {
          "recruitmentDetails": "subjects were accrued 2007-2008 in outpatient clinic",
          "groups": [
            {
              "id": "FG000",
              "title": "Arm 1 Enzyme Inducing Antiseizure Drug (+ EIASD) Level 1",
              "description": "subjects on the +EIASD (Level 1) treatment arm were taking one of these antiseizure drugs: phenytoin, carbamazepine, phenobarbital, primidone and oxcarbazepine.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Dose level 1= 750mg/day. NO intrasubject dose escalation.\n\nPharmacokinetics (PK) data will be collected on day one of cycle one infusion"
            },
            {
              "id": "FG001",
              "title": "Arm 2 +EIASD Level 2",
              "description": "subjects on the +EIASD (Level 2) treatment arm were taking one of these antiseizure drugs: phenytoin, carbamazepine, phenobarbital, primidone and oxcarbazepine.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Dose level 2= 1100mg/day. NO intrasubject dose escalation."
            },
            {
              "id": "FG002",
              "title": "Arm 3 +EIASD Level 3",
              "description": "subjects on the +EIASD (Level 3) treatment arm were taking one of these antiseizure drugs: phenytoin, carbamazepine, phenobarbital, primidone and oxcarbazepine.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Dose level 3= 1700mg/day. NO intrasubject dose escalation. Includes pts at the new formulation TC6 at 1700mg"
            },
            {
              "id": "FG003",
              "title": "Arm 4 +EIASD Level 4",
              "description": "subjects on the +EIASD (Level 4) treatment arm were taking one of these antiseizure drugs: phenytoin, carbamazepine, phenobarbital, primidone and oxcarbazepine.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Dose level 4= 2220mg/day. NO intrasubject dose escalation."
            },
            {
              "id": "FG004",
              "title": "Arm 5 Non-Enzyme Inducing Antiseizure Drug (-EIASD) Level 1",
              "description": "Subjects in the -EIASD group were either not being treated with antiseizure drugs or were taking ones that did not significantly induce hepatic enzymes such as gabapentin, lamotrigine, valproic acid, levetiracetam, tiagabine, topiramate, zonisamide and felbamate.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Level 1 = 750mg/day. NO intrasubject dose escalation.\n\nPK data will be collected on day one of cycle one infusion"
            },
            {
              "id": "FG005",
              "title": "Arm 6 -EIASD Level 2",
              "description": "Subjects in the -EIASD group were either not being treated with antiseizure drugs or were taking ones that did not significantly induce hepatic enzymes such as gabapentin, lamotrigine, valproic acid, levetiracetam, tiagabine, topiramate, zonisamide and felbamate.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Level 2 = 1100mg/day. NO intrasubject dose escalation.\n\nPK data will be collected on day one of cycle one infusion"
            },
            {
              "id": "FG006",
              "title": "Arm 7 -EIASD Level 3",
              "description": "Subjects in the -EIASD group were either not being treated with antiseizure drugs or were taking ones that did not significantly induce hepatic enzymes such as gabapentin, lamotrigine, valproic acid, levetiracetam, tiagabine, topiramate, zonisamide and felbamate.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Level 3 = 1700mg/day. NO intrasubject dose escalation. this Arm including pts treated at the new formulation TC6 at 1700mg\n\nPK data will be collected on day one of cycle one infusion"
            },
            {
              "id": "FG007",
              "title": "Arm 8 -EIASD Level 4",
              "description": "Subjects in the -EIASD group were either not being treated with antiseizure drugs or were taking ones that did not significantly induce hepatic enzymes such as gabapentin, lamotrigine, valproic acid, levetiracetam, tiagabine, topiramate, zonisamide and felbamate.\n\nSubjects will take terameprocol for 5 consecutive days each month by IV. Level 4 = 2200mg/day. NO intrasubject dose escalation.\n\nPK data will be collected on day one of cycle one infusion"
            },
