        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Average Annualized Costs",
              "description": "Average annualized overall healthcare costs and epilepsy-related healthcare costs were calculated for each treatment group. Epilepsy-related costs were those with a code for epilepsy. ED, Emergency Department; AMC, All Medical Costs; Ep Rel, Epilepsy Related. United States dollars were consumer price index adjusted for 2009.",
              "populationDescription": "For Arms 1 - 4, Medicaid-enrolled participants with uncontrolled epilepsy (see Arm Descriptions for Arm Title 1 and Arm Title 3) or matched participants with well-controlled or intermediate epilepsy. For Arms 5 - 8, privately-insured participants with uncontrolled epilepsy or matched participants with well-controlled or intermediate epilepsy.",
              "reportingStatus": "POSTED",
              "paramType": "MEAN",
              "dispersionType": "Standard Deviation",
              "unitOfMeasure": "United States dollars",
              "timeFrame": "1 year",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Medicaid, Uncontrolled, Subgroup",
                  "description": "Database records for participants with 2 or more consecutive changes in anti-epileptic drug (AED) therapy occurring at least 30 days apart and followed by 1 or more epilepsy-related inpatient or emergency department (ED) visits within the next 365 days. This subgroup was matched with participant records in the Medicaid, well-controlled cohort"
                },
                {
                  "id": "OG001",
                  "title": "Medicaid, Well Controlled",
                  "description": "Database records for participants with an epilepsy diagnosis but no AED change and no epilepsy-related inpatient or ED visits"
                },
                {
                  "id": "OG002",
                  "title": "Medicaid, Uncontrolled",
                  "description": "Database records for participants with 2 or more consecutive changes in AED therapy occurring at least 30 days apart and followed by 1 or more epilepsy-related inpatient or ED visits within the next 365 days. This arm represents all participant records that met the criteria for uncontrolled epilepsy"
                },
                {
                  "id": "OG003",
                  "title": "Medicaid, Intermediate",
                  "description": "Database records for participants who are not classified as uncontrolled or well controlled"
                },
                {
                  "id": "OG004",
                  "title": "Private, Uncontrolled, Subgroup",
                  "description": "Database records for participants with 2 or more consecutive changes in AED therapy occurring at least 30 days apart and followed by 1 or more epilepsy-related inpatient or ED visit within the next 365 days. This subgroup was matched with participant records in the private, well-controlled cohort."
                },
                {
                  "id": "OG005",
                  "title": "Private, Well Controlled",
                  "description": "Database records for participants with an epilepsy diagnosis but no AED change and no epilepsy-related inpatient or ED visit"
                },
                {
                  "id": "OG006",
                  "title": "Private, Uncontrolled",
                  "description": "Database records for participants with 2 or more consecutive changes in AED therapy occurring at least 30 days apart and followed by 1 or more epilepsy-related inpatient or ED visit within the next 365 days. This arm represents all participant records that met the criteria for uncontrolled epilepsy."
                },
                {
                  "id": "OG007",
                  "title": "Private, Intermediate",
                  "description": "Database records for participants who are not classified as uncontrolled or well controlled"
                }
              ],
