        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Part A Dose-Escalation: Number of Participants Who Experienced Any Serious Adverse Events Related To Vaccine Administration",
              "description": "To assess the safety and tolerability of NMRC-M3V-Ad-PfCA, in a dose-escalation design (Part A), in healthy malaria-naïve adults. Part A was a dose escalation of NMRC-M3V-AdPfCA (2 antigen combination) using two dose groups, 2x10\\^10 pu (Group 1) and 1x10\\^11 pu (Group 2). Subjects received a single intramuscular injection with the injections in the 2 groups staggered by 4 weeks in order to assess the safety and tolerability of the vaccine and define the dose to be used in Part B. The vaccine was to be considered safe and well-tolerated if there were no severe or serious adverse events related to vaccine administration.",
              "timeFrame": "Through Study Completion, an average of 1 year"
            },
            {
              "measure": "Part B Regimen-Comparison: Number of Participants With Any Serious Adverse Events Related to Vaccine Administration",
              "description": "To assess the safety and tolerability of NMRC-M3V-Ad-PfCA, in a regimen-comparison design (Part B), in healthy malaria-naïve adults. Subjects in part B received 2 intramuscular injections given 16 weeks apart: Group 3 NMRC-M3V-Ad-PfCA (2 antigen combination) at a dose of 2x10\\^10 pu, or Group 4 NMRC-MV-Ad-PfC (single antigen) at 1x10\\^10 pu dose. The vaccine was to be considered safe and well-tolerated if there were no severe or serious adverse events related to vaccine administration.",
              "timeFrame": "Through Study Completion, an average of 1 year"
            },
            {
              "measure": "Part B Regimen Comparison: Time to Parasitemia to Assess the Protective Efficacy Against Sporozoite Challenge (Pf, 3D7 Strain)",
              "description": "Protective efficacy was assessed by conducting a homologous 3D7 strain sporozoite challenge 3 weeks after the second NMRCMV-Ad-PfC immunization. Time to parasitemia was measured in both vaccinated and unvaccinated volunteers (infectivity controls) in Group 3 (NMRC-M3V-Ad-PfCA (2 antigen combination) at a dose of 2x10\\^10 pu) and Group 4 (NMRC-MV-Ad-PfC (single antigen) at 1x10\\^10 pu dose). Infectivity control subjects were challenged with Group 3 and Group 4. Each volunteer was monitored for the onset of signs and symptoms of malaria and by daily Giemsa-stained thick blood films with positive films confirmed by a second reader. The identity of immunized and non-immunized volunteers was known to the clinical trial staff but not to the microscopists reading the malaria smears.",
              "timeFrame": "Through Study Completion, an average of 1 year"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Part A Dose-Escalation: To Assess the Immunogenicity of NMRC-M3V-Ad-PfCA in Healthy Malaria-Naïve Adults Using ELISpot IFN-γ Responses",
              "description": "The NMRC-M3V-Ad-PfCA vaccine combines two adenovectors encoding circumsporozoite protein (CSP) and apical membrane antigen-1 (AMA1). In Group 1 healthy volunteers received one intramuscular injection of 2x10\\^10 pu at Week 0 and in Group 2 a five-fold higher dose of 1 x 10\\^11 pu at Week 4. Immunogenicity was assessed by ELISpot IFN-γ responses against synthetic peptides derived from CSP and AMA1 as the range of spot forming cells/million peripheral blood mononuclear cells \\[sfc/m\\].",
              "timeFrame": "One month post immunization"
            },
            {
              "measure": "Part B Regimen-Comparison: To Assess the Immunogenicity of NMRC-M3V-Ad-PfCA in Healthy Malaria-Naïve Adults Using ELISpot IFN-γ Responses in Group 3",
              "description": "The NMRC-M3V-Ad-PfCA vaccine combines two adenovectors encoding circumsporozoite protein (CSP) and apical membrane antigen-1 (AMA1). Group 3 healthy volunteers received 2 intramuscular injections of NMRC-M3V-Ad-PfCA (2 antigen combination) at a dose of 2x10\\^10 pu at Week 16 and Week 32. Immunogenicity was assessed by ELISpot IFN-γ responses against synthetic peptides derived from CSP and AMA1 using peripheral blood mononuclear cells during the study. IFN-γ ELISpot responses were measured as the range of spot forming cells/million peripheral blood mononuclear cells \\[sfc/m\\].",
              "timeFrame": "22-23 days post immunization"
            },
            {
              "measure": "Part B Regimen-Comparison: To Assess the Immunogenicity of NMRC-MV-Ad-PfC in Healthy Malaria-Naïve Adults Using ELISpot IFN-γ Responses in Group 4",
              "description": "Group 4 healthy volunteers received 2 intramuscular injections of NMRC-MV-Ad-PfC (single antigen) at a dose of 1x10\\^10 pu at Week 16 and Week 32. Immunogenicity was assessed by ELISpot IFN-γ responses against synthetic peptides derived from circumsporozoite protein (CSP) using peripheral blood mononuclear cells during the study. IFN-γ ELISpot responses measured as the range of spot forming cells/million peripheral blood mononuclear cells \\[sfc/m\\].",
              "timeFrame": "4 weeks post immunization"
            },
            {
              "measure": "Part A Dose-Escalation: To Assess the Immunogenicity of NMRC-M3V-Ad-PfCA in Healthy Malaria-Naïve Adults Using Intracellular Cytokine Staining of CD4+ and CD8+ T Cell IFN-γ Responses",
              "description": "The NMRC-M3V-Ad-PfCA vaccine combines two adenovectors encoding circumsporozoite protein (CSP) and apical membrane antigen-1 (AMA1). In Group 1 healthy volunteers received one intramuscular injection of 2x10\\^10 pu at Week 0 and in Group 2 a five-fold higher dose of 1 x 10\\^11 pu at Week 4. Immunogenicity was assessed by Intracellular Cytokine Staining of CD4+ and CD8+ T cell IFN-γ responses to AMA1 and CSP using peripheral blood mononuclear cells during the study. CD4+ and CD8+ T cell IFN-γ responses were measured as percentage (%) range of positive responses.",
              "timeFrame": "One month post immunization"
            },
            {
              "measure": "Part B Regimen-Comparison: To Assess the Immunogenicity of NMRC-M3V-Ad-PfCA in Healthy Malaria-Naïve Adults Using Intracellular Cytokine Staining CD4+ and CD8+ T Cell IFN-γ Responses in Group 3",
              "description": "The NMRC-M3V-Ad-PfCA vaccine combines two adenovectors encoding circumsporozoite protein (CSP) and apical membrane antigen-1 (AMA1). Group 3 healthy volunteers received 2 intramuscular injections of NMRC-M3V-Ad-PfCA (2 antigen combination) at a dose of 2x10\\^10 pu at Week 16 and Week 32. Immunogenicity was assessed by Intracellular Cytokine Staining of CD4+ and CD8+ T cell IFN-γ responses to AMA1 and CSP measured using peripheral blood mononuclear cells during the study. CD4+ and CD8+ T cell IFN-γ responses were measured as percentage (%) range of positive responses.",
              "timeFrame": "22-23 days post immunization"
            },
            {
              "measure": "Part B Regimen-Comparison: To Assess the Immunogenicity of NMRC-MV-Ad-PfC in Healthy Malaria-Naïve Adults Using Intracellular Cytokine Staining of CD4+ and CD8+ T Cell IFN-γ Responses in Group 4",
              "description": "Group 4 healthy volunteers received 2 intramuscular injections of NMRC-MV-Ad-PfC (single antigen) at a dose of 1x10\\^10 pu at Week 16 and Week 32. Immunogenicity was assessed by Intracellular Cytokine Staining of CD4+ and CD8+ T cell IFN-γ responses to synthetic peptides derived from circumsporozoite protein (CSP) using peripheral blood mononuclear cells during the study. CD4+ and CD8+ T cell IFN-γ responses were measured as percentage (%) range of positive responses.",
              "timeFrame": "4 weeks post immunization"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "INCLUSION CRITERIA:\n\n* Between the ages of 18-50 (inclusive)\n* Negative results of HIV ELISA, HbSAg, anti-HCV antibody, and no other clinically significant abnormal laboratory results from screening.\n* Adenovirus serotype 5 (Ad5) titer \\<1:500\n* Able to provide written informed consent.\n* Complete an Assessment of Understanding and verbalize an understanding of any questions answered incorrectly.\n* In good general health without clinically significant medical history or physical exam abnormalities at screening.\n* Willing to continue immunogenicity and clinical follow-ups for one year and telephone or mail (electronic/U.S. Postal) contact as long term safety monitoring provision for an additional four years (totaling five years of participation; immunized volunteers only).\n* Male and female participants being immunized and female participants being challenged agree to use effective means of birth control (an FDA approved contraceptive, abstinence) between screening and 60 days following last clinical study visit or able to provide evidence of no reproductive capability.\n\nEXCLUSION CRITERIA:\n\n* Have a history of malaria infection, exposure to malaria infection(i.e. you have been to an area that has malaria within the past two years),lived in a country with malaria for more than 5 years or receipt of certain candidate malaria vaccines\n* Known immune system disease\n* Known blood, heart, liver, kidney disease\n* At known significant risk for developing heart disease\n* A positive result on HIV testing at screening\n* A positive result on Hepatitis B or C testing at screening\n* Removal of your spleen\n* Taking medication that suppresses the immune system within 30 days of immunization.\n* Received or will be receiving another vaccine within 30 days of immunization\n* Received blood products (e.g. transfused with blood cells, platelets, plasma or serum) within 120 days of the immunization\n* Have had serious adverse reactions to other vaccines including hives, anaphylaxis, respiratory difficulty, tongue/mouth/neck/throat/body swelling or abdominal pain\n* Pregnant, breastfeeding, or planning to become pregnant during the next year\n* Plan to participate (or have participated in the last 30 days) in any other research study including an investigational drug or device\n* Unwilling or unable to participate/complete all study elements\n* Evidence of previous infection with adenovirus 5 or prior receipt of an adenovirus containing vaccine.",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "50 Years",
          "stdAges": [
            "ADULT"
          ]
        },
