      "resultsSection": {
        "participantFlowModule": {
          "groups": [
            {
              "id": "FG000",
              "title": "Group 1: NMRC-M3V-Ad-PfCA, 2x10^10 pu",
              "description": "Part A is a dose escalation of NMRC-M3V-Ad-PfCA (2 antigen combination) using 2 dose groups: Group 1 received a single low dose of 2x10\\^10 pu and Group 2 received a single high dose of 1x10\\^11 pu. Injections were staggered by 4 weeks in order to assess the safety and tolerability of the vaccine and define the dose to be used in Part B."
            },
            {
              "id": "FG001",
              "title": "Group 2: NMRC-M3V-Ad-PfCA, 1x10^11 pu",
              "description": "Part A is a dose escalation of NMRC-M3V-Ad-PfCA (2 antigen combination) using 2 dose groups: Group 1 received a single low dose of 2x10\\^10 pu and Group 2 received a single high dose of 1x10\\^11 pu. Injections were staggered by 4 weeks in order to assess the safety and tolerability of the vaccine and define the dose to be used in Part B."
            },
            {
              "id": "FG002",
              "title": "Group 3: NMRC-M3V-Ad-PfCA, 2x10^10 pu",
              "description": "Part B is the challenge phase to assess protective efficacy. Subjects in part B received 2 intramuscular injections given 16 weeks apart: Group 3 NMRC-M3V-Ad-PfCA (2 antigen combination) at a dose of 2x10\\^10 pu, or Group 4 NMRC-MV-Ad-PfC (single antigen) at 1x10\\^10 pu dose. Infectivity control subjects were challenged with Group 3 and Group 4."
            },
            {
              "id": "FG003",
              "title": "Group 3: Infectivity Control",
              "description": "Infectivity control subjects were challenged with Group 3"
            },
