        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Part A Dose-Escalation: Number of Participants Who Experienced Any Serious Adverse Events Related To Vaccine Administration",
              "description": "To assess the safety and tolerability of NMRC-M3V-Ad-PfCA, in a dose-escalation design (Part A), in healthy malaria-naïve adults. Part A was a dose escalation of NMRC-M3V-AdPfCA (2 antigen combination) using two dose groups, 2x10\\^10 pu (Group 1) and 1x10\\^11 pu (Group 2). Subjects received a single intramuscular injection with the injections in the 2 groups staggered by 4 weeks in order to assess the safety and tolerability of the vaccine and define the dose to be used in Part B. The vaccine was to be considered safe and well-tolerated if there were no severe or serious adverse events related to vaccine administration.",
              "reportingStatus": "POSTED",
              "paramType": "COUNT_OF_PARTICIPANTS",
              "unitOfMeasure": "Participants",
              "timeFrame": "Through Study Completion, an average of 1 year",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Group 1",
                  "description": "Group 1 received NMRC-M3V-Ad-PfCA (2 antigen combination) at a single low dose of 2x10\\^10 pu on Week 0"
                },
                {
                  "id": "OG001",
                  "title": "Group 2",
                  "description": "Group 2 received NMRC-M3V-Ad-PfCA (2 antigen combination) at a single high dose of 1x10\\^11 pu on Week 4."
                }
              ],
              "denoms": [
                {
                  "units": "Participants",
                  "counts": [
                    {
                      "groupId": "OG000",
                      "value": "6"
                    },
                    {
                      "groupId": "OG001",
                      "value": "6"
                    }
                  ]
                }
              ],
              "classes": [
                {
                  "categories": [
                    {
