                      ]
                    }
                  ]
                }
              ]
            },
            {
              "type": "PRIMARY",
              "title": "Part B Regimen-Comparison: Number of Participants With Any Serious Adverse Events Related to Vaccine Administration",
              "description": "To assess the safety and tolerability of NMRC-M3V-Ad-PfCA, in a regimen-comparison design (Part B), in healthy malaria-naïve adults. Subjects in part B received 2 intramuscular injections given 16 weeks apart: Group 3 NMRC-M3V-Ad-PfCA (2 antigen combination) at a dose of 2x10\\^10 pu, or Group 4 NMRC-MV-Ad-PfC (single antigen) at 1x10\\^10 pu dose. The vaccine was to be considered safe and well-tolerated if there were no severe or serious adverse events related to vaccine administration.",
              "reportingStatus": "POSTED",
              "paramType": "COUNT_OF_PARTICIPANTS",
              "unitOfMeasure": "Participants",
              "timeFrame": "Through Study Completion, an average of 1 year",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Group 3",
                  "description": "2 doses of NMRC-M3V-Ad-PfCA (2x10\\^10 pu) administered intramuscular 16 weeks apart on Week 16 and Week 32"
                },
                {
                  "id": "OG001",
                  "title": "Group 4",
                  "description": "2 doses of NMRC-MV-Ad-PfC (1x10\\^10 pu) administered intramuscular 16 weeks apart on Week 16 and Week 32"
                }
              ],
              "denoms": [
                {
                  "units": "Participants",
                  "counts": [
                    {
                      "groupId": "OG000",
                      "value": "20"
                    },
                    {
                      "groupId": "OG001",
                      "value": "15"
                    }
                  ]
                }
              ],
              "classes": [
