            {
              "type": "PRIMARY",
              "title": "Part B Regimen Comparison: Time to Parasitemia to Assess the Protective Efficacy Against Sporozoite Challenge (Pf, 3D7 Strain)",
              "description": "Protective efficacy was assessed by conducting a homologous 3D7 strain sporozoite challenge 3 weeks after the second NMRCMV-Ad-PfC immunization. Time to parasitemia was measured in both vaccinated and unvaccinated volunteers (infectivity controls) in Group 3 (NMRC-M3V-Ad-PfCA (2 antigen combination) at a dose of 2x10\\^10 pu) and Group 4 (NMRC-MV-Ad-PfC (single antigen) at 1x10\\^10 pu dose). Infectivity control subjects were challenged with Group 3 and Group 4. Each volunteer was monitored for the onset of signs and symptoms of malaria and by daily Giemsa-stained thick blood films with positive films confirmed by a second reader. The identity of immunized and non-immunized volunteers was known to the clinical trial staff but not to the microscopists reading the malaria smears.",
              "reportingStatus": "POSTED",
              "paramType": "GEOMETRIC_MEAN",
              "dispersionType": "Full Range",
              "unitOfMeasure": "days",
              "timeFrame": "Through Study Completion, an average of 1 year",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Group 3",
                  "description": "2 doses of NMRC-M3V-Ad-PfCA (2x10\\^10 pu) administered intramuscular 16 weeks apart on Week 16 and Week 32 followed by a sporozoite challenge 3 weeks later. Infectivity control subjects (not vaccinated) were also challenged."
                },
                {
                  "id": "OG001",
                  "title": "Group 3 Infectivity Control",
                  "description": "Infectivity control subjects (not vaccinated) were also challenged"
                },
                {
                  "id": "OG002",
                  "title": "Group 4",
                  "description": "2 doses of NMRC-MV-Ad-PfC (1x10\\^10 pu) administered intramuscular 16 weeks apart on Week 16 and Week 32 followed by a sporozoite challenge 3 weeks later. Infectivity control subjects (not vaccinated) were also challenged."
                },
                {
                  "id": "OG003",
                  "title": "Group 4 Infectivity Control",
                  "description": "Infectivity control subjects (not vaccinated) were also challenged"
                }
              ],
