          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Group 1",
              "type": "EXPERIMENTAL",
              "description": "Group 1: n=20, randomized to receive 16 g Pfs25-EPA/Alhydrogel (n=10) or the comparator (EuvaxB, n=10) on D0, D56",
              "interventionNames": [
                "Biological: Pfs25-EPA/Alhydrogel",
                "Biological: Euvax B"
              ]
            },
            {
              "label": "Group 2",
              "type": "EXPERIMENTAL",
              "description": "Group 2: n=30, randomized to receive 47 g Pfs25-EPA/Alhydrogel (n=15) or the comparator (EuvaxB and Menactra , n=15) on D0, D56, D112, D480",
              "interventionNames": [
                "Biological: Pfs25-EPA/Alhydrogel",
                "Biological: Euvax B",
                "Biological: Menactra"
              ]
            },
            {
              "label": "Group 3",
              "type": "EXPERIMENTAL",
              "description": "Group 3: n=70 randomized to receive 47 g Pfs25-EPA/Alhydrogel (n=35) or the comparator (EuvaxB and Menactra , n=35) on D0, D56, D112, D480",
              "interventionNames": [
                "Biological: Pfs25-EPA/Alhydrogel",
                "Biological: Euvax B",
                "Biological: Menactra"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Pfs25-EPA/Alhydrogel",
              "description": "The Pfs25-EPA conjugate was produced by reaction between thiolated PpPfs25 and maleimideactivated EcEPA, followed by purification using size-exclusion chromatography. The cGMP Pfs25-EPA conjugate Lot# WRAIR1634 was manufactured at Walter Reed Bioproduction facility in cGMP compliance in May 2010. Alhydrogel (Brenntag, Denmark) is an aluminum hydroxide gel and has been extensively used as an adjuvant in licensed human vaccines. Alhydrogel is supplied as a sterile product in water without preservatives. Pfs25- EPA/Alhydrogel WRAIR Lot #1668 was manufactured and filled as single-use vials at Walter Reed Bioproduction facility in cGMP compliance in October 2010. Each vial contains 78 g/mL conjugated Pfs25, 93 g/mL conjugated EPA and 1600 g/mL Alhydrogel in a volume of 0.8 mL. The vial label reads: 78 g/mL Conjugated Pfs25 on Alhydrogel .",
              "armGroupLabels": [
                "Group 1",
                "Group 2",
                "Group 3"
              ]
            },
            {
              "type": "BIOLOGICAL",
              "name": "Euvax B",
              "description": "Euvax B consists of highly purified, noninfectious particles of HBsAg absorbed onto aluminum salts as an adjuvant and preserved with thimerosal.",
              "armGroupLabels": [
                "Group 1",
                "Group 2",
                "Group 3"
              ]
            },
            {
              "type": "BIOLOGICAL",
              "name": "Menactra",
              "description": "Menactra , Meningococcal (Groups A, C, Y and W-135) Polysaccharide Diphtheria Toxoid Conjugate Vaccine, is a sterile, intramuscularly administered vaccine that contains Neisseria meningitidis serogroup A, C, Y and W-135 capsular polysaccharide antigens individually conjugated to diphtheria toxoid protein. N meningitidis A, C, Y and W-135 strains are cultured on Mueller Hinton agar (3) and grown in Watson Scherp (4) media. The polysaccharides are extracted from the N meningitidis cells and purified by centrifugation, detergent precipitation, alcohol precipitation, solvent extraction and diafiltration.",
              "armGroupLabels": [
                "Group 2",
                "Group 3"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
